final _nb_Lesson21 = Lessons(
    lessonNumber: 21,
    lessonTitle: 'Moderation',
    lessonBody:
        '''Aim: To present a balanced Christian Life through the principle of moderation.

Introduction: A well known Bible teacher once said, " Truth pushed too far becomes an error". This statement carries a powerful truth that needs a serious consideration by all Christians. We have heard of many cases of extreme and fanatical practices of some Christians that bring reproach and shame to the Name of Christ, rather than the glory to His Name. Well- meaning Christians can avoid these pitfalls only if they learn the principle of moderation.

I. What is the Meaning of Moderation?

A. It means that the experience and daily walk of a believer should never lead him to extremes, fanaticism, unseemly manifestations, backbitings and murmurings.

B. B. Positively, it means being sober, thoughtful, balanced, mellow, forgiving, steadfast, humble, self - sacrificing and Christlike.

II. Biblical Basis of the Principle of Moderation

A. Philippians 4:5 – “ Let your gentleness be evident to all. The Lord is near.”

B. Ephesians 4:14-15 – “Then we will no longer be infants, tossed back and forth by the waves, and blown here and there by every wind of teaching and by the cunning and craftiness of people in their deceitful scheming. Instead, speaking the truth in love, we will grow to become in every respect the mature body of him who is the head, that is, Christ.”

C. I Corinthians 13:5 - “It does not dishonor others, it is not self-seeking, it is not easily angered, it keeps no record of wrongs.

D. Colossians 3:12,13 - “Therefore, as God’s chosen people, holy and dearly loved, clothe yourselves with compassion, kindness, humility, gentleness and patience.”

III. Areas where we can Apply Moderation

A. Spiritual gifts
B. Doctrines
C. Religious Observance
D. Personal preference
E. Habits
F. Personal Liberty
G. Temperament

IV. Conclusion Our life as a Christian will become balanced, wholesome, and well - rounded if we apply the principles of moderation.
''');

final _nb_Lesson22 = Lessons(
    lessonNumber: 22,
    lessonTitle: 'Overcoming Fear',
    lessonBody:
        '''Aim: To help the believers understand that they have the power to overcome fear.

Introduction:

“ Fear stifles our thinking and actions. It creates indecisiveness that results in stagnation. I have known talented people who procrastinate indefinitely rather than risk failure. Lost opportunities cause erosion of confidence, and the downward spiral begins.”
--Charles Stanley

"Don't be afraid to see what you see." - Ronald Reagan

After Adam sinned in the garden, fear became the dominant force in his life. The first words he spoke to God were, "I was afraid..." ( Gen. 3:10 ).

The faith he had in his heart was turned into fear.

Satan is a fallen angel. He has no creative power. He cannot create. He can only destroy. Satan just perverted the Laws that were already there.

Sin is righteousness perverted. Fear is faith perverted. Hate is love perverted. The force we know in this earth as fear originally Adam's faith.

I. ANY FEAR SATAN CAN BRING TO OUR MINDS IS A FEAR OF FAILURE OF GOD'S PROMISE, SINCE THERE IS A PROMISE THAT COVERS EVERYTHING IN LIFE.

1. Fear of death is actually a fear that John 11:26 is not True.
2. Fear of being alone is actually a fear that John 14:16 is not True.
3. Fear of Sickness is actually a fear that 1 Peter 2:24 is not True.
4. Fear of financial failure is actually the fear that Philippians 4:19 is not true.


II. SOME TRUTHS IN OVERCOMING FEAR.
1. II Timothy 1:7, the source of fear is not God. God has given you power, love and sound mind. Fear is from Satan. What you must do now is apply the force of God's Word to your mind and renew your your thinking to the Word of God. By spending time in the word of God, you will re- program your thinking from fear to Faith, from death to life, from sickness to health , from poverty to prosperity.

2. Psalm 118:6 The Lord is on my side; I will not fear. If God says, " Fear not " that means you don't have to fear. Your confession in every situation in your life is important.

3. I John 4:18 - perfect love (the kind of love Christ has for us ) casts out fear. Walking in love will get rid of fear. When you realize that you are walking in the commandment of God, there is nothing to be afraid of. Fear has no authority over you.

Conclusion: Fear is the absence of faith while faith is the absence of fear. As children of God, we need to continually rely and depend on His promises, the truth contained in the Scriptures.
''');

final _nb_Lesson23 = Lessons(
    lessonNumber: 23,
    lessonTitle: 'The Christian Home',
    lessonBody: '''Aim: To present clearly God's design for the home.

Introduction:
The Christian church cannot flourish without the Christian home - the backbone of the nation, the salt of civilization.

A young doctor, his wife and three children couldn't find a house to live in so they had to stay in a hotel. A friend said to the six - year old girl, "Too bad you have no home." "Oh, yes we have a home," she replied promptly, “but no house to put in."


I. GOD-FEARING FATHERS
1. God has placed the husband as the head of the home.
Ephesians 5:23
23 For the husband is the head of the wife as Christ is the head of the church, his body, of which he is the Savior.

Abraham commanded his household which included the wife, children and servants . This is God's order and the home that reverses it, breaks God's plan and destroy the peace in the home.

2. It is the husband's duty to love his wife.
Ephesians 5:25
25 Husbands, love your wives, just as Christ loved the church and gave himself up for her

- Loving in health, in sickness, in poverty and in prosperity.

3. Fathers must provide to their family.
1 Timothy 5:8
8 If anyone does not provide for his relatives, and especially for his immediate family, he has denied the faith and is worse than an unbeliever.

4. The husband is the priest of the whole family and is responsible to establish a
family altar (set a family devotion ).

Job offered for the whole family.
Job 1:5
5 When a period of feasting had run its course, Job would send and have them purified. Early in the morning he would sacrifice a burnt offering for each of them, thinking, "Perhaps my children have sinned and cursed God in their hearts." This was Job's regular custom.


II. GOD- FEARING MOTHERS

Almost all great men have been made by one or two loving women - a godly mother or a devoted wife.

1. Good wives and good mothers are wonderful gifts from the Lord.
Proverbs 19:14
14 Houses and wealth are inherited from parents, but a prudent wife is from the Lord.

Prudent - wise or judicious in practical affairs;
- careful in providing for the future; provident: a prudent decision.

They become a tremendous blessing to their husbands and families.

Proverbs 31:10-12
10 A wife of noble character who can find? She is worth far more than rubies. 11 Her husband has full confidence in her and lacks nothing of value. 12 She brings him good, not harm, all the days of her life.

2. The Wife's duty is to submit to their husband.
Ephesians 5:22
22 Wives, submit to your husbands as to the Lord. 24 Now as the church submits to Christ, so also wives should submit to their husbands in everything. Sarah was very exemplary –

1Peter 3:6.
6 like Sarah, who obeyed Abraham and called him her master. You are her daughters if you do what is right and do not give way to fear.

The reason for this is given in:
1 Timothy 2:11-15
11 A woman should learn in quietness and full submission. 12 I do not permit a woman to teach or to have authority over a man; she must be silent. 13 For Adam was formed first, then Eve 14 And Adam was not the one deceived; it was the woman who was deceived and became a sinner. 15 But women will be saved through childbearing-if they continue in faith, love and holiness with propriety.

3. The Wife's duty is to love the husband and the children.
Titus 2:4
3 Likewise, teach the older women to be reverent in the way they live , not to be slanderers or addicted to much wine, but to teach what is good. 4 Then they can train the younger women to love their husbands and children, 5 to be self-controlled and pure, to be busy at home, to be kind, and to be subject to their husbands, so that no-one will malign the word of God.


III. GOD-FEARING CHILDREN

1. Children are precious heritage from the Lord.
Psalm 127:3
3 Sons are a heritage from the Lord, children a reward from him.

2. Children must be brought to the Lord at an early stage.
Matthew 19:13-14
13 Then little children were brought to Jesus for him to place his hands on them and pray for them. But the disciples rebuked those who brought them. 14 Jesus said, "Let the little children come to me, and do not hinder them, for the kingdom of heaven belongs to such as these."

3. Children must be trained -
Proverbs 22:6
6 Train a child in the way he should go, and when he is old he will not turn from it.

4. Children must obey the parents.
Ephesians 6:1-3
1 Children, obey your parents in the Lord, for this is right. 2 “Honor your father and mother”—which is the first commandment with a promise— 3 “so that it may go well with you and that you may enjoy long life on the earth.”

IV. CONCLUSION

The home is the greatest construction. Only a Christian Home displays a complete fulfillment of God's plan of matrimony. A family that desires to establish a truly “Christian Home" should learn to submit to God's blue - print as contained in His word.
''');

final _nb_Lesson24 = Lessons(
    lessonNumber: 24,
    lessonTitle: 'The Christian Marriage',
    lessonBody: '''Aim: To present clearly God's design for marriage.

Introduction:  Marriage is the oldest human institution. It is older than the church and the government.

John Stott gave a Biblical definition of marriage. "Marriage is an heterosexual covenant between one man and one woman, ordained and sealed by God preceded by a public leaving of parents, consummated in in sexual union, issuing in a permanent mutually supportive partnership and normally crowned by the gift of children."

"A successful marriage required falling in love many times, always with the same person" -Mignon Mc Laughlin


I. REASONS FOR MARRIAGE
A. To obey the command of God. Gen.1:28

“ God blessed them and said to them, “Be fruitful and increase in number; fill the earth and subdue it. Rule over the fish in the sea and the birds in the sky and over every living creature that moves on the ground.”

B. For Fellowship Gen. 2:18

The LORD God said, “It is not good for the man to be alone. I will make a helper suitable for him.”

C. For Partnership Ecclesiastes 4:9-11

“Two are better than one, because they have a good return for their labor: If either of them falls down, one can help the other up. But pity anyone who falls and has no one to help them up. Also, if two lie down together, they will keep warm. But how can one keep warm alone?”

D. For the propagation of the human race. Genesis 1:28, 9:1

“Then God blessed Noah and his sons, saying to them, “Be fruitful and increase in number and fill the earth.”


II. THE BIBLICAL BASIS OF MARRIAGE IN MARK 10:6-9

“But at the beginning of creation God ‘made them male and female.’ ‘For this reason a man will leave his father and mother and be united to his wife, and the two will become one flesh.’[So they are no longer two, but one flesh. Therefore what God has joined together, let no one separate.”

1. Marriage is to be Monogamous - one man, one woman relationship under God

2. Marriage is to be Heterosexual - the divine pattern indicates a male and a female relationships

3. Marriage involves a distinct union. The two shall be one flesh.

4. Marriage is permanent. What therefore God has joined together,let no man put asunder. (see also Matt. 19:6)


III. Conclusion:

Marriage is sacred because it is of divine planning. It originated in the greatest Mind - God's. Contracting parties of the said union should therefore be faithful to the vows they have made before God and before men.
''');

final _nb_Lesson25 = Lessons(
    lessonNumber: 25,
    lessonTitle: 'Soul Winning or Witnessing',
    lessonBody:
        '''Aim: To share the urgency of winning souls for the Kingdom of God. (Ephesians 5:16 – “redeeming the time, because the days are evil)

Introduction: "You will always want to tell someone about Him. The wise writer of the book of Proverbs said that he that wins a soul is wise. He didn’t say he that knows about soul wining or he that preaches about soul wining. It is he that wins souls that Is wise." Seasoned Life Journal

One major reason why God saved us is in order to serve Him. John 15:16 points us to the fact that Christ has chosen us and has ordained us to bear fruit. It is the plan of God, therefore, for each one of us to be His instrument in sharing His message of salvation.

John 15:16 “You did not choose me, but I chose you and appointed you to go and bear fruit-fruit that will last. Then the Father will give you whatever you ask in my name.”


I WHAT DOES EVANGELISM MEAN?

A. Evangel means " good news"

B. Evangelism - is sharing or proclaiming the good news of salvation through the Lord Jesus Christ.

C. However, our purpose must not only be sharing the Gospel to unbelievers, but to win them and become followers of Jesus Christ.

Matthew 28: 19-20”Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit, and teaching them to obey everything I have commanded you. And surely I am with you always, to the very end of the age."


II BASIC REASONS WHY WE NEED TO WIN SOULS

A . A command of Christ

Matt. 28:19”Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit.”
Mark 16:15He said to them, "Go into all the world and preach the good news to all creation.

B. Compassion for the lost. Matthew 9:36

“When he saw the crowds, he had compassion on them, because they were harassed and helpless, like sheep without a shepherd.”

C. Shortness of Time.  John 4:35

“Do you not say, 'Four months more and then the harvest'? I tell you, open your eyes and look at the fields! They are ripe for harvest.”

Ephesians 5:16
“Redeeming the time, because the days are evil. “


III HINTS ON HOW TO WITNESS

A. Two Things to remember clearly:

1. We are introducing Jesus to the people.
2. Jesus is the answer to everyone's personal needs.

B. Basic Needs of an individual.

1. To be loved.
2. To be served.
3. To be a success.
4. To be creative.


IV. CONCLUSION / APPLICATION
A. Pray that God will lead you to someone who is receptive to the gospel.

B. Before we evangelize, we must:
1. Have a genuine born - again experience.
2. Know the basic idea of salvation.
3. Live a consistent Christian life.
''');

final _nb_Lesson26 = Lessons(
    lessonNumber: 26,
    lessonTitle: 'Divine Healing pt.1',
    lessonBody:
        '''Aim: To share the biblical concept and blessing of Divine Healing.

Introduction:
Jeremiah 30:17 "For I will restore health to you, and I will heal you of your wounds, said the LORD; because they called you an Outcast, saying, This is Zion, whom no man seeks after."

Acts 10:38 "How God anointed Jesus of Nazareth with the Holy Ghost and with power: who went about doing good, and healing all that were oppressed of the devil; for God was with him."

Many believers, because of lack of knowledge from God's Word concerning the subject, are robbed of the tremendous blessing of Divine healing. It is ironic that some Christians are acquainted with demonic- inspired healing , like spiritist healing, quack – healing, etc., rather than Biblical divine healing. Some Christians have gone to the point of denying the healing ministry of God by saying that the age of miracles has already passed.

But what does the bible say about Divine Healing?


1. REASONS WHY WE BELIEVE THAT DIVINE HEALING IS ALSO FOR TODAY.
A. Jesus Christ is the same yesterday, today and forever. Hebrews 13:8
“Jesus Christ is the same yesterday and today and forever.”

B. Jesus promised healing will accompany them that believe in His Name. Mark 16:16-17, Romans 10:17
16 “Whoever believes and is baptized will be saved, but whoever does not believe will be condemned. 17 And these signs will accompany those who believe: In my name they will drive out demons; they will speak in new tongues;”

17 “ So then faith comes from hearing, and hearing by the Word of God.”

C. Healing is part of the Atoning work of Christ. Isaiah 53:4-5
4 “Surely he took up our pain and bore our suffering, yet we considered him punished by God, stricken by him, and afflicted. 5 But he was pierced for our transgressions, he was crushed for our iniquities; the punishment that brought us peace was on him, and by his wounds we are healed.”

D. We are not only saved from sin but also from sicknesses.  1Peter 2:24
24 “He himself bore our sins” in his body on the cross, so that we might die to
sins and live for righteousness; “by his wounds you have been healed.”

Healed in 1 Pet 2:24 is “iathete” in Greek, occurring also in James 5:13-16

“13 Is anyone among you in trouble? Let them pray. Is anyone happy? Let them sing songs of praise. 14 Is anyone among you sick? Let them call the elders of the church to pray over them and anoint them with oil in the name of the Lord. 15 And the prayer offered in faith will make the sick person well; the Lord will raise them up. If they have sinned, they will be forgiven. 16 Therefore confess your sins to each other and pray for each other so that you may be healed. The prayer of a righteous person is powerful and effective.


2. HOW TO RECEIVE DIVINE HEALING.

A. Recognize that sickness and diseases are of the devil John 10:10a
10 “The thief comes only to steal and kill and destroy…”

B. Know that God wants to heal you. It is His will. John 10:10b
“…I have come that they may have life, and have it to the full.”

C. Ask in Faith claiming the promise in God's word. James 5:15
“And the prayer of faith shall save the sick, and the Lord will raise him up; and if he has committed sins, they shall be forgiven them.”

D. Use the Mighty Name of Jesus to rebuke sickness and in claiming the healing.
John 16:23-24 –
23 “In that day you will no longer ask me anything. Very truly I tell you, my Father will give you whatever you ask in my name. 24 Until now you have not asked for anything in my name. Ask and you will receive, and your joy will be complete.”
Mark 16:17-18 –
17 And these signs will accompany those who believe: In my name they will drive out demons; they will speak in new tongues; 18 they will pick up snakes with their hands; and when they drink deadly poison, it will not hurt them at all; they will place their hands on sick people, and they will get well.”

E. Receive the Healing by faith according to Mark 11:24 –
24 “Therefore I tell you, whatever you ask for in prayer, believe that you have received it, and it will be yours.”


3. CONCLUSION/ APPLICATION

The Biblical concept of Divine Healing will become a reality only when you begin to appropriate it in actual situation. Pray that God will use you in ministering healing to the sick.
''');

final _nb_Lesson27 = Lessons(
    lessonNumber: 27,
    lessonTitle: 'Divine Healing pt.2',
    lessonBody:
        '''Aim: To share the biblical concept and blessing of Divine Healing.

Introduction:
"May your spirit, soul and body be kept safe, sound and without blame.." -1Thess. 5:23

God wants us whole (that is, without mental illness, emotional wounds or physical sickness). He desires wholeness in our spirit, soul and body. Sin damages us. Sin damages others – often those we love. Sin can cause illness of spirit, soul and body. Only God can heal these three different parts of our lives (spirit, soul and body) and make us whole again.

What hope and comfort Jesus' words bring to the broken soul when He says: "Go in peace, your faith has made you whole" (Luke 7:50, 8:48).

Yes, God wants to heal the broken and bruised parts of our lives. The Holy Spirit wants every part of our beings to be safe, sound and strong. He desires to bring life and power to our spirits, restore our souls and bring healing to our bodies. These are the blessings which "our great salvation" provides for each one of us.


A. SPIRIT, SOUL AND BODY: THERE IS A DIFFERENCE

It will help us in understanding the topic of this section "Healing For The Soul," if we first study the three parts of man.

The spirit relates upward to God. The soul relates inward to itself. The body relates outward to the world.

For three-part man to be whole, each part must be in harmony with the others. Every part has a special role or function to play in the well-being of every person.

Some Bible students believe there is no difference in meaning between the words "spirit" and "soul." They say both terms refer to that part of man which is not physical or material.

1. What Scripture Shows

It is true that some Scripture verses use either term in that general way. However, in other verses each of these words is used with a special and distinct meaning. The writer of the Book of Hebrews plainly states that there is a difference between the spirit and the soul of man:

"The word of God is alive and powerful. It is sharper than a sword with two cutting edges. It can cut deeply and swiftly. In so doing, it divides or separates the soul from the spirit…" –Hebrews 4:12

Note that the Word of God divides… soul… from … spirit, making them separate and distinct entities within us.

Paul points out the difference between the two terms in his first letter to the Corinthian church:

"The natural [soulish] man does not receive the things of God's Spirit. To him they are foolish. He cannot understand them because they can only be judged spiritually…. Only the spiritual man can make such judgment…" -1 Cor 2:14, 15.

Note the distinction between the soulish man and spiritual man.

2. What Language Shows

Let us look at the Greek terms in the New testament for spirit, soul and body.
a. Pneuma. The Greek word for "spirit" is pneuma. It means "breath." The lung disease" pneumonia" takes its name from that term.

b. Psuche. The Greek word for "soul" is psuche. "Psychology," therefore is the study of the soul (mind) of man.

c. Soma. Finally, the Greek term for "body" is soma. ""Psychosomatic" (soul-body) diseases are disorders of the body which are caused by mental and emotional (soul-related) problems.


B. These are three Greek terms that have been carefully traced through the New Testament Scriptures. In regard to man's makeup, they are used as follows.

1. Spirit (pneuma) –

The "spirit" is that part of man which is aware or conscious of God – God-awareness. It is made "alive" by God's Spirit at salvation. It is "energized" by God's Spirit when we are filled with the Spirit.

The functions of the spirit include the following.
a. Revelation from God
b. Prayer to God
c. Communion with God
d. Worship of God
e. Witness to man (world)
f. Memory: to recall (remember, reflect)
g. Imagination: to create (envision, dream)
h. Conscience: to judge (discern)
i. Curiosity: to inquire (explore)
j. Perception: to interpret (sense and understand)
k. Fellowship with God (church)
l. Discernment of spirits (spiritual senses)
m. Spiritual warfare
n. Seedbed for the fruit of the Spirit
o. Reception area for the Gifts of the Spirit.

2. Soul (psuche) –

The "soul" is that part of man which is aware or conscious of himself – self-awareness. It is the center of the ego or personality. The functions of the soul can be outlined as follows:
a. Reason: to think (meditate, conceive)
b. Emotion: to feel (have passion, affection)
c. Volition: to will (decide)

3. Body (soma) –

The "body" is the part of man which is aware of and reacts with the outside world – world-awareness. The functions of the body can be outlined as follows.

a. Reception. Information is received from the world by way of the senses (eyes, ears, touch, etc.)
b. Reaction. The body reacts through the motor (muscle) system by words and actions.
c. Expression. The body can express to the world the thoughts, feelings and decisions of the soul.


C. SPIRIT, SOUL, AND BODY: HOW THEY RELATE

We might put these thoughts together in the following way:

1. Soul and Body

Our body receives information (through seeing with our eyes, hearing with our ears, smelling with our nose) by the soul. (To "perceive" means to interpret, judge and understand what we have received. To do so, we must rely upon our reason and our memory.)

How we think and feel about a situation will determine what action we will take. In other words, our will or volition now comes to play. We then will do something or say something (a body response). So our soul works with our body and our body with our soul.

2. Spirit and Soul

These relationships of man's three-part being are understood as follows:

The spirit of man is not fully functional because of sin. Before being born of the Holy Spirit (born-again), man's spirit is incapacitated – that is, it doesn't function properly in harmony with God's Spirit.

By being baptized in the Holy Spirit, he receives the spiritual power (or spirit power) he now needs to live his new life in Christ.

3. Holy Spirit and Soul

"The natural [soulish] man does not receive the things of God's Spirit. To him they are foolish. He cannot understand them because they can only be judged spiritually" – 1Cor 2:14

It is God's purpose that all the functions of man's soul come under the Lordship (governance) of the Holy Spirit. The fruit, gifts and graces given by the Holy Spirit enable the newborn babe in Christ to grow up in the Lord and start obeying God and His Word.
If we grieve the Holy Spirit by natural, soulish ways of living, we will hold back the flow of God's Spirit through our lives. We then fall back into our old (soulish-sensual) way of life.

The Bible calls this being "carnal," or in the "flesh" (see Romans 8:5; Galatians 5:16-26).


D. SPIRIT, SOUL AND BODY; WHAT GOD HAS DONE

Apart from the work of the Holy Spirit in our spirit, we will follow the desires or lusts of the flesh. This is the mark of the "natural" or "soulish" man.

Our desires, however, is to be like Jesus. In His humanity He was the perfect man. He was "spiritual" because He was like us – totally man in spirit, soul and body – He can relate to us in our human needs and sorrows.

1. Our Relationship To God.

On the cross, He completed "our great salvation."
When He cried out, "It is finished," the work of the redemption was done.
Salvation was secured for the spirit, soul and body of man:

a. Justified. Our spirits have been "justified" – made right with God.
b. Sanctified. Our souls are being "sanctified" – made holy before God.
d. Glorified. Our bodies shall be "glorified" – made eternal by the Spirit of God.

Yes, our salvation in Christ covers our total life experience – past, present and future.

2. Our Relationship To Sin

a. We were saved from the "penalty" of sin.
b. We are being saved from the "power" of sin.
c. We shall be saved from the "presence" of sin.


E. CONCLUSION

The following passage by Paul now takes on added interest for us:

"The body that is sown in death is a natural [psuche] body. However, it will be raised a spiritual [pneuma] body. If there is a natural body, there is also a spiritual body." -1Cor 15:44

Paul is telling us that the bodies we now live in here on earth are "soul-bodies." The bodies we will have in Heaven will be "spirit-bodies."

Jesus was raised from the dead by the Holy Spirit. His body after His resurrection was probably a spiritual (pneuma) body.

He said, "Behold I live and am alive forever more." –Rev 1:18. By that statement, He meant He would never die. He had a (pneuma) spiritual body - one that would live forever.

At our resurrection, we too will have a (pneuma) spiritual body, and our whole being – spirit, soul, and body – will be made perfect in Christ Jesus.

The above should explain all we need to know about spirit, soul and body. This will prepare us for our topic, "Soul Sickness."
''');

final _nb_Lesson28 = Lessons(
    lessonNumber: 28,
    lessonTitle: 'Divine Healing pt.3',
    lessonBody:
        '''Aim: To share the biblical concept and blessing of Divine Healing.

Introduction:
The meaning of the Greek word “sozo” (salvation) includes the idea of health, healing and wholeness for spirit, soul and body.

Sickness of the soul is a common problem of mankind. Soul sickness or soul injury is referred to by the term "broken-hearted." This term issued to describe the inner hurts of the soul.

Jesus said: "… the Spirit of the Lord is upon me… to heal the broken-hearted [wounded soul]"

We are told in the Twenty-third Psalm that the Good Shepherd of our lives will "restore" our souls.

This is an important topic, for whatever destroys the soul can finally destroy the body. Sickness of soul can produce sickness of body. A breakdown of the emotions and mind will lead to a breakdown in the body. We truly need to have our souls restored.
As we have seen, the functions of the soul include our mind, emotions, imagination and even our memories.

Many Christians suffer from scars on their souls. They retain many painful memories from the past.

As a result, they doubt the present and fear the future. They may have answers in their heads, but it is hard to think straight when one's heart is hurting.

I think we all would agree that many of us need an "inner healing" of the soul. Our minds, memories and emotions need to be made whole. I have called this the "release of the soul."


A. GOD WANTS US WHOLE
Healing of the whole man is a process. It begins by meeting Jesus as our Savior and our Baptizer in the Holy Spirit. This results in our having a new heart and a free spirit.
God always starts at the center of our being- that is, our spirit. He first touches our spirit with His Spirit. After our spirit is released, our soul can be restored.

God begins in our spirit (sometimes called the inner-man or innermost being; see John 7:37, 38). Then He desires to work His way into our soul to heal and restore it.
He wishes to bring His life and healing power to our spirit, soul and body – that we might be "blameless" (sound and complete) when He comes.

1. Spirit, Soul and Body: Our Health
As we have said, the functions of the spirit, soul and body are related to one another. A healthy "spirit" is the sound foundation for a healthy "soul". healthy "soul" favors a healthy "body."

It works the other way as well. It is difficult to be at our best spiritually if we are emotionally or physically sick. If we are ill in mind or body, it can affect our work and witness for God. Our relationship with God's Spirit is safe and secure, but the flow of His Spirit through our lives to the world can be limited.

We have been created to function as "whole" persons. I believe the Apostle John refers to this truth in one of his letters:
"Dear friend, I pray that you may prosper and be in health even as your soul prospers" -3 John 2.

This verse teaches us that physical health is related to the well-being of one's soul. In other words, a healthy soul-life is necessary for a healthy body-life.

2. Spirit, Soul and Body: Our Healing
Our bodies tend to follow the lead which is taken by our souls. And our souls follow the lead taken by our spirits.

Spiritual (spirit) problem produces mental and emotional (soul) problems; these in turn produce physical (body) problems. The links between our spirit, soul and body truly form an unbroken chain.

One cannot solve a psychological (soul) problem by treating the body alone. Likewise, one cannot solve a spiritual problem by dealing only with the mind or emotions.

This is why some treatments by doctors and psychologists fail. The root reasons in the soul and/or spirit which are producing the problems have not been rooted out.

This is true even of healing prayer in some cases of bodily disease. After prayer, the person may seem to be healed. Body pain and physical symptoms may be gone for a time.. However, if deep needs of the soul (emotions) and spirit have not been met, physical problems may soon show up again.

I have seen this happen many times in the ministry of the healing-evangelists. Many people have been totally healed and have never suffered from their physical problems again.

However, others have kept coming back for prayer. They kept "losing" their healing after a short period of time.

Many in the ministry are not aware of the deeper levels of need in the souls of the people.

Yes, God wants us well. He wants us to be whole in spirit, soul and body. But there must be total work of healing – one which moves from within to without (starting in the spirit, continuing into the soul and expressed finally in the body).
Otherwise, only a limited or partial healing occurs which will not last. For this reason, we wish to study the kinds of hurt which can damage the soul of man.


B. SOUL SICKNESS
There are many things which can place lasting injury upon our souls.

I – CAUSED BY:

1. Our Parents. For example, many children suffer because of the faults and failures of their parents. The Scriptures tell us that children are to be taught and trained in love (Eph. 6:4). Unkind, unfair or unwise words and actions can cause either fear or anger in the hearts of children.
a. Physical Abuse. Some parents are very harsh and critical. They never praise or encourage their children. Some even resort to physical abuse and cruel beatings.
In such cases, it is not just the body which suffers. The soul (personality and emotions) can be severely damaged as well. These inner-scars are often carried into adult life.

b. Emotional Abuse. Far worse than the welts and wounds of physical abuse are the unseen wounds of overly critical parents which injure the soul.

Those who have been hurt in this way grow up and become adults with many emotional problems. It affects their relationships with other people – in the family, at school and work, and even within the church.
Many children thus suffer from a very low sense of self-esteem. They cannot picture themselves being successful at anything. They are afraid to take on new duties or even prepare themselves for a better position in life.

They have been put down (berated or criticized) so many times, they have lost hope. They live under a cloud of self-doubt and personal insecurity.

Everyone has a few feelings such as these from time to time. However, some have been damaged so badly, they cannot live a normal life.

2. Our Sins. God's laws of love and morality were given for our well-being. They came from His Father-heart because He cares for His children. He gave us the rules (laws) to keep us from injury, hurt and pain. When we break His moral laws, this results in our hearts (soul) being broken. When you break God's laws, you end up with a broken (injured, wounded) heart (soul).

Not only do we suffer, but others suffer as well. Our sins affect others, and their sins affect us. The consequence (result) of breaking God's law is often hurt and pain for innocent children. They are not to blame at all for their pain and suffering.
Did you have a parent who drank alcoholic beverages to excess? Such parents sometimes beat and injure their children in their drunken stupor. The child suffers (though innocent and guilty of no wrong-doing).

a. Sexual Sins. Moral sin and compromise also injure and damage the soul. The Old Testament strongly stated the truth in this way:
"Whoever commits adultery with a woman is a total fool, for he is destroying his own soul. He will be both wounded and disgraced – and his shame will never be wiped away" –Proverbs 6:32, 33.

What Society Says. Sadly, modern society want to lift all moral limits in regard to sexual relationships. Some modern-day "fools" say that as long as no none objects, any kind of sexual activity is all right.

Adultery, homosexual activity, sex with children, and other shameful practices are not seen as wrong. They are all within the personal "rights" of each individual. Such activities are called marks of "maturity" and personal "freedom" by these modern-day moral lepers.

What God Says. God's Word plainly forbids such immoral behavior, and warns people of the painful results-both to the individual and to society.
God's principles of morality are for our well-being and personal happiness. They are also for the good of society as a whole.

To violate or break the laws of God does not bring true freedom. In fact, we come under a bondage which in the end will only lead to death and destruction.

In the downward process, there will be much pain at every level – spiritually, mentally, emotionally, and physically. This is true for the individual and for society as a whole.

Results. Modern society is already beginning to reap a horrible harvest from the sinful seeds it has sown: Broken homes, hearts and marriages; confused and abused children; unwed mothers and abortions; dread sexual disease.

And God grieves because man hurts. It is a pain which is produced by man's rebellion against God's divine laws of love. To ignore this truth is to invite tragedy – because all this immorality wounds and destroys the soul.

3. Other Sins. Further light on the causes of soul injury can be found in these words form the pen of the Apostle Peter:

a. What Scripture Says. "Dear friends, you are only visitors in this world. Therefore, I beg you to resist and remove yourselves from the strong desires and lusts of the flesh. These things war [are the enemies which will destroy and fight] against your soul" -1Peter 2:11

Peter is saying that if we give in to the strong desires of the flesh, these sins (like enemy warriors) will seek to destroy our emotions, mind and thinking ability. As a result, the soul will be injured, bruised and broken.

b. Results. Our inner life rests upon a foundation of reason and emotion. When our emotions have been damaged, it is difficult to think properly. Painful memories are woven into our hearts and minds. We can't' clearly see or understand ourselves or others. The future is filled with fearful images.

Our imagination holds mental pictures or "images" of what is going to happen. The color and character of these pictures is controlled by the will-being of our soul life.
When "it is well with our soul," the future is bright and filled with hope and faith.

However, if our minds, memories and emotions are still scarred by painful events of the past, the scene is quite different. The picture will be painted with the dark colors of fear, doubt, resentment, jealousy and self-pity.

No wonder a God of love gives us divine guidelines by which to live. He knows the pain we will suffer if we follow our own fleshly desires or lusts.

4. Works of the Flesh. In his letter to the Galatians, Paul lists some of the works of the flesh which can so severely damage the soul. We might do well to give them special attention (Galatians 5:19-21):

a. Adultery– sex with someone other than your spouse;
b. Fornication – sex with unmarried persons;
c. Uncleanness – impure thoughts, words and deeds, homosexuality;
d. Lasciviousness – selfish and shameless behavior;
e. Idolatry – worship of idols and false gods;
f. Witchcraft – the use of magical demonicpower;
g. Hatred – bad temper;
h. Variance – trouble – making, fighting;
i. Emulations - being jealous;
j. Wrath – anger;
k. Strife – arguing;
l. Seditions – causing divisions;
m. Heresies – false teaching;
n. Envying – wanting what someone else has;
o. Murders – killing people;
p. Drunkenness – using strong drink(liquor/whiskey);
q. Reveling – wild and wasteful parties.


II EFFECTS ON:
1. Ourselves. The works of the flesh are planned by the devil to damage the soul. We will be left weakened and wounded within. Our lives will be robbed, wasted and even destroyed. A nation which permits and encourages such "soulish" activities through magazines, newspapers and cinema films is committing social suicide. It is sowing the seeds of death and destruction among its people.

2. Our Society. At the personal level, the final results are mental, emotional and physical breakdowns. At the social level, moral standards fall and the crime rate rises.

This is the sad state in which we find much of our world today. Hospitals, prisons and other social institutions are filled to overflowing. When the people of a nation are sick in their souls, all of society suffers as well.


III WE HAVE A CHOICE

Jesus warned His disciples that the devil has come to "steal and destroy." He then declares: "But I have come that you may have life-full and overflowing" –John 10:10

1. Life or Death. The choice is clear: It is one between life and death – the fruit of the Spirit or the works of the flesh. When a society ignores or willfully breaks God's laws, it is opening the doors to the devil himself.

The results are tragic at every level of life – whether it be the individual, family, community or nation.

"Blessed is the nation whose God is the Lord…" –Psalm 33:12. How sad it is when a nation founded on godly principles shuts God out of its public life. When moral values are lowered in the schools and on television, there is a price to pay. Sin is not cheap – it costs a great deal to serve the devil.

2. Draw Near to God. When we draw near to God, He draws near to us (Jas 4:8). When we shut God out of our lives, we shut ourselves off from the protection of His presence. He will honor our choice and give us over to our wicked ways.

"God shows His anger from heaven. His anger is against evil and wicked men who push away the truth… So he gives them up to the fleshly lusts which dishonor their body… He gives them over to their evil ways… that they might get paid in their own souls and bodies the terrible penalty which they deserve" –Romans 1:18, 24, 26, 27


CONCLUSION
Yes, we see all around us the results of man's wicked ways. Sin is like a sword which pierces deep within the soul of man.

But there is hope. It is found in God's Word. In His grace, He has provided healing for man's sin-scarred body and soul. He wants us well for both our good and His glory.
''');

final _nb_Lesson29 = Lessons(
    lessonNumber: 29,
    lessonTitle: 'Divine Healing pt.4',
    lessonBody:
        '''Aim: To share the biblical concept and blessing of Divine Healing.

Introduction:
There are two processes of healing for the body: natural and supernatural (divine). Medical doctors know they cannot heal. They only assist the "natural" healing powers already in the body.
But Jesus is greater that other physicians. By His supernatural power, sick bodies can also be healed. The divine power for such healing comes directly from God.


A. TWO SOURCES OF HEALING.
The same two sources for healing also apply to the soul. It is said that time heals. This natural healing that occurs with the passage of time does help us outgrow some of the inner hurts which were such problems during our younger years.

1. NATURAL
We find out in time that not everybody is stronger, smarter and better looking than we are. Most of us learn to relate to others and succeed in our fields of work. We gain the respect of our families, friends and fellow workers.
As we grow in years, we face grief, sorrow and losses with understanding. Even those with mental illness often recover by themselves over a period of time. It seems the soul has natural healing powers, as does the body.
Some people however, do not outgrow their problem of early life. They carry their painful scars on into adulthood. All of us probably have some hurts we recall from the past which affect our present attitudes and actions.
For some, however, the carryover is so great, they can hardly function in a normal way. Many such people have suffered mental or emotional breakdowns. When wounds are deep, the results may be lifelong.
Psychologists and psychiatrists are doctors who treat mental and emotional disorders. They seek, through medicine and counsel to assist the natural healing powers of the soul.
However, just as there are physical diseases which cannot be cured, so there are sicknesses of the soul which cannot be helped in natural ways. To "restore" such a soul would take a "miracle" – a supernatural healing.
I know of young people who have "burned" their brains and damaged their souls on drugs. At one time they were bright, healthy youngsters with much to look forward to in life.
Now they are broken in spirit, mind and body. Is there any hope, or is it too late? Only a miracle can meet such a need. Praise God, there is hope.
Our Lord is the mighty God of miracles and mercy!

2. SUPERNATURAL
Let us look at these gracious words from the prophet Isaiah:
"Share what you have with the hungry. Meet the needs of those who are afflicted – who suffer the inner pain of being rejected. Then your light shall rise in the darkness, and your night will be as the noonday" Isaiah 58:10
The pain of being rejected (or put away – divorced) can be healed only by love and acceptance. God desires to reach out to the "afflicted" through you and me – through our hearts and hands.

A. DAVID EXPERIENCED HEALING. David spoke for us all in his hour of inner pain when he cried out: "Lord, have mercy on me. Heal my soul, for I have sinned against you" –Psalm 41:4
David knew personally about this healing love of God, or he could never have written the Twenty-third Psalm: "The Lord is my shepherd… He has restored [healed] my soul."
Later on, the Psalmist speaks of God's grace in these beautiful words:
"The Lord heals the brokenhearted and binds up their wounds – curing their pains and their sorrows… Great is our Lord and mighty in power. His understanding is without limit. He lifts up the humble – those who have been put down…" Psalm 147:3,5,6

B. JESUS BROUGHT HEALING THEN. There is special passage in the gospels which I have seen in a new light. I should like to share it with you, for it speaks of the nature of our Lord's healing ministry:
"Jesus went about all of Galilee preaching the gospel of the kingdom… and he healed every kind of disease and sickness. The report of his healing power spread throughout Syria. Therefore, they also brought to him people with many different diseases and torments. Others suffered from demon possession, epilepsy, and paralysis. And he healed the all" – Matthew 4:23, 24
It is of interest to note the that the Scriptures say that Jesus healed "every kind" of sickness and disease (vs 23). This included spiritual, mental, emotional and physical problems. Verse 24 names some of the diseases related to each part of man's total being:
1. Spiritual sickness – demon possession;
2. Emotional sickness – torments;
3. Physical sickness – paralysis.

C. GOD HEALS TODAY. Jesus went about making men and women completely whole. Wherever sin had broken into – spirit, soul or body – Jesus forgave, cleansed and brought the healing power of God's love.
I think of my good friend, Costa Deir. When God found him in the depths of sin, he was hopeless case. Alcohol had damaged his brain, liver, heart and digestive system. Satan had robbed him of his friends and family. The devil had destroyed his body, and was after his soul.
He was spiritually, mentally and physically sick – and about to die. Then he met the greatest physician in the entire world – the Lord Jesus Christ.
And what did Jesus do? He made him completely whole – a new creature – in spirit, soul and body. Hallelujah! No wonder he now wants to tell the whole world about the healing power of God's love.


B. FIVE STEPS TO HEALING THE SOUL
Yes, God wants us well. But what is the process by which "inner healing" can come to our lives? I believe there are five important steps we can prayerfully take in faith.
The first three of the five steps for healing of the injured soul can be found in these words of hope and comfort by Jesus:
• "Come to me, all you who are weary and under a heavy load, and I will give you rest.
• "Take my yoke upon you, and
• "Learn of me, for I am meek and lowly. Then you will find rest [restoration] for your souls" -Matt 11:28
1. COME TO JESUS
The first step for inner healing (or healing for the soul) is this: Come to Jesus! Jesus invites us to come to Him.
If we go anywhere else, or look to any other source, we will be let down and disappointed. To whom do you turn in your time of need? Jesus says: "Come unto me…"
Yes, Jesus waits with open arms and bids us to come to Him. There is also welcome for the lost sinner.
As said before, we need to be forgiven and set free from the heavy load of guilt and condemnation. This is where "inner healing" begins. We all must come to Jesus as our Savior. Without this first step, we can never take the second. We must repent if we want to be restored.

2. TAKE HIS YOKE
The yoke of Christ refers to His governance (control) over our lives. He must not only be our Savior, but also our Lord and Master.
The devil wants to deceive us with a lie. He wants us to believe that we will lose our "freedom" when we give our life to the Lord. He will never tell us that his yoke of sin becomes heavier and more painful the longer we carry it.. In the end, we will fall beneath its weight. Only God's grace can truly set us free.
Many Christians suffer under the weight of a yoke of their own making. It is the weight of a self-willed life. They have confessed Christ as their Savior. They want to go to Heaven when they die. However, they also want their won way in many areas of their life here on earth.
God sometimes lets us have our way to teach us a lesson. We soon will find that it becomes a very injurious road. To walk in the "flesh" includes many painful falls. Each one leaves a scar on our souls, as we have already seen.
Clearly, this kind of inner pain can be healed only as we turn to Jesus and confess Him as the Lord of our life. To our joy we will find that His yoke is easy and light – as feathers are to a bird.
Total submission of our lives to Jesus means a total healing of our lives by Jesus. Moreover, it is the only way to true spiritual freedom.
When our faith, hope and plans for the future are linked with the Lord, our inner strength will be renewed and restored. Then we can freely soar without tiring – as on the wings of an eagle! –Isaiah 40:30, 31

3. Learn of Him
When Jesus is the Lord of our lives, we become His disciples. A disciple is one who watches, listens and learns from his teacher. What is it that w can learn from Jesus about the healing of our soul (inner healing)?
We might wonder: Was Jesus ever in circumstances (places) where His soul was injured and wounded? If He was, how did He respond to such pain? How was His soul restored?

a. He suffered. Jesus is the perfect pattern or model for our life. If we can discover how He – in His humanity – met such problems, we can find the solution for ours. Let us turn to God's Word for our answers. The scene of Jesus' wounding begins in the Garden of Gethsemane:
"And he took with him Peter, James and John. Soon he began to show great grief and distress of mind – and was deeply depressed.
"Then he said to them, 'My soul is very sad, and my heart is almost breaking with sorrow. I feel as if I am about to die. Please stay with me and watch and pray'" – Matt 2:37, 38
The awful hours that followed on Calvary were described by the prophet Isaiah. He speaks of our Lord's body being beaten, that our bodies might be made whole: "By his stripes we are healed" –Isaiah 53:5
I believe He also suffered in His soul – that our souls might be healed.
Listen to these further words from the prophet's pen: "He shall see the travail and suffering of his soul, and be satisfied… for he has poured out his soul unto death…" Isaiah 53:11, 12
As said above, this terrible prophecy was fulfilled during the events of Christ's crucifixion. Not only did He suffer in body, but His soul was hurt as well. He was forsaken by His disciples and rejected by the Jews.
They mocked Him, pulled His beard and slapped His face. He was laughed at, spat upon and brought to a place of open shame before the people. The religious leaders of the day loudly jeered, while He suffered in pain.
What more could have been done to make His agony of soul any worse? Just one thing – to be forsaken by His heavenly Father! There could be no greater hurt to a human heart. Yet it had to be. It was the price He had to pay for the penalty of our sin.
Not only was the heart of His Son broken, but so was the heart of the Father in Heaven. "The sinless soul of God's Son became sin – for he took our sin – that we might become right and holy before God" -2Cor 5:21
How terrible must have been this cry from the lips of Jesus as it echoed from earth to Heaven: "My God, my God, why have you forsaken me?" –Mark 15:34. Truly, when the sword was thrust into the side of Jesus, it was more that just blood and water which poured forth: "For he poured out his soul unto death…" Isaiah 53:12. Yes, the Lord Jesus offered His soul, that we might have healing for ours. Without a doubt, He experienced every hurt known to the soul of man.

b. He Forgave. The stress and strain on His soul during those awful hours must have been terrible. How did He keep His inner being in victory? What was it that protected His soul form destruction?
I believe the answer can be found in His response to His "tormentors" – the cruel leaders and soldiers at the foot of the cross: "Father, forgive them, for they don't know what they are doing." Luke 23:34
What was it that protected and restored His soul? It was forgiveness! Truly, this is what we must learn from Jesus – how to forgive. It is the main key to inner healing.

c. We Must Forgive. Do you remember the story Jesus told about the man who had been forgiven a large debt by his master? Yet he himself would not forgive someone who owed him a much smaller debt.
His master was very angry when he learned about his unforgiving spirit. Therefore, he had him thrown into prison to be "tormented" by his jailers.
Jesus replied the story in a very personal way: "So shall my Father do to you, if in your heart you refuse to forgive your brothers" (see Matthew 18:30-35)
What did Jesus mean by this? If we fail to forgive another, a root of resentment can begin to grow in our souls. In time, it will bear very bitter fruit. If we hold on to "hard or hurt feelings" towards someone, our souls will suffer.
In time, the pain will bring torment to all parts of our life – a life that becomes a hell on earth. Forgiveness is the key that unlocks the cell in that hell.
The Psalmist was speaking of Jesus when he said: "You will not leave my soul in hell, or let your Holy One see decay and destruction" – Psalm 16:10
Our souls can actually rot and decay in the Hell of unforgiveness. Hell couldn't hold the Lord Jesus, because He already held the key of forgiveness in His nail-scarred hand.
If you are suffering from the soul sickness of resentment, look to Jesus for the grace of forgiveness. It is a sure, fast remedy that can bring healing to your soul.
Speak out these words: "Father, forgive them- and forgive me – right now for Jesus' sake and in His Name, I pray. Amen." It shall be so!


4. COME AS LITTLE CHILDREN
After forgiving those who have hurt and injured us, we are ready for our next step toward inner healing. We are to come to Jesus as little children.
Our support from Scripture comes from Mark's gospel. Parents were bringing their little children to Jesus to be touched and blessed. The disciples were upset this action because it was robbing them of their time with Jesus.
Therefore, they reproved the parents and tried to send the little children away. Jesus was very displeased with their action and spoke these words to the disciples:
"Let the little children come to me, for the kingdom of God belongs to such as they. Don't send them away. Indeed, whoever does not receive the kingdom of God as a little child,shall not enter it at all" –Mark 10:14, 15
There is healing power, for the whole person in the Kingdom of God. Jesus showed that throughout His earthly ministry. However, to receive that healing power we must come as little children.

A. EARLY MEMORIES NEED HEALING.
Many of the scars on our soul came from events in our early years as children. To these were added other injuries which we received as we grew up into adulthood.
I believed that becoming as a little child includes going back in our memories to our early years. What we are, and how we feel and think today, is a product of all of our past years added together.
Many of us have shadows from the past that darken our present-day lives. They can be traced to painful soul-injuries that occurred in years gone by. They have so damaged our mind and emotions, it is difficult to fully enter into our new life in Christ.

B. HOLY SPIRIT BRINGS HEALING. However, we now have a new Spirit within, which can bring the healing power of Jesus to those places of inner hurt.
With the help of the Holy Spirit, picture yourself in your mind as a little child with Jesus. See yourself walking back through memory lane with the Lord. You don't have to be afraid to face anything, any place or anyone when Jesus is by your side. He doesn't want to hurt you, but to heal you from painful events that occurred in the past.
He will show you why you feel and act as you do when faced with certain situations.
We often have reflex feelings when we face something which reminds us of a hurtful or shameful part of the past. Sometimes we are not directly aware of the cause, but the emotional response is still there. We feel the same way each time.
The Lord wants to reach the roots of those painful reflexes. He desires to heal those memories with His love and understanding. Sometimes we recall the people who caused the wound in our soul. It could be a parent or other family member. Teachers and other authority figures sometimes abuse their right to rule over the lives of others.
It helps to understand that many times such people are sick in their own souls They too have been hurt in the past. So they use the power of their position to build up their own low sense of self esteem.
In such cases, the Lord assures us of His love for us, and the special place we have in God's family. Then He reveals to us how much He wants to bring His love and forgiveness to everyone.
To be touched with that kind of love brings healing to our hearts. We are able to receive His forgiveness and be set free from feelings of resentment or self-pity. Moreover, that love enables us to forgive and release others to God's grace and mercy.

C. FORGIVENESS BRINGS HEALING

1. The Story of a Young Wife and Mother. I recall a young wife and mother in one of our World MAP Summer Conferences. She was driven by a wandering, gypsy spirit. At times, she would suddenly leave her husband and children and drive the family automobile miles from home.
Once, she had gone over a thousand miles before she was found and place in the ward of a local hospital. Finally, it was arranged for her to come to one of our meetings for prayer.
The Lord gave one of our team leaders a Word of Knowledge (revelation knowledge from the Holy Spirit) into the cause of her behavior. She had lived through a series of events in her girlhood which had seriously damaged her soul.

a. She Suffered. She had been born in Europe during World War II. Before the age of six, she had been physically and emotionally abused by both her mother and father. Later, the starving parents abandoned her to take care of herself.
The war was a fearful period of time I her life. She lived through many bombing raids, not knowing whether she would live or die. She searched through garbage cans for food, and slept wherever she found some form of shelter. She finally joined a gypsy group and went with them as they wandered from place to place. The gypsy "spirit" took hold of her.

b. She Forgave. In the course of time, she came to America, found the Lord, and was married. Still, she was tormented by bad dreams, and driven by these sudden and strange desires to wander like a gypsy without reason or notice. It took a revelation from the Lord to uncover the cause of her soul-injury.
After prayer, counseling and ongoing support, she was able to forgive those who had abused her. Over period of time, the hurt in her heart was healed. God restored here soul and removed the pain from her tragic past. She became a nurse, ministering to the sick and suffering. Praise the Lord!

2. Lessons From the Life of Joseph. As we have seen, the role forgiveness is most important in receiving inner healing. A beautiful example of inner healing and forgiveness is found in the Old Testament story of Joseph (see Genesis 37-46)

a. He suffered. You recall that he was given special favor and attention by his father, Jacob. As a boy, he was told by God in a dream that one day he would be a great ruler. His brothers were very jealous, and finally sold him as a slave into Egypt. The wife of his master failed in an attempt to lead him into sexual sin. In her anger, she lied about his conduct, and had Potiphar, her husband, put Joseph in a dungeon.
Joseph began as a boy with the promise of a bright future. He ended up as a hopeless man in a dark prison. The Scripture says he was put in chains of iron: "and the iron entered into his soul" –Psalm 105:18mp
Betrayed, sold into slavery, falsely accused, forgotten in a prison, he was tried by the Word of the Lord. In the natural , he had every reason to be angry, bitter, resentful and even destroy himself by self-pity and despair. But he didn't.
Such situations will either make us "bitter" or "better." It depends on how we respond. The choice is ours. How did Joseph respond?

b. He Forgave. We know the rest of the story. Joseph was given important duties even while in prison. After thirteen years in prison, he was the only person in Egypt who could interpret Pharaoh's dream. As a result, he was placed by Pharaoh in a position of great authority and power. He became a ruler over all of Egypt.
God then brought his brothers back to him. What did he do? Rise up in anger? Destroy them in a fit of rage fired by years of resentment? No, he fed them and forgave them!
What brought forth such a noble response on the part of Joseph? I don't believe Joseph's action was hasty or by chance. It wasn't something that just happened because it seemed like a "good idea" at the time. It was an action born out of his character like that.
When Joseph saw his brothers, he had been in Egypt for some twenty-three years. He was a lad of seventeen when he arrived. That's plenty of time to become "bitter" or "better.

D. GOD MEANS IT FOR GOOD. I believe that Joseph held on to God's word and dream for his life. That was his hope. He had a divine destiny. Therefore, all things would finally work together for that good purpose. Tat revelation kept him faithful and forgiving. You recall his words of divine wisdom to his brothers:
"Don't be afraid, for I am not in God's place as a judge. You meant to harm and hurt me, but God meant it for good. His purpose was to bring life to many people. So don’t be afraid, I will take care of you and your children.' In this way Joseph comforted them, and spoke kindly to their hearts" Gen 50:19-21 smf
1. Joseph Trusted God. There is yet another truth about inner healing that we can learn from Joseph's life. After his rise to power in Egypt, he was given Asenath, the daughter of Potiphera, to be his wife. You will note that the name of his wife's father is very similar – both in meaning and sound – to that of his former master, Potiphar.
a. God Healed His Memories. Any leftover hurt or resentment in Joseph's heart concerning Potiphar could easily have become a great problem. Just the sight of his father-in-law – or even the mention of his name – could have brought to Joseph's mind the painful years of his unfair punishment in prison. How many people suffer form this kind of "carry-over" from the past?
In God's grace, Joseph had been healed from all of the cruel and unfair pain of his past. This is clearly seen in the names of his first two sons, Manasseh and Ephraim. –Gen 41:51, 52
Manasseh means "making to forget" Joseph explains the choice of this name with these wonderful words: "For God has made me forget all the pain, toil and trouble of my youth – and my father's household" (vs 51 smf) God healed the memory of Joseph.
b. God Made Him Fruitful. Ephraim – the name of his second son – means "fruitful" Joseph adds these thoughts form his heart: "For God has caused me to be fruitful in the land of my pain and affliction." (vs 52)
God hasd not only removed the pain from Joseph's memories; He did something else. He actually took the evil events in Joseph's life and turned them into great good – for Joseph and for God! God's eternal prupose was being worked out in time through Joseph's life. Nothing was lost or wasted. God make you fruitful in your land of pain and affliction. Allow Him in to heal you.

5. COMMIT YOUR SOUL TO GOD
God wants not only to heal our past hurts, but also to give us a bright hope for the future. We can trust Him to protect us from the kinds of inner injury which would damage our souls in the days to come.
The ready grace of His forgiveness can quickly put out the fires of anger, resentment, jealousy, fear and self-pity – before they can hurt us or harm others. Our soul can be at peace, and we can rejoice in His great love for us. In this we can find a true sense of self-worth. Like Joseph, we too have an eternal destiny – in Christ Jesus.
Perhaps, dear reader, your heart has been greatly moved by a hope for healing deep within your own soul. Accept this as the gentle work of the Holy Spirit preparing you for the release you so deeply desire.

a. Jesus Will Reveal. You may have tried before, on your won, to search out things from the past. But because it only led to deeper depression, you set it all aside. This time, try coming to Jesus – and let Him do the searching of your soul. He is wise, loving and very gentle. He can bring to your mind the parts, places and persons of past which need His healing touch. Again, we say Jesus wants to restore your soul and make you whole. Do not fear.

b. Jesus Will Heal. A member of our ministry team, Dr. Robert Frost (who left this life to walk with Jesus in 1992), tells this story:
"I speak this words from personal experience. I once tried to uncover the hurts of my past in my own strength and wisdom. It only made matters worse.
"I finally came to the Lord and simply said: 'I am going to trust You, Holy Spirit, to reveal to me what I need to know. Do it in Your way, and in Your time.'
"Three days later, the Lord brought something to my mind that I had long forgotten. I saw myself as a little boy in the midst of a very sad situation. I had been rejected, and put aside in a most unkind and unloving way.
"I saw myself under a dark stairway at school with tears running down my face. I was looking to God for help, because I had been hurt and wounded within.
"In faith, I brought the Lord Jesus right into that part of my past. I asked Him to heal that painful memory. I pictured Jesus in my mind coming in love to that little boy. I saw Jesus put His arm around me as His little brother and heal my pain. In His strong arms I felt safe, secure, and most of all – loved.
"That inner healing has given me a great love for others who have deep scars in their soul. That is why I can say with great feeling – and with great faith: Come to Jesus just as if you are a little child. Take His yoke of love upon you, and learn of Him. Let Him bring forgiveness and healing to your heart even now."


C. CONCLUSION
This biblical prayer can help you:
" Intimately examine me, O God, and know my innermost emotions: [soul]; investigate and test me as metal that is being refined, and know my thoughts, memories and opinions;
"And see if there be any mental pain sorrow or painful toil in me, as I have walked the course of my life; and govern, guide and lead me in my journey and manner of living, always and without end" –Ps 139, 24 lit amp
If the Lord shows you "any mental pain, sorrow or painful toil," bring it to Him . Let Him heal your soul. Jesus promised:
"Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest[oration] unto your souls" –Matthew 11:29
''');

final _nb_Lesson30 = Lessons(
    lessonNumber: 30,
    lessonTitle: 'The Word of God',
    lessonBody:
        '''Aim: To impart to the believer the importance of the Word of God in Christian growth.

Introduction:
" Within the covers of the Bible are the answers for all the problems men face." Ronald Reagan

"A thorough knowledge of the Bible is worth more than a college education." Theodore Roosevelt

The aim of a christian disciples is to grow morel like Jesus. As our human body needs food daily in order to become strong and mature.


I. THE IMPORTANCE OF THE WORD OF GOD.
A. The Word of God is our spiritual nourishment.
Matthew 4:4
4 But he answered and said, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God.

1Peter 2:1,2
2 As newborn babes, desire the sincere milk of the word,
that ye may grow thereby: KJV

2 Like newborn babies, crave pure spiritual milk, so that by it you may grow up in your salvation, NIV

B. The Word of God is our light.
Psalm 119:105
105 Your word is a lamp to my feet and a light for my path.

C. The Word of God is our weapon.
Hebrews 4:12
12 For the word of God is living and active. Sharper than any double-edged sword, it penetrates even to dividing soul and spirit, joints and marrow; it judges the thoughts and attitudes of the heart.

D. The Word of God is the Truth that will set us free.
John 8:32
32 Then you will know the truth, and the truth will set you free."

E. The Word of God is our Equipper.
2 Timothy 3:16,17

16 All Scripture is God-breathed and is useful for teaching, rebuking, correcting and training in righteousness,
17 so that the man of God may be thoroughly equipped for every good work.

F. The Word of God is our source of life and health.
Proverbs 4:20-22
20 My son, pay attention to what I say; listen closely to my words.
21 Do not let them out of your sight, keep them within your heart;
22 for they are life to those who find them and health to a man's whole body.


II. How was the Bible Written?
A. 1 Peter 1:20-21
20 Above all, you must understand that no prophecy of Scripture came about by the prophet's own interpretation.
21 For prophecy never had its origin in the will of man, but men spoke from God as they were carried along by the Holy Spirit.

B. 2 Timothy 3:16

16 All Scripture is God-breathed and is useful for teaching, rebuking, correcting and training in righteousness,
17 so that the man of God may be thoroughly equipped for every good work.


III. THE AUTHORITY OF GOD'S WORD
A. It is guaranteed by God.
Jeremiah 11:1-4
1 This is the word that came to Jeremiah from the LORD:2 "Listen to the terms of this covenant and tell them to the people of Judah and to those who live in Jerusalem.3 Tell them that this is what the LORD, the God of Israel, says: 'Cursed is the man who does not obey the terms of this covenant-4 the terms I commanded your forefathers when I brought them out of Egypt, out of the iron-smelting furnace.' I said, 'Obey me and do everything I command you, and you will be my people, and I will be your God.

Isaiah 55:11
11 so is my word that goes out from my mouth: It will not return to me empty, but will accomplish what I desire and achieve the purpose for which I sent it.

B. It is eternal or permanent.
Psalm 119:89

89 Your word, O LORD, is eternal; it stands firm in the heavens.


IV. APPLICATION

A. Hear -
Romans 10:17
17 Consequently, faith comes from hearing the message, and the message is heard through the word of Christ.

B. Read
Isaiah 34:16
16 Look in the scroll of the LORD and read: None of these will be missing, not one will lack her mate. For it is his mouth that has given the order, and his Spirit will gather them together.

C. Study - 2Timothy 2:15
15 Do your best to present yourself to God as one approved, a workman who does not need to be ashamed and who correctly handles the word of truth.

D. Meditate -
Psalm 1:1-3
1 Blessed is the man who does not walk in the counsel of the wicked or stand in the way of sinners or sit in the seat of mockers.
2 But his delight is in the law of the LORD, and on his law he meditates day and night.
3 He is like a tree planted by streams of water, which yields its fruit in season and whose leaf does not wither. Whatever he does prospers.

E. Obey -
John 14:21
21 Whoever has my commands and obeys them, he is the one who loves me. He who loves me will be loved by my Father, and I too will love him and show myself to him."
''');

final _nb_Lesson31 = Lessons(
    lessonNumber: 31,
    lessonTitle: 'The Authority of the Bible',
    lessonBody:
        '''Aim: To establish the Bible as the sole source of authority for the believer.

Introduction:
“It is impossible to rightly govern the world without God and Bible.”
George Washington, First President of the United States

Richrad Hooker, one the greatest English Theologians, listed three possible sources of authority; the Bible, the church and human reason. Catholics emphasize the authority of the church, evangelicals emphasize the authority of the Bible and emphasize the authority of reason.


I. THE AUTHORITY OF OLD TESTAMENT
The phrase "Thus saith the Lord, or its equivalent, occurs more than 2,000 times in the Old Testament.

A. Testimony of its writers:
1. David. 2 Samuel 23:2
-2 “The Spirit of the LORD spoke through me; his word was on my tongue.
2. Jeremiah. Jeremiah 1:9
9 Then the LORD reached out his hand and touched my mouth and said to me, “I have put
my words in your mouth.
3. Ezekiel. Ezekiel 3:4
4 He then said to me: “Son of man, go now to the people of Israel and speak my words to
them.

B. Testimony of Christ.
1. Matthew 5:17-18.17 “Do not think that I have come to abolish the Law or the Prophets; I
have not come to abolish them but to fulfill them. 18 For truly I tell you, until heaven and
earth disappear, not the smallest letter, not the least stroke of a pen, will by any means
disappear from the Law until everything is accomplished.

2. John 5:39.39 You study[a] the Scriptures diligently because you think that in them you
have eternal life. These are the very Scriptures that testify about me,

C. Testimony of the Apostles
It is evident from their inspired writing that the Apostles of Christ considered the Old Testament scriptures prophetic and inseparable from the authority, power and ministry of Christ.

Paul says - the whole Old Testament is inspired by God.
2 Timothy 3:16-17.16 All Scripture is God-breathed and is useful for teaching, rebuking,
correcting and training in righteousness, 17 so that the servant of God[a] may be thoroughly
equipped for every good work.


II. THE AUTHORITY OF THE NEW TESTAMENT

A. The authority given the Apostle by Christ
John 17:18.18 As you sent me into the world, I have sent them into the world.
John 20:21.21 Again Jesus said, “Peace be with you! As the Father has sent me, I am sending
you.”

B. The apostles wrote under Christ's authority. Paul received what
He preached from the Lord.

1 Corinthians 11:23.23 For I received from the Lord what I also passed on to you: The Lord
Jesus, on the night he was betrayed, took bread,

Galatians 1:11,12.11 I want you to know, brothers and sisters that the gospel I preached is
not of human origin. 12 I did not receive it from any man, nor was I taught it; rather, I received it by revelation from Jesus Christ.

The writer of Hebrews got his authority through Christ.

Hebrews 1:1,2.1In the past God spoke to our ancestors through the prophets at many times and in various ways, 2 but in these last days he has spoken to us by his Son, whom he appointed heir of all things, and through whom also he made the universe.


III. CONCLUSION.
The Bible is the Word of God. As such, it should serve as the one and only source of authority for us believers in all our dealings with God and with man.
''');

final _nb_Lesson32 = Lessons(
    lessonNumber: 32,
    lessonTitle: 'The Bible, The Holy Word of God',
    lessonBody: '''Aim: To understand the Bible as The Holy Word of God.

Introduction:
"Tell your prince that this Book (the BIBLE) is the secret of England's greatness"
-Queen Victoria, to an African Prince

"It is impossible to rightly govern the world without GOD and the BIBLE"
-George Washington

Next to the gift of Christ and the Holy Spirit, the Bible is the third greatest gift. Sir Walter Scott, himself the author of many books an the possessor of a great library, said, " There is but one book, the Bible." The Bible is the oldest book in existence. It required sixteen centuries to write it, the first writer died 1450 years before the last writer was born. The Bible lends itself to translation and has been translated in whole or in part in more than a thousand languages and dialects.

Seven Crowning Wonders of the Bible.
(Rev. Dyson Hague )

1. The wonder of its formation; one book written on one place and in one language.
Another book written in one country centuries later in another language.

2. The wonder of its unification, it is the library of 66 books , yet only one book, for it has but one author, The. Holy Spirit. There are no contradictions.

3. The wonder of its age. It is the most ancient of all books.
4. The wonder of its sale, It is the best seller of all time.
5. The wonder of its interest. It is the only book that is read by all classes and ages
of mankind. It is read by ages and children, read by all nations.
6. The wonder of its language. It was written by largely by uneducated men, yet it is considered a literary masterpiece.
7. The wonder of its preservation. It has been the most hated of all books. Time and again Kings and governments have sought to burn and abolish it. Yet God has preserved it for us today and it can be found in almost every home.

Seven Symbols Used To Illustrate The Word of God

1. A Sword.The Bible is a pointed word that convicts the hearer.
Hebrews 4:12 -12 For the word of God is living and active. Sharper than any double-edged sword, it penetrates even to dividing soul and spirit, joints and marrow; it judges the thoughts and attitudes of the heart.

2. A Hammer. The Bible is powerful and breaks the resistance of the hearer.
Jeremiah 23:29, 29 "Is not my word like fire," declares the LORD, "and like a hammer that breaks a rock in pieces?

3. A Seed. The Bible is a living Word regenerating the hearer.
1Peter 1:23, 23 For you have been born again, not of perishable seed, but of imperishable, through the living and enduring word of God.

4. A Mirror. The Bible is a faithful Word, revealing the individual to himself.
James 1:23-24, 23 Anyone who listens to the word but does not do what it says is like a man who looks at his face in a mirror

5. A Fire. The Bible is a burning Word, consuming the dross in the hearer.
Jeremiah 20:9
9 But if I say, "I will not mention him or speak any more in his name," his word is in my heart like a fire, a fire shut up in my bones. I am weary of holding it in; indeed, I cannot.
Jeremiah 23:29, 29 "Is not my word like fire," declares the LORD, "and like a hammer that breaks a rock in pieces?

6. A Lamp. The Bible is an Illuminating Word guiding the believer day by day.
Psalm 119:105, 105 Your word is a lamp to my feet and a light for my path.

7. Food.The Bible is nourishing food, feeding the soul ( Providing meat and drink)
1 Peter 2:2 - 2 Like newborn babies, crave pure spiritual milk, so that by it you may grow up in your salvation,

1 Corinthians 3:2 - 2 I gave you milk, not solid food, for you were not yet ready for it. Indeed, you are still not ready.

Romans 10:17 - 17 Consequently, faith comes from hearing the message, and the message is heard through the word of Christ.

The word of God convicts, breaks, regenerates, reveals, consumes, illuminates and nourishes the individual.


SEVEN REASONS FOR PREACHING THE WORD OF GOD

In Mark 2:2, Jesus faced the multitude and made a tremendous decision; it was to preach the Word of God.
We are sent to preach not a new church but Christ as He is revealed in the Bible.
We insist on preaching the Bible because it endures for time and eternity.

Isaiah 40:8 - 8 The grass withers and the flowers fall, but the word of our God stands for ever."

1. Conviction of sin comes through the preaching of the Word of God.
Acts 2: 14-37. In Peter's Pentecost sermon nine verses out of twenty three are quotations from the OT.

2. Faith comes by hearing the Word of God.
Romans 10:17 - 17 So then faith cometh by hearing, and hearing by the word of God.

3. Cleansing comes from the Word of God.
2 Corinthians 7:1 - 1 Having therefore these promises, dearly beloved, let us cleanse ourselves from all filthiness of the flesh and spirit, perfecting holiness in the fear of God.

4. Assurance comes from the Word of God.
1John 5:13 - 13 These things have I written unto you that believe on the name of the Son of God; that ye may know that ye have eternal life, and that ye may believe on the name of the Son of God.

5. Comfort comes from the Word of God.
1 Thessalonians 4:18, 18 Wherefore comfort one another with these words.

6. Truth comes from the Word of God.
Acts 17:11, 11 These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so.

7. The New Birth comes from the Word of God.
1Peter 1:23, 23 Being born again, not of corruptible seed, but of incorruptible, by the word of God, which liveth and abideth for ever.


SEVEN POINTS TO REMEMBER IN READING THE BIBLE.
1. Read it lovingly.
The Bible is the Word of my Savior to me. Psalm 119:11
2. Read it reverently.
The Bible is the Word of God,
3. Read it prayerfully.
The Bible is God's message to me, to my own heart and life.
4. Read it meditatively.
Be like David of old and meditate on the word of God.
5. Read it systematically.
Read right through the Bible, not just selected portions.
6. Read it resolutely.
I will obey that which my father teaches me from His book.
7. Read it daily.
Not just on Sundays but everyday of your life read a portion.


CONCLUSION
Make the Bible your constant guide and companion in life.
The Bible is the Word of God. it is worthy of being believed.
Breathe a prayer to the Holy Spirit to help you understand the sacred pages.
''');

final _nb_Lesson33 = Lessons(
    lessonNumber: 33,
    lessonTitle: 'Last Days Series pt. 1',
    lessonBody:
        '''Aim:To study the scriptural meaning and basis of hope and its importance in the life of a believer.

Introduction:
" Once you choose hope, anything is possible" Christopher Reeve

" Hope is the little voice you hear whisper, maybe when the entire world is shouting NO!"
-Anonymous

Hope is a very vital ingredient in our christian experience. Without hope we are living aimlessly and carelessly. Hope, like an anchor, hives ability to a ship. In this study , we will try to explore the implications of hope in our lives as believers of Jesus Christ.


I. WHAT IS HOPE?
This is used to express a desire or expectation concerning the future that is often nothing more than wishful thinking or holding on mere possibility. But “Christian Hope" is more than " wishful thinking" because it is based on something definite and solid - Word of God. Hope is a positive factor in our christian lives.


II. WHAT ARE SOME OBJECTS OF OUR BLESSED HOPE?

A. Second Coming of Christ
Titus 2:13 - 13 while we wait for the blessed hope—the appearing of the glory of our great God and Savior, Jesus Christ,

B. the Resurrection of the Dead
1. Cor. 15:12-22 - 12 But if it is preached that Christ has been raised from the dead, how can some of you say that there is no resurrection of the dead? 13 If there is no resurrection of the dead, then not even Christ has been raised. 14 And if Christ has not been raised, our preaching is useless and so is your faith. 15 More than that, we are then found to be false witnesses about God, for we have testified about God that he raised Christ from the dead. But he did not raise him if in fact the dead are not raised. 16 For if the dead are not raised, then Christ has not been raised either. 17 And if Christ has not been raised, your faith is futile; you are still in your sins. 18 Then those also who have fallen asleep in Christ are lost. 19 If only for this life we have hope in Christ, we are of all people most to be pitied. 20 But Christ has indeed been raised from the dead, the first fruits of those who have fallen asleep. 21 For since death came through a man, the resurrection of the dead comes also through a man. 22 For as in Adam all die, so in Christ all will be made alive.

C. Glory.
Romans 8:18 - 18 I consider that our present sufferings are not worth comparing with the glory
that will be revealed in us.
Col. 1:27 -27 To them God has chosen to make known among the Gentiles the glorious riches of
this mystery, which is Christ in you, the hope of glory.

D. Heaven.
2 Peter 3:13 - 13 But in keeping with his promise we are looking forward to a new heaven and a
new earth, where righteousness dwells.

E. Millennial Reign
Rev. 20:6 - 6 Blessed and holy are those who share in the first resurrection. The second death has no power over them, but they will be priests of God and of Christ and will reign with him for a thousand years.

F. Heavenly Reward.
2 Timothy 4:8 - 4 In the presence of God and of Christ Jesus, who will judge the living and the dead, and in view of his appearing and his kingdom, I give you this charge: 2 Preach the word; be prepared in season and out of season; correct, rebuke and encourage—with great patience and careful instruction. 3 For the time will come when people will not put up with sound doctrine. Instead, to suit their own desires, they will gather around them a great number of teachers to say what their itching ears want to hear. 4 They will turn their ears away from the truth and turn aside to myths. 5 But you, keep your head in all situations, endure hardship, do the work of an evangelist, discharge all the duties of your ministry.
6 For I am already being poured out like a drink offering, and the time for my departure is near. 7 I have fought the good fight, I have finished the race, I have kept the faith. 8 Now there is in store for me the crown of righteousness, which the Lord, the righteous Judge, will award to me on that day—and not only to me, but also to all who have longed for his appearing.


III. WHAT DOES HOPE PRODUCE IN US?
A. Confidence.
John 11:8 - "But Rabbi," they said, "a short while ago the Jews there tried to stone you, and yet you are going back?"

B. Gladness
Prov. 10:28 - The prospect of the righteous is joy, but the hopes of the wicked come to nothing.

C. Faith.
Hebrews 11:1 - Now faith is being sure of what we hope for and certain of what we do not see.

D. Purity.
1John 3:3 - 3 All who have this hope in him purify themselves, just as he is pure.

E. Strength.
Psalm 31:24 - 24 Be strong and take heart, all you who hope in the LORD.

F. Anchor/ Stability
Hebrews 6:18,19 - 18 God did this so that, by two unchangeable things in which it is impossible for God to lie,we who have fled to take hold of the hope set before us may be greatly encouraged.19 We have this hope as an anchor for the soul, firm and secure. It enters the inner sanctuary behind the curtain,


IV. CONCLUSION
Christians can always be joyful because of their blessed Hope in Christ.
''');

final _nb_Lesson34 = Lessons(
    lessonNumber: 34,
    lessonTitle: 'The Second Coming of Christ',
    lessonBody:
        '''Aim:To study the scriptural meaning and basis of The Second coming of Jesus Christ.

Introduction:
“Are you ready for the rapture of the church
Are you ready for Heaven
Our Lord Jesus Christ now wants all Christians to get into a sense of urgency in our preparation for His second coming.” ― Doris Ijeoma Basil, A Sense of Urgency

“The second coming of Christ will be so revolutionary that it will change every aspect of life on this planet. Christ will reign in righteousness. Disease will be arrested. Death will be modified. War will be abolished. Nature will be changed. Man will live as it was originally intended he should live.” ― Billy Graham, Billy Graham in Quotes

There are three Greek words used to reveal this fact:
1. Parousia - personal presence.
2. Apukalupsis - revelation
3. Epiphaneia - appearing

These three words signify that there will come a time when Christ will return in a public, personal revelation of Himself to the world. Some teach that the second coming is when at death "Jesus comes to receive the soul," but that would not be a public revelation visible to the world.

Acts 1:10,11 - 10 They were looking intently up into the sky as he was going, when suddenly two men dressed in white stood beside them. 11 “Men of Galilee,” they said, “why do you stand here looking into the sky? This same Jesus, who has been taken from you into heaven, will come back in the same way you have seen him go into heaven.”

Describes as being
1. Personal
2. Bodily
3. Visible and
4. With power

The Savior's first coming was in humiliation but the second coming will be glorious.
There are three (3) major view points respecting His second coming.

1. Post millennial view - it teaches that the second coming will follow rather that precede the millennial age.

2. The A - millenial view - supporters do not believe in a literal period of a thousand years but believe
that when Christ

3. The revelation which is public ( Revelation 1:7), when the Lord comes with His saints to set up the millenium
Revelation 1:7 -7 “Look, he is coming with the clouds and “every eye will see him, even those who pierced him”; and all peoples on earth “will mourn because of him. So shall it be! Amen.

1 Thessalonians 3:13 - 13 May he strengthen your hearts so that you will be blameless and holy in the presence of our God and Father when our Lord Jesus comes with all his holy ones.
An unsolve problem of pre- millennialists is whether the church will go through the tribulation so there are the " Pre - tribulation and mid - tribulation" debates.

I. PROPHECIES OF CHRIST'S SECOND COMING His first coming was prophesied and those prophecies came to pass literally. That gives us confidence that the prophecies of the Second Advent will also be fulfilled literally and not in a figurative or spiritual sense.

1. It was foretold by the prophets
Daniel 7:13 - 13 “In my vision at night I looked, and there before me was one like a son of man,coming with the clouds of heaven. He approached the Ancient of Days and was led into his presence.

2. It was foretold by Jesus Himself.
Matthew 25:31 -31 “When the Son of Man comes in his glory, and all the angels with him, he will sit on his glorious throne.

3. It was foretold by Paul.
1 Timothy 6:14 - 14 to keep this command without spot or blame until the appearing of our Lord Jesus Christ,

4. It was foretold by angels.
Acts 1:10,11 - 10 They were looking intently up into the sky as he was going, when suddenly two men dressed in white stood beside them. 11 “Men of Galilee,” they said, “why do you stand here looking into the sky? This same Jesus, who has been taken from you into heaven, will come back in the same way you have seen him go into heaven.”


II. TIME OF CHRIST'S COMING.

This is a secret that only the Lord knows.
Matthew 24:36 -36 “But about that day or hour no one knows, not even the angels in heaven, nor
the Son,[a] but only the Father.

Jesus Christ as a man did not know the date but Jesus Christ as God is Omniscient and certainly knows the exact moment when it will occur.

Alban Douglas comment, " I believe it is movable date 2 Peter 3:12 that can be advanced or retarded depending on the speed or slowness of taking the Gospel to every tribe, Matthew 24:14 .

2 Peter 3:12 -12 as you look forward to the day of God and speed its coming.[a] That day will bring about the destruction of the heavens by fire, and the elements will melt in the heat.

Matthew 24:14 -14 And this gospel of the kingdom will be preached in the whole world as a testimony to all nations, and then the end will come.


III. PURPOSE OF CHRIST'S COMING.

1. To complete the salvation of saints.
He has delivered us from the power and penalty of sin.
Hebrews 9:28 - 28 so Christ was sacrificed once to take away the sins of many; and he will appear a second time, not to bear sin, but to bring salvation to those who are waiting for him.

2. To be glorified in His saints.
2 Thess. 1:10-10 on the day he comes to be glorified in his holy people and to be marveled at among all those who have believed. This includes you, because you believed our testimony to you.

3. To bring to light the hidden things of darkness.
1 Cor. 4:5 - 5 Therefore judge nothing before the appointed time; wait until the Lord comes. He will bring to light what is hidden in darkness and will expose the motives of the heart. At that time each will receive their praise from God.

4. To Judge.
2 Tim. 4:1 - In the presence of God and of Christ Jesus, who will judge the living and the dead, and in view of his appearing and his kingdom, I give you this charge:

5. To Reign.
Revelation 11:15 -15 The seventh angel sounded his trumpet, and there were loud voices in heaven, which said: “The kingdom of the world has become the kingdom of our Lord and of his Messiah, and he will reign for ever and ever.”
6. To receive us to be with Himself.
John 14:3 -3 And if I go and prepare a place for you, I will come back and take you to be with me that you also may be where I am.

7. To destroy death.
1 Cor. 15: 25,26 -25 For he must reign until he has put all his enemies under his feet.26 The last enemy to be destroyed is death.


IV. HOW IS CHRIST'S COMING.
A. Secretly at the Rapture.
1 Thess. 5:2 -2 for you know very well that the day of the Lord will come like a thief in the night.
Matthew 24:44 - 44 So you also must be ready, because the Son of Man will come at an hour when you do not expect him.

Be prepared to meet Him today.

B. Publicly at the revelation.
Revelation 1:7 -“Look, he is coming with the clouds,” and “every eye will see him, even those who pierced him”; and all peoples on earth “will mourn because of him.” So shall it be! Amen.
Matthew 24:30 -30 “Then will appear the sign of the Son of Man in heaven. And then all the peoples of the earth[a] will mourn when they see the Son of Man coming on the clouds of heaven, with power and great glory.
Titus 2:13 - 13 while we wait for the blessed hope—the appearing of the glory of our great God and Savior, Jesus Christ,


V. WHERE IS CHRIST'S COMING TO?

A. At the Rapture we will meet Him in the Air.
1 Thess. 4-17
1 Thess. 4:17 17 After that, we who are still alive and are left will be caught up together with them in the clouds to meet the Lord in the air. And so we will be with the Lord forever.

B. At the Revelation we will descend with Him to the earth. Probably He will land on the Mount of Olives.
Zechariah 14:4 -4 On that day his feet will stand on the Mount of Olives, east of Jerusalem, and the Mount of Olives will be split in two from east to west, forming a great valley, with half of the mountain moving north and half moving south.


VI. MANNER OF HIS COMING

1. In the clouds.
Matthew 24:30 -30 “Then will appear the sign of the Son of Man in heaven. And then all the peoples of the earth will mourn when they see the Son of Man coming on the clouds of heaven, with power and great glory.

2. In the glory of His Father.
Matthew 16:27 - 27 For the Son of Man is going to come in his Father’s glory with his angels, and then he will reward each person according to what they have done.

3. In His own glory.
Matthew 25:31 - 31 “When the Son of Man comes in his glory, and all the angels with him, he will sit on his glorious throne.

4. In flaming fire.
2 Thess. 1:8 -8 He will punish those who do not know God and do not obey the gospel of our Lord Jesus.

5. With power and great glory.
Matthew 24:30 -30 “Then will appear the sign of the Son of Man in heaven. And then all the peoples of the earthwill mourn when they see the Son of Man coming on the clouds of heaven, with power and great glory.

6. As He ascended, in bodily form
Acts 1: 9-11 -9 After he said this, he was taken up before their very eyes, and a cloud hid him from their sight. 10 They were looking intently up into the sky as he was going, when suddenly two men dressed in white stood beside them. 11 “Men of Galilee,” they said, “why do you stand here looking into the sky? This same Jesus, who has been taken from you into heaven, will come back in the same way you have seen him go into heaven.”

7. With the shout and the voice of the archangel.
1 Thess. 4:16 -16 For the Lord himself will come down from heaven, with a loud command, with the voice of the archangel and with the trumpet call of God, and the dead in Christ will rise first.

8. With His saints.
1 Thess. 3: 13 -13 May he strengthen your hearts so that you will be blameless and holy in the presence of our God and Father when our Lord Jesus comes with all his holy ones.
9. Accompanied by Angels.
Matthew 16:27 -27 For the Son of Man is going to come in his Father’s glory with his angels, and then he will reward each person according to what they have done.
10. Suddenly.
Mark 13:36 -36 If he comes suddenly, do not let him find you sleeping.


VII. SIGNS OF CHRIST'S COMING
2 Timothy 3:1-7 -But mark this: There will be terrible times in the last days. 2 People will be lovers of themselves, lovers of money, boastful, proud, abusive, disobedient to their parents, ungrateful, unholy, 3 without love, unforgiving, slanderous, without self-control, brutal, not lovers of the good, 4 treacherous, rash, conceited, lovers of pleasure rather than lovers of God— 5 having a form of godliness but denying its power. Have nothing to do with such people.6 They are the kind who worm their way into homes and gain control over gullible women, who are loaded down with sins and are swayed by all kinds of evil desires, 7 always learning but never able to come to a knowledge of the truth.
Lists 23 signs of His coming, most of which are evident today.
1. Perilous times
2. Men loving themselves
3. Covetousness
4. Boasting
5. Proud
6. Blasphemy
7. Disobedient to parents
8. Unthankful
9. Unholy
10. Without natural affection
11. Truce-breakers (unforgiving)
12. False accusers
13. Incontinent (without self-control)
14. Fierce (brutal)
15. Despising good
16. Traitors
17. Heady (rash)
18. High minded (conceited)
19. Lovers of pleasures more than lovers of God.
20. Having a form of godliness
21. Silly women laden with sins
22. Divers lusts (all kinds of evil desires.)
23. Ever learning and never able to come to the knowledge of truth.

Matthew 24:5-7,12-38 5 For many will come in my name, claiming, ‘I am the Messiah,’ and will deceive many. 6 You will hear of wars and rumors of wars, but see to it that you are not alarmed. Such things must happen, but the end is still to come. 7 Nation will rise against nation, and kingdom against kingdom. There will be famines and earthquakes in various places.

Lists ten signs.
1. False Christ's
2. Wars and rumors of wars.
3. Famines
4. Pestilences
5. Earthquakes
6. Iniquity to abound
7. Love of many waxes cold,
8. Eating
9. Drinking
10. Marrying

Other signs include:
1. The destruction of Jerusalem
Luke 21:20,24 - 20 “When you see Jerusalem being surrounded by armies, you will know that its desolation is near. 24 They will fall by the sword and will be taken as prisoners to all the nations. Jerusalem will be trampled on by the Gentiles until the times of the Gentiles are fulfilled.

2. The completion of the church.
Romans 11:25 -25 I do not want you to be ignorant of this mystery, brothers and sisters, so that you may not be conceited: Israel has experienced a hardening in part until the full number of the Gentiles has come in.

3. Gospel preached everywhere.
Matthew 24:14 -14 And this gospel of the kingdom will be preached in the whole world as a testimony to all nations, and then the end will come.

4. The coming of the anti-Christ.
2 Thess. 2:3-8 -3 Don’t let anyone deceive you in any way, for that day will not come until the rebellion occurs and the man of lawlessness[a] is revealed, the man doomed to destruction. 4 He will oppose and will exalt himself over everything that is called God or is worshiped, so that he sets himself up in God’s temple, proclaiming himself to be God. 5 Don’t you remember that when I was with you I used to tell you these things? 6 And now you know what is holding him back, so that he may be revealed at the proper time. 7 For the secret power of lawlessness is already at work; but the one who now holds it back will continue to do so till he is taken out of the way. 8 And then the lawless one will be revealed, whom the Lord Jesus will overthrow with the breath of his mouth and destroy by the splendor of his coming.


CONCLUSION

Be not a scoffer like those in
2 Peter 3:3 for His coming is sure and certain.
Is it right to sell everything and sit on a hilltop waiting for Him?
Definitely NOT!

We ought to plan and work as if He were not coming for another century but a holy life and pure life as if He were to return today.
1 Thess. 3:12,13
This doctrine must affect our lives. It ought to keep us busy and watching.
2 Peter 3:3 -3 Above all, you must understand that in the last days scoffers will come, scoffing and following their own evil desires.
1 Thess. 3:12,13 -12 May the Lord make your love increase and overflow for each other and for everyone else, just as ours does for you. 13 May he strengthen your hearts so that you will be blameless and holy in the presence of our God and Father when our Lord Jesus comes with all his holy ones.
''');

final _nb_Lesson35 = Lessons(
    lessonNumber: 35,
    lessonTitle: 'The Rapture of the Church',
    lessonBody:
        '''Aim:To teach the believers the biblical teaching of the first phase of the second coming of Christ, the Rapture.

Introduction:
“Are you ready for the rapture of the church”
“Are you ready for Heaven”

Our Lord Jesus Christ now wants all Christians to get into a sense of urgency in our preparation for His second coming.”
― Doris Ijeoma Basil, A Sense of Urgency

The word " Rapture" is derived from the latin word " Raptu". Which means " caught away or caught up". This latin word is equivalent to the Greek word " Harpaze" translated as " caught up " in 1 Thessalonians 4:17

"17 After that, we who are still alive and are left will be caught up together with them in the clouds to meet the Lord in the air. And so we will be with the Lord for ever."-1 Thessalonians 4:17

This event, described here and in 1 Corinthians 15, refers to the catching up of the church from the earth to meet the Lord in the air. It involves only the faithful of Christ's churches.


The Stages of the Rapture
1. Just prior to the Rapture, as Christ is descending from heaven for His church, the resurrection of the “Dead in Christ" will occur 1 Thessalonians 4:16

16 For the Lord himself will come down from heaven, with a loud command, with the voice of the archangel and with the trumpet call of God, and the dead in Christ will rise first. -1Thess 4:16

This is not the same resurrection described in (Rev. 20:4 ) for the latter is an event occurring after Christ returns to earth, destroys the wicked and binds Satan ( Rev. 19:11-20:3 ). The resurrection in Rev. 20:4 relates to the martyred dead of the tribulation and possibly to OT saints (Rev. 20:6)

4 I saw thrones on which were seated those who had been given authority to judge. And I saw the souls of those who had been beheaded because of their testimony about Jesus and because of the word of God. They had not worshiped the beast or its image and had not received its mark on their foreheads or their hands. They came to life and reigned with Christ a thousand years.-Revelation 20:4

11 I saw heaven standing open and there before me was a white horse, whose rider is called Faithful and True. With justice he judges and wages war.-Revelation 19:11

3 He threw him into the Abyss, and locked and sealed it over him, to keep him from deceiving the nations anymore until the thousand years were ended. After that, he must be set free for a short time.–Revelation 20:3

2. At the same time as the dead in Christ will rise, living believers will be transfigured, their bodies will be clothed with immortality. (1Cor. 15:51,53)
This will happen in a very short time," In the twinkling of an eye" ( I Co. 15:52)
1 Corinthians 15:51, 53, 15:52
51 Listen, I tell you a mystery: We will not all sleep, but we will all be changed52 in a flash, in the twinkling of an eye, at the last trumpet. For the trumpet will sound, the dead will be raised imperishable, and we will be changed.
53 For the perishable must clothe itself with the imperishable, and the mortal with immortality.

3. Both the resurrected believers and the transfigured believers will be caught up together to meet Christ in the air.,. In the atmosphere between heaven and the earth.

4. They will be visibly united with Christ.
1 Thess. 4;16-17, taken to His Father's house in heaven
John 14:2-3 and united with loved who have died. 1 Thess. 4:13-18

1Thessalonians 4:16-17
16 For the Lord himself will come down from heaven, with a loud command, with the voice of the archangel and with the trumpet call of God, and the dead in Christ will rise first. 17 After that, we who are still alive and are left will be caught up together with them in the clouds to meet the Lord in the air. And so we will be with the Lord forever.

5. They will be removed from all distress (2 Co. 5:2,4, Phil. 3:21)

2 Corinthians 5:2,4
2 Meanwhile we groan, longing to be clothed instead with our heavenly dwelling,

4 For while we are in this tent, we groan and are burdened, because we do not wish to be unclothed but to be clothed instead with our heavenly dwelling, so that what is mortal may be swallowed up by life.

Philippians 3:21
21 who, by the power that enables him to bring everything under his control, will transform our lowly bodies so that they will be like his glorious body.
From all persecution and oppression ( Rev. 3:10), from the entire sin and death ( 1 Cor.15:51-56) Christ thereby delivers them from " the wrath to come" 1 Thess. 1:10, 5:9) from the great tribulation.

Revelations 3:20
20 Here I am! I stand at the door and knock. If anyone hears my voice and opens the door, I will come in and eat with that person, and they with me.

1 Corinthians 15:51-56
51 Listen, I tell you a mystery: We will not all sleep, but we will all be changed— 52 in a flash, in the twinkling of an eye, at the last trumpet. For the trumpet will sound, the dead will be raised imperishable, and we will be changed. 53 For the perishable must clothe itself with the imperishable, and the mortal with immortality. 54 When the perishable has been clothed with the imperishable, and the mortal with immortality, then the saying that is written will come true: “Death has been swallowed up in victory.”[55 “Where, O death, is your victory? Where, O death, is your sting?”56 The sting of death is sin, and the power of sin is the law.

1 Thess. 1:10
10 and to wait for his Son from heaven, whom he raised from the dead—Jesus, who rescues us from the coming wrath.
9 For God did not appoint us to suffer wrath but to receive salvation through our Lord Jesus Christ.

6. The hope that our Savior will soon return to take us out if the world to "ever be with the Lord" (1 Thess. 4:17) is the blessed hope of the redeemed (Titus 2:13) and a major source of comfort for suffering believers (1 Thes 4:17-18, 5:10)

Titus 2:13
13 while we wait for the blessed hope—the appearing of the glory of our great God and Savior, Jesus Christ,

1Thessaloninas 4:17, 5:10
17 After that, we who are still alive and are left will be caught up together with them in the clouds to meet the Lord in the air. And so we will be with the Lord forever. 18 Therefore encourage one another with these words.

5:10 He died for us so that, whether we are awake or asleep, we may live together with him.

7. Paul uses "we" in 1Thes 4:17 because he knows the Lord's return could have happened in his own lifetime, and he communicates this same anticipation to the Thessalonians. The Bible insists on a continual waiting with eagerness for the return of the Lord. Believers today must be ever watchful and hopeful for Christ's return to take them to Himself (cf. Rom 13:11; 1 Cor 7:29; 10:11; 15:51-52; Phil 4:5)

Rom 13:11
11 And do this, understanding the present time: The hour has already come for you to wake up from your slumber, because our salvation is nearer now than when we first believed.

1 Corinthians 7:29, 10:11, 15:51,
29 What I mean, brothers and sisters, is that the time is short. From now on those who have wives should live as if they do not;

11 These things happened to them as examples and were written down as warnings for us, on whom the culmination of the ages has come.

51 Listen, I tell you a mystery: We will not all sleep, but we will all be changed— 52 in a flash, in the twinkling of an eye, at the last trumpet. For the trumpet will sound, the dead will be raised imperishable, and we will be changed.

8. According to this view of the rapture, professing Christians who do not have a saving relationship with Christ will be left behind (see Mat 25:1, note; see article on The Age of the Antichrist, p. 1912), and be subject to God’s wrath.

Matthew 25:1
“At that time the kingdom of heaven will be like ten virgins who took their lamps and went out to meet the bridegroom.

9. Following the rapture is the day of the Lord, a time that brings distress and wrath to the ungodly (1 Thes 5:2-10; see 5:2, note). That will be followed by the second stage of Christ’s coming, when He comes to destroy the ungodly and to reign on earth (see Mat 24:42,44 notes).

1Thessalonians 5:2-10
2 for you know very well that the day of the Lord will come like a thief in the night. 3 While people are saying, “Peace and safety,” destruction will come on them suddenly, as labor pains on a pregnant woman, and they will not escape.4 But you, brothers and sisters, are not in darkness so that this day should surprise you like a thief.5 You are all children of the light and children of the day. We do not belong to the night or to the darkness. 6 So then, let us not be like others, who are asleep, but let us be awake and sober. 7 For those who sleep, sleep at night, and those who get drunk, get drunk at night. 8 But since we belong to the day, let us be sober, putting on faith and love as a breastplate, and the hope of salvation as a helmet. 9 For God did not appoint us to suffer wrath but to receive salvation through our Lord Jesus Christ. 10 He died for us so that, whether we are awake or asleep, we may live together with him.
''');

final _nb_Lesson36 = Lessons(
    lessonNumber: 36,
    lessonTitle: 'The Bema Seat of Christ',
    lessonBody:
        '''Aim: To teach the believers the biblical teaching of the second phase of the second coming of Christ,
the Bema Judgement.

Introduction:
“We are to wait for the coming of Christ with patience. We are to watch with anticipation. We are to work with Zeal. We are to prepare with urgency. Scripture says Christ is coming when you’re least expecting him. Coming as a thief. He said, ‘Be prepared. Get Ready. Prepare to meet thy God. Are you prepared?’” Dr. Billy Graham Here we come to the second phase of the second coming of Christ, the Bema judgement. In this lesson we will begin to see one the glorious activity of Christ at His advent. We will answer some of the tough questions on what will happen to the saints after they will be judged based on their performance while we are in this earth.

What is the Judgment Seat of Christ / Bema Seat of Christ?"
Romans 14:10-12 says, “For we will all stand before God’s judgment seat…so then, each of us will give an account of himself to God.”

Romans 14:10-1210 You, then, why do you judge your brother or sister[a]? Or why do you treat them with contempt? For we will all stand before God’s judgment seat. 11 It is written: “‘As surely as I live,’ says the Lord, ‘every knee will bow before me; every tongue will acknowledge God.’”12 So then, each of us will give an account of ourselves to God.
Second Corinthians 5:10 tells us, “For we must all appear before the judgment seat of Christ, that each one may receive what is due him for the things done while in the body, whether good or bad.”
In the context, it is clear that both scriptures are referring to Christians, not unbelievers. The judgment seat of Christ, therefore, involves believers giving an account of their lives to Christ.
The judgment seat of Christ does not determine salvation; that was determined by Christ’s sacrifice on our behalf (1 John 2:2) and our faith in Him (John 3:16). All of our sins are forgiven, and we will never be condemned for them (Romans 8:1). We should not look at the judgment seat of Christ as God judging our sins, but rather as God rewarding us for our lives. Yes, as the Bible says, we will have to give an account of ourselves. Part of this is surely answering for the sins we committed. However, that is not going to be the primary focus of the judgment seat of Christ.
1 John 2:2-2 He is the atoning sacrifice for our sins, and not only for ours but also for the sins of the whole world.
Romans 8:1-8 Therefore, there is now no condemnation for those who are in Christ Jesus,

At the judgment seat of Christ, believers are rewarded based on how faithfully they served Christ (1 Corinthians 9:4-27; 2 Timothy 2:5). Some of the things we might be judged on are how well we obeyed the Great Commission (Matthew 28:18-20), how victorious we were over sin (Romans 6:1-4), and how well we controlled our tongues (James 3:1-9). The Bible speaks of believers receiving crowns for different things based on how faithfully they served Christ (1 Corinthians 9:4-27; 2 Timothy 2:5). The various crowns are described in 2 Timothy 2:5, 2 Timothy 4:8, James 1:12, 1 Peter 5:4, and Revelation 2:10. James 1:12 is a good summary of how we should think about the judgment seat of Christ: “Blessed is the man who perseveres under trial, because when he has stood the test, he will receive the crown of life that God has promised to those who love him.”
2 Timothy 2:5-5 similarly, anyone who competes as an athlete does not receive the victor’s crown except by competing according to the rules.

Matthew 28:18-2018 Then Jesus came to them and said, “All authority in heaven and on earth has been given to me. 19 Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit, 20 and teaching them to obey everything I have commanded you. And surely I am with you always, to the very end of the age.”

Romans 6:1-4-6 what shall we say, then? Shall we go on sinning so that grace may increase? 2 By no means! We are those who have died to sin; how can we live in it any longer? 3 Or don’t you know that all of us who were baptized into Christ Jesus were baptized into his death? 4 We were therefore buried with him through baptism into death in order that, just as Christ was raised from the dead through the glory of the Father, we too may live a new life.

2 Timothy 4:8-8 Now there is in store for me the crown of righteousness, which the Lord, the righteous Judge, will award to me on that day—and not only to me, but also to all who have longed for his appearing.

James 1:12- 12 Blessed is the one who perseveres under trial because, having stood the test, that person will receive the crown of life that the Lord has promised to those who love him.

1 Peter 5:4-4 And when the Chief Shepherd appears, you will receive the crown of glory that will never fade away.

Revelation 2:10- 10 Do not be afraid of what you are about to suffer. I tell you, the devil will put some of you in prison to test you, and you will suffer persecution for ten days. Be faithful, even to the point of death, and I will give you life as your victor’s crown.

"What are the five heavenly crowns that believers can receive in Heaven?"
There are five heavenly crowns mentioned in the New Testament that will be awarded to believers. They are the imperishable crown, the crown of rejoicing, the crown of righteousness, the crown of glory, and the crown of life. The Greek word translated “crown” is stephanos (the source for the name Stephen the martyr) and means “a badge of royalty, a prize in the public games or a symbol of honor generally.” Used during the ancient Greek games, it referred to a wreath or garland of leaves placed on a victor’s head as a reward for winning an athletic contest. As such, this word is used figuratively in the New Testament of the rewards of heaven God promises t hose who are faithful.

Paul’s passage in 1 Corinthians 9:24-25 best defines for us how these crowns are awarded.

1) The Imperishable Crown –
(1 Corinthians 9:24-25) “Do you not know that those who run in a race all run, but one receives the prize? Run in such a way that you may obtain it. And everyone who competes for the prize is temperate [disciplined] in all things. Now they do it to obtain a perishable crown, but we for an imperishable crown” (NKJV). All things on this earth are subject to decay and will perish. Jesus urges us to not store our treasures on earth “where moth and rust destroy, and where thieves break in and steal” (Matthew 6:19). This is analogous to what Paul was saying about that wreath of leaves that was soon to turn brittle and fall apart. But not so the heavenly crown; faithful endurance wins a heavenly reward which is “an inheritance incorruptible and undefiled and that does not fade away, reserved in heaven for you” (1 Peter 1:3-5).

2) The Crown of Rejoicing – (1 Thessalonians 2:19) “For what is our hope, or joy, or crown of rejoicing? Is it not even you in the presence of our Lord Jesus Christ at His coming?” The apostle Paul tells us in Philippians 4:4 to “rejoice always in the Lord” for all the bountiful blessings our gracious God has showered upon us. As Christians we have more in this life to rejoice about than anyone else. Luke tells us there is rejoicing even now in heaven (Luke 15:7). The crown of rejoicing will be our reward where “God will wipe away every tear . . . there shall be no more death, nor sorrow, nor crying. There shall be no more pain, for the former things have passed away” (Revelation 21:4).

3) The Crown of Righteousness – (2 Timothy 4:8) “Finally, there is laid up for me the crown of righteousness, which the Lord, the righteous Judge, will give to me on that Day, and not to me only but also to all who have loved His appearing.” We inherit this crown through the righteousness of Christ which is what gives us a right to it, and without which it cannot be obtained. Because it is obtained and possessed in a righteous way, and not by force and deceit as earthly crowns sometimes are, it is an everlasting crown, promised to all who love the Lord and eagerly wait for His return. Through our enduring the discouragements, persecutions, sufferings, or even death, we know assuredly our reward is with Christ in eternity (Philippians 3:20). This crown is not for those who depend upon their own sense of righteousness or of their own works. Such an attitude breeds only arrogance and pride, not a longing, a fervent desire to be with the Lord.

4) The Crown of Glory – (1 Peter 5:4) “And when the Chief Shepherd appears, you will receive the crown of glory that does not fade away.” Though Peter is addressing the elders, we must also remember that the crown will be awarded to all those who long for or love His appearing. This word “glory” is an interesting word referring to the very nature of God and His actions. It entails His great splendor and brightness. Recall Stephen who, while being stoned to death, was able to look into the heavens and see the glory of God (Acts 7:55-56). This word also means that the praise and honor we bestow to God alone is due Him because of who He is (Isaiah 42:8, 48:11; Galatians 1:5). It also recognizes that believers are incredibly blessed to enter into the kingdom, into the very likeness of Christ Himself. For as Paul so eloquently put it, “For I consider that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us” (Romans 8:18 NKJV).

5) The Crown of Life – (Revelation 2:10) “Do not fear any of those things which you are about to suffer. Indeed, the devil is about to throw some of you into prison, that you may be tested, and you will have tribulation ten days. Be faithful until death, and I will give you the crown of life.” This crown is for all believers, but is especially dear to those who endure sufferings, who bravely confront persecution for Jesus, even to the point of death. In Scripture the word “life” is often used to show a relationship that is right with God. It was Jesus who said, “I have come that they may have life and that they may have it more abundantly” (John 10:10). Just as things such as air, food, and water are vital for our physical lives, Jesus provides us what is required for our spiritual lives. He is the One who provides “living water.” He is the “bread of life” (John 4:10, 6:35). We know that our earthly lives will end. But we have the amazing promise that comes only to those who come to God through Jesus: “And this is the promise that He has promised us—eternal life” (1 John 2:25).
James tells us that this crown of life is for all those who love God (James 1:12). The question then is how do we demonstrate our love for God? The apostle John answers this for us: “For this is the love of God, that we keep His commandments. And His commandments are not burdensome” (1 John 5:3). As His children we must keep His commandments, obeying Him, always remaining faithful. So, as we endure the inevitable trials, pains, heartaches, and tribulations—as long as we live—may we ever move forward, always “looking unto Jesus, the author and finisher of our faith” (Hebrews 12:2) and receive the crown of life that awaits us.

HOW CAN I BE PREPARED TO MEET THE BEMA?
• By constant communion with my Savior Jesus Christ.
• By much self-examination.
• By constant confession of my sins.
• By much prayer and meditation the Word of God. By constant attention to the will of the Holy Spirit.


Conclusion:
The believer's judgement before the judgement Seat of Christ is not a judgement of condemnation, but the determining the believer's awards. To the Christian the Bema should no terrors, it ought to the best day he has ever had. It will be his crowning day.
Readings and supplements: Foundations of Pentecostal Theology One Hundred Bible lessons Got Questions. Org.
''');

final _nb_Lesson37 = Lessons(
    lessonNumber: 37,
    lessonTitle: 'The Resurrection of the Body',
    lessonBody:
        '''Aim: To teach the believers the biblical teaching of the Resurrection of the body.

Introduction:
"The bodily resurrection of Jesus Christ from the dead is the crowning proof of Christianity. If the resurrection did not take place, then Christianity is a false religion. If it did take place, then Christ is God and the Christian faith is absolute truth.”—Henry Morris

The resurrection of the body is an essential doctrine in Scripture. It refers to God raising a human body from the dead and reuniting it with the person's soul and spirit, from which at death it was separated during the intermediate state.

I. The Bible reveals at least 3 reasons why the resurrection of the body is necessary.
1. The body is essential to the total human personality, humans are incomplete
Without a body. Thus, the redemption Christ offers applies to the whole person, including the body -Romans 8:18-25.

2. The body is the temple of the Holy Spirit.
1 Corinthians 6:19
It will become once more a temple of the Spirit at the resurrection.

3. To undo the result of sin at all levels, humanity's final enemy ( death of the body )
Must be conquered through the resurrection .
1 Corinthians 15:26


II. Both the Old Testament and New Testament teach the future bodily resurrection.
Old Testament
1. Genesis 22:1-14 - Abraham and Isaac Story
with Hebrews 11: 17-19

2. Psalm 16:10 - David's confession
With Acts 2:24-25

3. Job 19:25-27 Job's open vision
with 1 Corinthians 15:22-23


III. Our bodily resurrection is guaranteed by the fact of Christ's resurrection
Matthew 28:6
The Resurrection of Jesus is one of the central truths of the gospel. 1 Cor. 15:1-8
What is the importance of Christ's resurrection to those who believe in Him?
1. It proves He is the Son of God. John 10:17-18, Romans 1:4
2. It guarantees the efficacy of His redemptive death. Ro. 6:4, 1Co. 15:17
3. It verifies the truth of the Scripture. Ps. 16:10, Acts 2:31
4. It is proof of the future judgement on the wicked. Acts 17: 30-31
5. It is the foundation of Christ's gift of the Holy Spirit and spiritual life to
His people. John 20:22, Romans 5:10, 1 Co. 15:45 and for His heavenly ministry
Of intercession for the believer ( Hebrews 7:23- 28)
6. It assuresbelievers of their future heavenly inheritance. ( 1 Peter 1:3-4 )
And of their resurrection or translation when the Lord returns ( Jn. 14:3 )
7. It makes available the presence of Christ and His power over sin in our
everyday experience ( Gal. 2:20, Eph. 1:18-20 ).


IV. In general terms, the believer's resurrected body will be like the Lord's own resurrected body.
Philippians 3:20-21
1. A body possessing continuity and identity with the body of this life and therefore
Recognizable ( Luke 16:19-31)
2. A body changed into heavenly body adoptedfor the new heaven and new earth.
1 Co. 15:42-44,47-48, Rev. 21:1
3. An imperishable body, free from decayand death. ( 1 Co. 15:42)
4. A glorifiedbody like Christ's. 1Co. 15:43, Phil. 3:20-21
5. A powerful body not subject to disease and weakness ( 1Co. 15:43 )
6. A spiritual ( not natural, but supernatural ) body, not bound by laws of nature. Luke 24:31
7. A body capableof eating and drinking .
Luke 24:36:48


V. When believers receive their new bodies, they put on immortality. 1 Co. 15:53
Scripture indicates at least 3 purposes for this;
1. So that believers may become all that God intended for humans at creation.
1 Co. 2:9-10
2. So that believers may come to know God in the full way.
He wants them to know Him. John 17:3
3. So that God may express His love to His children as He desires.
John 3:16
Eph. 2:7
1John 4:8-16


VI. Jesus speaks of a resurrection of life for the believer and a resurrection of judgement for the wicked .
John 5:28-29
28 "Do not be amazed at this, for a time is coming when all who are in their graves will hear his voice
29 and come out-those who have done good will rise to live, and those who have done evil will rise to be condemned.
''');

final _nb_Lesson38 = Lessons(
    lessonNumber: 38,
    lessonTitle: 'The Judgement of Believers',
    lessonBody:
        '''Aim: To teach the believers the biblical teaching of the Judgement of believers.

Introduction:
“When I stand before God at the end of my life, I would hope that I would not have a single bit of talent left, and could say, 'I used everything you gave me.” ― Erma Bombeck
2 Corinthians 5:10
10 For we must all appear before the judgment seat of Christ, that each one may receive what is due to him for the things done while in the body, whether good or bad.

The Bible teaches that believers will someday have to give an account at “the judgement seat of Christ." Concerning the judgement of believers, the following facts should be kept in mind;

1. All Christians will be subject to _Judgement, there will be no exceptions.
Romans 14:12, 1 Cor. 3:12-15, 2 Cor. 5:10

2. This judgement will occur when Christ returns for His church.
John 14:3, 1 Thess. 4:14-17

3. The judge is Chris.
John 5:22, 2 Tim. 4:8

4. The Bible speaks of the believer's judgement as something solemn and serious, especially since it includes the possibility of damage or "loss" ( 1Cor. 3:15; 2John 8), Of being ashamed before Him " at His coming" ( 1John 2:8) and of burning up of one's whole life's work ( 1 Cor. 3:13-15). The believers’ judgement, however, will not involve a declaration of condemnation by God.

5. Everything will be made Manifest. The word appear Gk. Phanee, 2 Cor. 5:10 means "to be revealed
Openly or publicly" God will examine and openly reveal, in its true reality.
A. Our secret acts. Mark 4:22, Ro. 2:16
B. Our character Romans 2:5-11
C. Our words Matthew 12:36-37
D. Our good deeds Eph. 6:8
E. Our attitudes Mark 5:22
F. Our motives1Cor. 4:5
G. Our lack of love Col. 3:18 - 4:1
H. And our work and ministry 1 Cor. 3:13

6. In sum, believers will have to give an account of their faithfulness or unfaithfulness to God ( Matt. 25:21,23, 1Cor. 4:2-5) and of their deeds in light of the grace, opportunity and understanding made available to them ( Luke 12:48, John 5:24, Ro. 8:1)

7. The believer's bad deeds, when repented of, are forgivenwith respect to eternal punishment ( Romans 8:1), but they are still taken into account when being judged for repayment:" he that doeth wrong shall receive for the wrong which he hath done" Col. 3:5, Ecc. 12:14, 1Cor. 3:15, 2 Co. 5:10). The believer's good deeds and love are remembered by God and rewarded ( He. 6:10):" Whatsoever good thing any man doeth, the same shall he receive of the Lord" ( Eph. 6:8).

8. The specific results of the believer's judgement will be varied. There will be either the gain or loss of joy ( 1John :28), divine approval ( Matthew 25:21), task and authority (Matt. 25:14-30), position (Matt. 5:19, 19:30), rewards ( 1 Cor. 3:12-14; Phil. 3:14,
2 Tim 4:8 and honor ( Rom. 2:10, 1 Peter 1:7)

9. The impending judgement of Christians should perfect in them the fear of the Lord
(2 Cor. 5:11; Phil. 2:12; 1 Pet. 1:17) and cause them to be clear minded and self-controlled, to watch and pray
(1 Peter 4:5,7), to live holy and godly lives ( 2 Peter 3:11), and to show mercy and kindness to all ( Matt. 5:7; 2Tim. 1:16-18).
''');

final _nb_Lesson39 = Lessons(
    lessonNumber: 39,
    lessonTitle: 'The White Throne Judgement',
    lessonBody:
        '''Aim: To teach the believers the biblical teaching of the White Throne judgement.

Introduction:
"In this teaching on the events of the last days or eschatology, the Lord is graciously unveiling the curtain of eternity to reveal to humanity His program for this present evil world. The doctrine of “The Great White Throne Judgment” opens our eyes to see a time to come when all wicked/ungodly people (the living and the dead, small and great who have neglected God’s salvation) will face the final judgement of the Living God" (Deeper Christian Life Ministries)
Question: "What is the Great White Throne Judgment?"
Answer: The great white throne judgment is described in Revelation 20:11-15 and is the final judgment prior to the lost being cast into the lake of fire. We know from Revelation 20:7-15 that this judgment will take place after the millennium and after Satan, the beast, and the false prophet are thrown into the lake of fire (Revelation 20:7-10). The books that are opened (Revelation 20:12) contain records of everyone’s deeds, whether they are good or evil, because God knows everything that has ever been said, done, or even thought, and He will reward or punish each one accordingly (Psalm 28:4; 62:12; Romans 2:6; Revelation 2:23; 18:6; 22:12).

Revelation 20:7-157 When the thousand years are over, Satan will be released from his prison 8 and will go out to deceive
the nations in the four corners of the earth—Gog and Magog—and to gather them for battle. In number they are like the sand on the seashore. 9 They marched across the breadth of the earth and surrounded the camp of God’s people, the city he loves. But fire came down from heaven and devoured them. 10 And the devil, who deceived them, was thrown into the lake of burning sulfur, where the beast and the false prophet had been thrown. They will be tormented day and night for ever and ever. 11 Then I saw a great white throne and him who was seated on it. The earth and the heavens fled from his presence, and there was no place for them. 12 And I saw the dead, great and small, standing before the throne, and books were opened. Another book was opened, which is the book of life. The dead were judged according to what they had done as recorded in the books. 13 The sea gave up the dead that were in it, and death and Hades gave up the dead that were in them, and each person was judged according to what they had done. 14 Then death and Hades were thrown into the lake of fire. The lake of fire is the second death. 15 Anyone whose name was not found written in the book of life was thrown into the
lake of fire.

Psalm 28:44 Repay them for their deeds and for their evil work; repay them for what their hands have done and bring back on them what they deserve.

Psalm 62:12 12 and with you, Lord, is unfailing love”; and, “You reward everyone according to what they have done.”

Romans 2:6 6 God “will repay each person according to what they have done.”

Revelation 2:2323 I will strike her children dead. Then all the churches will know that I am he who searches hearts and minds, and I will repay each of you according to your deeds.

Revelation 18:66 Give back to her as she has given; pay her back double for what she has done. Pour her a double portion from her own cup.

Revelation 22:1212 “Look, I am coming soon! My reward is with me, and I will give to each person according to what they
have done.

Also at this time, another book is opened, called the “book of life” (Revelation 20:12). It is this book that determines whether a person will inherit eternal life with God or receive everlasting punishment in the lake of fire. Although Christians are held accountable for their actions, they are forgiven in Christ and their names were written in the “book of life from the creation of the world” (Revelation 17:8). We also know from Scripture that it is at this judgment when the dead will be “judged according to what they had done” (Revelation 20:12) and that “anyone’s name” that is not “found written in the book of life” will be “thrown into the lake of fire” (Revelation 20:15).

Revelation 17:8 8 The beast, which you saw, once was, now is not, and yet will come up out of the Abyss and go to its destruction. The inhabitants of the earth whose names have not been written in the book of life from the creation of the world will be astonished when they see the beast, because it once was, now is not, and yet will come.
The fact that there is going to be a final judgment for all men, both believers and unbelievers, is clearly confirmed in many passages of Scripture. Every person will one day stand before Christ and be judged for his or her deeds. While it is very clear that the great white throne judgment is the final judgment, Christians disagree on how it relates to the other judgments mentioned in the Bible, specifically, who will be judged at the great white throne judgment.

TWO VIEWS ON THE WHITE THRONE JUDGEMENT
Some Christians believe that the Scriptures reveal three different judgments to come.
1. The first is the judgment of the sheep and the goats or a judgment of the nations (Matthew 25:31-36). This takes place after the tribulation period but prior to the millennium; its purpose is to determine who will enter the millennial kingdom.

Matthew 25:31-36 31 “When the Son of Man comes in his glory, and all the angels with him, he will sit on his glorious throne. 32 All the nations will be gathered before him, and he will separate the people one from another as a shepherd separates the sheep from the goats. 33 He will put the sheep on his right and the goats on his left. 34 “Then the King will say to those on his right, ‘Come, you who are blessed by my Father; take your inheritance, the kingdom prepared for you since the creation of the world. 35 For I was hungry and you gave me something to eat, I was thirsty and you gave me something to drink, I was a stranger and you invited me in, 36 I needed clothes and you clothed me, I was sick and you looked after me, I was in prison and you came to visit me.’
2. The second is a judgment of believers’ works, often referred to as the “judgment seat [bema] of Christ” (2 Corinthians 5:10). At this judgment, Christians will receive degrees of reward for their works or service to God.
2 Corinthians 5:1010 For we must all appear before the judgment seat of Christ, so that each of us may receive what is due us for the things done while in the body, whether good or bad.

3. The third is the great white throne judgment at the end of the millennium (Revelation 20:11-15). This is the judgment of unbelievers in which they are judged according to their works and sentenced to everlasting punishment in the lake of fire.
Other Christians believe that all three of these judgments speak of the same final judgment, not of three separate judgments. In other words, the great white throne judgment in Revelation 20:11-15 will be the time that believers and unbelievers alike are judged. Those whose names are found in the book of life will be judged for their deeds in order to determine the rewards they will receive or lose. Those whose names are not in the book of life will be judged according to their deeds to determine the degree of punishment they will receive in the lake of fire. Those who hold this view believe that Matthew 25:31-46 is another description of what takes place at the great white throne judgment. They point to the fact that the result of this judgment is the same as what is seen after the great white throne judgment in Revelation 20:11-15. The sheep (believers) enter into eternal life, while the goats (unbelievers) are cast into “eternal punishment” (Matthew 25:46).
Whichever view one holds of the great white throne judgment, it is important to never lose sight of the facts concerning the coming judgment(s). First, Jesus Christ will be the judge, all unbelievers will be judged by Christ, and they will be punished according to the works they have done. The Bible is very clear that unbelievers are storing up wrath against themselves (Romans 2:5) and that God will “give to each person according to what he has done” (Romans 2:6). Believers will also be judged by Christ, but since Christ’s righteousness has been imputed to us and our names are written in the book of life, we will be rewarded, but not punished, according to our deeds. Romans 14:10-12 says that we will all stand before the judgment seat of Christ and that each one of us will give an account to God.

Matthew 25:31-46 31 “When the Son of Man comes in his glory, and all the angels with him, he will sit on his glorious throne. 32 All the nations will be gathered before him, and he will separate the people one from another as a shepherd separates the sheep from the goats. 33 He will put the sheep on his right and the goats on his left. 34 “Then the King will say to those on his right, ‘Come, you who are blessed by my Father; take your inheritance, the kingdom prepared for you since the creation of the world. 35 For I was hungry and you gave me something to eat, I was thirsty and you gave me something to drink, I was a stranger and you invited me in, 36 I needed clothes and you clothed me, I was sick and you looked after me, I was in prison and you came to visit me.’ 37 “Then the righteous will answer him, ‘Lord, when did we see you hungry and feed you, or thirsty and give you something to drink?38 When did we see you a stranger and invite you in, or needing clothes and clothe you? 39 When did we see you sick or in prison and go to visit you?’ 40 “The King will reply, ‘Truly I tell you, whatever you did for one of the least of these brothers and sisters of mine, you did for me.’ 41 “Then he will say to those on his left, ‘Depart from me, you who are cursed, into the eternal fire prepared for the devil and his angels. 42 For I was hungry and you gave me nothing to eat, I was thirsty and you gave me nothing to drink, 43 I was a stranger and you did not invite me in, I needed clothes and you did not clothe me, I was sick and in prison and you did not look after me.’ 44 “They also will answer, ‘Lord, when did we see you hungry or thirsty or a stranger or needing clothes or sick or in prison, and did not help you?’ 45 “He will reply, ‘Truly I tell you, whatever you did not do for one of the least of these, you did not do for me.’
46 “Then they will go away to eternal punishment, but the righteous to eternal life.”

Romans 2:55 But because of your stubbornness and your unrepentant heart, you are storing up wrath against yourself for the day of God’s wrath, when his righteous judgment will be revealed.

Romans 2:66 God “will repay each person according to what they have done.”

Matthew 25:46 46 “Then they will go away to eternal punish
''');

final _nb_Lesson40 = Lessons(
    lessonNumber: 40,
    lessonTitle: 'The Tribulation',
    lessonBody:
        '''Aim: To teach the believers the biblical teaching of the Tribulation.

A. The Word “Tribulation” in Scripture.
In the Bible, the word “tribulation” is used in at least three different ways:

1. To apply to the trials and persecutions that the Christian believers will suffer throughout the Church age as a result of their identification with Christ: “In the world ye shall have tribulation: but be a good cheer; I have overcome the world” (Jn. 16:33)
33“I have told you these things, so that in me you may have peace. In this world you will have trouble. But take heart! I have overcome the world.”
John, in his first epistle, explains why we suffer with Christ in this world: “Therefore the world knoweth us not, because it knew Him not” (Jn. 3:1b). (See also 1Cor. 3:4; 2Thes. 1:4; Acts 14:22, Rom 12:12; Eph. 3:13; 2 Cor. 7:4)
John 3:1, Now there was a Pharisee, a man named Nicodemus who was a member of the Jewish ruling council.
1Cor. 3:4, For when one says, “I follow Paul,” and another, “I follow Apollos” are you not mere human beings?
2Thes. 1:4, Therefore, among God’s churches we boast about your perseverance and faith in all the persecutions and trials you are enduring.
Acts 14:22, strengthening the disciples and encouraging them to remain true to the faith. “We must go through many hardships to enter the kingdom of God,” they said.
Romans 12:12, Be joyful in hope, patient in affliction, faithful in prayer.
Eph. 3:13, I ask you, therefore, not to be discouraged because of my sufferings for you, which are your glory.
2 Cor. 7:4, I have spoken to you with great frankness; I take great pride in you. I am greatly encouraged; in all our troubles my joy knows no bounds.

2. To apply to a special period of tribulation for Israel prophesied by Daniel (9:24-27).
Jeremiah also makes reference to the same period calling it “Jacob’s trouble” (Jer 30:7-9). Jesus describes the Great Tribulation (Mt. 24:21) and confirms its application to Israel by the use of terms such as “Judea,” “the Sabbath day,” and “the abomination of desolation”) Dn 9:27) which refers to the desecration of the altar of the Jewish Temple by the Anti-Christ.
Daniel 9:24-2724 “Seventy ‘sevens’[a] are decreed for your people and your holy city to finish[b] transgression, to put an end to sin, to atone for wickedness, to bring in everlasting righteousness, to seal up vision and prophecy and to anoint the Most Holy Place.[c] 25 “Know and understand this: From the time the word goes out to restore and rebuild Jerusalem until the Anointed One,[d] the ruler, comes, there will be seven ‘sevens,’ and sixty-two ‘sevens.’ It will be rebuilt with streets and a trench, but in times of trouble. 26 After the sixty-two ‘sevens,’ the Anointed One will be put to death and will have nothing.[e] The people of the ruler who will come will destroy the city and the sanctuary. The end will come like a flood: War will continue until the end, and desolations have been decreed. 27 He will confirm a covenant with many for one ‘seven.’[f] In the middle of the ‘seven’ [g] he will put an end to sacrifice and offering. And at the temple[h] he will set up an abomination that causes desolation, until the end that is decreed is poured out on him.
Jeremiah 30:7-9,How awful that day will be! No other will be like it.It will be a time of trouble for Jacob, but he will be saved out of it. 8 “‘In that day,’ declares the LORD Almighty, ‘I will break the yoke off their necks and will tear off their bonds; no longer will foreigners enslave them. 9 Instead, they will serve the LORD their God and David their king, whom I will raise up for them.
Matthew 24:2121 For then there will be great distress, unequaled from the beginning of the world until now—and never to be equaled again.

3. To apply to God’s final wrath upon the Antichrist and the Gentile nations that follow him (Rv. 6:12-17), called the “Great Day of His Wrath.”
It is very important that the three different applications of the word “tribulation” be clearly distinguished. The fact that believers must be ready to suffer trials and tribulations throughout the Church age (Acts 14:14) does not mean that the Church must go through the “Great Tribulation” and the final hour of “God’s Wrath.” God has promised to keep the church saints from (Gr., ek, “out of”) the tribulation period (Rv. 3:10; 1 Thes. 5:9). Furthermore, the “Great Tribulation,” which is Daniel’s “seventieth week” of the seventy week period determined for dealing with Israel (Dn. 9:24-27; 12:8-13), is not a part of the Church age; when the “fullness of the Gentiles” comes, as Paul explains in Romans 11:25, the Church will be raptured, and God will turn again to effect the salvation of national Israel (Rom 11:24, 26; Rv. 7:4-8; Rv. 11, 12).
Revelation 6:12-1712 I watched as he opened the sixth seal. There was a great earthquake. The sun turned black like sackcloth made of goat hair, the whole moon turned blood red, 13 and the stars in the sky fell to earth, as figs drop from a fig tree when shaken by a strong wind.14 The heavens receded like a scroll being rolled up, and every mountain and island was removed from its place. 15 Then the kings of the earth, the princes, the generals, the rich, the mighty, and everyone else, both slave and free, hid in caves and among the rocks of the mountains. 16 They called to the mountains and the rocks, “Fall on us and hide us[a] from the face of him who sits on the throne and from the wrath of the Lamb! 17 For the great day of their[b] wrath has come, and who can withstand it?”
Acts 14:14,14 But when the apostles Barnabas and Paul heard of this, they tore their clothes and rushed out into the crowd, shouting:
Revelation 3:10, 10 Since you have kept my command to endure patiently, I will also keep you from the hour of trial that is going to come on the whole world to test the inhabitants of the earth.
1 Thessalonians. 5:9,9 For God did not appoint us to suffer wrath but to receive salvation through our Lord Jesus Christ.
Daniel 12:8-13,8 I heard, but I did not understand. So I asked, “My lord, what will the outcome of all this be?” 9 He replied, “Go your way, Daniel, because the words are rolled up and sealed until the time of the end. 10 Many will be purified, made spotless and refined, but the wicked will continue to be wicked. None of the wicked will understand, but those who are wise will understand. 11 “From the time that the daily sacrifice is abolished and the abomination that causes desolation is set up, there will be 1,290 days. 12 Blessed is the one who waits for and reaches the end of the 1,335 days. 13 “As for you, go your way till the end. You will rest, and then at the end of the days you will rise to receive your allotted inheritance.”


B. Daniel’s Dream and Vision.
Daniel also prophesied about times of world domination by Gentile nations (Nebuchadnezzar’s Image – Dn 2:31-44; Daniel’s dream of four beasts – Dn 7:1-14). The four parts of the image and the four beasts represented four successive Gentile empires, the last of which was to be the Roman Empire. According the dream of the image, the Roman Empire would be revived in the form of ten kingdoms, represented by the ten toes of the image. According to the vision of the four beasts, the fourth would have ten horns from which a “little horn,” symbolizing the Antichrist, would come forth. In both the dream and the vision, the Son of Man will come in the time of the fourth empire to punish the nations and to set up His everlasting kingdom (Dn 2:31-35; 7:8-14; 12:1-3). In Matthew chapter twenty-four, and in Luke chapter twenty one, Jesus makes clear that the Great Tribulation will include Daniel’s seventieth week of God’s dealing with Israel and His final wrath against Satan and the wicked Gentile nations that serve him. (See also Zec. 14:1-4; Rv 14:20, 16:14-16, 19:19)
Daniel 2:31-44,31 “Your Majesty looked, and there before you stood a large statue—an enormous, dazzling statue, awesome in appearance. 32 The head of the statue was made of pure gold, its chest and arms of silver, its belly and thighs of bronze, 33 its legs of iron, its feet partly of iron and partly of baked clay. 34 While you were watching, a rock was cut out, but not by human hands. It struck the statue on its feet of iron and clay and smashed them. 35 Then the iron, the clay, the bronze, the silver and the gold were all broken to pieces and became like chaff on a threshing floor in the summer. The wind swept them away without leaving a trace. But the rock that struck the statue became a huge mountain and filled the whole earth. 36 “This was the dream, and now we will interpret it to the king.37 Your Majesty, you are the king of kings. The God of heaven has given you dominion and power and might and glory; 38 in your hands he has placed all mankind and the beasts of the field and the birds in the sky. Wherever they live, he has made you ruler over them all. You are that head of gold.
39 “After you, another kingdom will arise, inferior to yours. Next, a third kingdom, one of bronze, will rule over the whole earth.40 Finally, there will be a fourth kingdom, strong as iron—for iron breaks and smashes everything—and as iron breaks things to pieces, so it will crush and break all the others. 41 Just as you saw that the feet and toes were partly of baked clay and partly of iron, so this will be a divided kingdom; yet it will have some of the strength of iron in it, even as you saw iron mixed with clay. 42 As the toes were partly iron and partly clay, so this kingdom will be partly strong and partly brittle. 43 And just as you saw the iron mixed with baked clay, so the people will be a mixture and will not remain united, any more than iron mixes with clay.44 “In the time of those kings, the God of heaven will set up a kingdom that will never be destroyed, nor will it be left to another people. It will crush all those kingdoms and bring them to an end, but it will itself endure forever.
Daniel 7:1-14, In the first year of Belshazzar king of Babylon, Daniel had a dream, and visions passed through his mind as he was lying in bed. He wrote down the substance of his dream.
2 Daniel said: “In my vision at night I looked, and there before me were the four winds of heaven churning up the great sea. 3 Four great beasts, each different from the others, came up out of the sea.4 “The first was like a lion, and it had the wings of an eagle. I watched until its wings were torn off and it was lifted from the ground so that it stood on two feet like a human being, and the mind of a human was given to it. 5 “And there before me was a second beast, which looked like a bear. It was raised up on one of its sides, and it had three ribs in its mouth between its teeth. It was told, ‘Get up and eat your fill of flesh!’6 “After that, I looked, and there before me was another beast, one that looked like a leopard. And on its back it had four wings like those of a bird. This beast had four heads, and it was given authority to rule. 7 “After that, in my vision at night I looked, and there before me was a fourth beast—terrifying and frightening and very powerful. It had large iron teeth; it crushed and devoured its victims and trampled underfoot whatever was left. It was different from all the former beasts, and it had ten horns. 8 “While I was thinking about the horns, there before me was another horn, a little one, which came up among them; and three of the first horns were uprooted before it. This horn had eyes like the eyes of a human being and a mouth that spoke boastfully.9 “As I looked, “thrones were set in place,
and the Ancient of Days took his seat. His clothing was as white as snow; the hair of his head was white like wool. His throne was flaming with fire, and its wheels were all ablaze. 10 A river of fire was flowing, coming out from before him. Thousands upon thousands attended him; ten thousand times ten thousand stood before him. The court was seated, and the books were opened. 11 “Then I continued to watch because of the boastful words the horn was speaking. I kept looking until the beast was slain and its body destroyed and thrown into the blazing fire. 12 (The other beasts had been stripped of their authority, but were allowed to live for a period of time.) 13 “In my vision at night I looked, and there before me was one like a son of man,[a] coming with the clouds of heaven. He approached the Ancient of Days and was led into his presence. 14 He was given authority, glory and sovereign power; all nations and peoples of every language worshiped him. His dominion is an everlasting dominion that will not pass away, and his kingdom is one that will never be destroyed.
Daniel 2:31-35,31 “Your Majesty looked, and there before you stood a large statue—an enormous, dazzling statue, awesome in appearance. 32 The head of the statue was made of pure gold, its chest and arms of silver, its belly and thighs of bronze, 33 its legs of iron, its feet partly of iron and partly of baked clay. 34 While you were watching, a rock was cut out, but not by human hands. It struck the statue on its feet of iron and clay and smashed them. 35 Then the iron, the clay, the bronze, the silver and the gold were all broken to pieces and became like chaff on a threshing floor in the summer. The wind swept them away without leaving a trace. But the rock that struck the statue became a huge mountain and filled the whole earth.
Daniel 7:8-14, 8 “While I was thinking about the horns, there before me was another horn, a little one, which came up among them; and three of the first horns were uprooted before it. This horn had eyes like the eyes of a human being and a mouth that spoke boastfully. 9 “As I looked, “thrones were set in place, and the Ancient of Days took his seat. His clothing was as white as snow; the hair of his head was white like wool. His throne was flaming with fire, and its wheels were all ablaze. 10 A river of fire was flowing, coming out from before him. Thousands upon thousands attended him; ten thousand times ten thousand stood before him. The court was seated, and the books were opened. 11 “Then I continued to watch because of the boastful words the horn was speaking. I kept looking until the beast was slain and its body destroyed and thrown into the blazing fire. 12 (The other beasts had been stripped of their authority, but were allowed to live for a period of time.) 13 “In my vision at night I looked, and there before me was one like a son of man,[a] coming with the clouds of heaven. He approached the Ancient of Days and was led into his presence. 14 He was given authority, glory and sovereign power; all nations and peoples of every language worshiped him. His dominion is an everlasting dominion that will not pass away, and his kingdom is one that will never be destroyed.
Daniel 12:1-3,“At that time Michael, the great prince who protects your people, will arise. There will be a time of distress such as has not happened from the beginning of nations until then. But at that time your people—everyone whose name is found written in the book—will be delivered. 2 Multitudes who sleep in the dust of the earth will awake: some to everlasting life, others to shame and everlasting contempt. 3 Those who are wise[a] will shine like the brightness of the heavens, and those who lead many to righteousness, like the stars for ever and ever.
Zec 14:1-4,A day of the LORD is coming, Jerusalem, when your possessions will be plundered and divided up within your very walls. 2 I will gather all the nations to Jerusalem to fight against it; the city will be captured, the houses ransacked, and the women raped. Half of the city will go into exile, but the rest of the people will not be taken from the city. 3 Then the LORD will go out and fight against those nations, as he fights on a day of battle. 4 On that day his feet will stand on the Mount of Olives, east of Jerusalem, and the Mount of Olives will be split in two from east to west, forming a great valley, with half of the mountain moving north and half moving south.
Revelation 14:20,They were trampled in the winepress outside the city, and blood flowed out of the press, rising as high as the horses’ bridles for a distance of 1,600 stadia.
Revelation 16:14-16, 14 They are demonic spirits that perform signs, and they go out to the kings of the whole world, to gather them for the battle on the great day of God Almighty. 15 “Look, I come like a thief! Blessed is the one who stays awake and remains clothed, so as not to go naked and be shamefully exposed.” 16 Then they gathered the kings together to the place that in Hebrew is called Armageddon.
Revelation 19:19,19 Then I saw the beast and the kings of the earth and their armies gathered together to wage war against the rider on the horse and his army.


C. Principal Events of the Tribulation.
1. The removal of the Church and the Restrainer of evil (2 Thes 2:1, 7, 8).
1 Thessalonians 2:1,7,8, Concerning the coming of our Lord Jesus Christ and our being gathered to him, we ask you, brothers and sisters,
7 For the secret power of lawlessness is already at work; but the one who now holds it back will continue to do so till he is taken out of the way. 8 And then the lawless one will be revealed, whom the Lord Jesus will overthrow with the breath of his mouth and destroy by the splendor of his coming.

2. Restoration of the daily sacrifice in a rebuilt temple by covenant with the Antichrist (Dn 9:27).
Daniel 9:27,27 He will confirm a covenant with many for one ‘seven.’[a] In the middle of the ‘seven’[b] he will put an end to sacrifice and offering. And at the temple[c] he will set up an abomination that causes desolation, until the end that is decreed is poured out on him.

3. Outpouring of judgments resulting from the opening of the seven seals (Rv. 6:1, 8:1).

4. Outpouring of judgments from the sounding of the seven trumpets (Rv. 8:6-11:15)

5. The taking away of the daily sacrifice by the Antichrist, and the setting up of the abomination of desolation (Dn 9:27; 12:10,11; Mt. 24:15).
Mathew. 24:15,15 “So when you see standing in the holy place ‘the abomination that causes desolation,’[a] spoken of through the prophet Daniel—let the reader understand—
(This happens in the middle of the seven years, which are divided into two parts
of three and one half years: Rv. 11:2,3; Dn. 9:27, 12:11; Rv. 12:14. The latter half is considered to be the “Great Tribulation.”)
Rev. 12:14,14 The woman was given the two wings of a great eagle, so that she might fly to the place prepared for her in the wilderness, where she would be taken care of for a time, times and half a time, out of the serpent’s reach.

6. Increased persecution of Israel (Rev 12); 144,000 Jews from the twelve tribes are sealed (Rev 7:1-8); an innumerable company of Tribulation, are taken to Heaven (Rv. 7:9-17).

7. Total control by the Beast and the False Prophet; the introduction of the mark of the Beast and his number, with compulsory worship of the Beast’s image (Rev 13).

8. The judgments resulting from the outpouring of the seven vials of wrath (Rev 15, 16).

9. Judgment upon the Harlot, mystery Babylon (Rev 17, 18), who probably represents apostate religion.
(After the Rapture of the true Church, organized religion with a “form of godliness but denying the power thereof” will become increasingly corrupt, even aligning herself with the Beast’s government.)

10. Gathering of the kings of the East and armies of the Anti-Christ (Beast) to make war with the remnant of Israel, resulting in the battle of Armageddon (Rv. 12:17,16:2-16).

11. Celebration of the Marriage Supper of the Lamb (Rv. 19:6-9).

12. Christ returns with His armies of saints to confront the Beast and his armies, and the Beast’s armies are destroyed by the brightness of Christ’s Coming (Rv. 19:14-21; 2 Thes 2:8).

13. The Beast and the False Prophet are cast into the Lake of Fire (Rv. 19:20)
Rv. 19:20,20 But the beast was captured, and with it the false prophet who had
performed the signs on its behalf. With these signs he had deluded those who had received the mark of the beast and worshiped its image. The two of them were thrown alive into the fiery lake of burning sulfur.

14. Satan is cast into the Bottomless Pit (the abyss) for one thousand years (Rv. 20:1-3)
Rv. 20:1-3,And I saw an angel coming down out of heaven, having the key to
the Abyss and holding in his hand a great chain. 2 He seized the dragon, that ancient serpent, who is the devil, or Satan, and bound him for a thousand years. 3 He threw him into the Abyss, and locked and sealed it over him, to keep him from deceiving the nations anymore until the thousand years were ended. After that, he must be set free for a short time.
''');

final _nb_Lesson41 = Lessons(
    lessonNumber: 41,
    lessonTitle: 'The Antichrist',
    lessonBody:
        '''Aim: To teach the believers the biblical teaching of the Antichrist.

A. The Word “Antichrist” in Scripture.
The word “antichrist” comes from two Greek words christos meaning “Christ” or the “anointed one”; and anti meaning in this combination “against”; thus, “the one against Christ, God’s anointed.” The name “antichrist’, is found only in John’s epistles (1Jn 2:18, 22; 4:3; 2 Jn 7), where he is described as one coming in the last time, and one whose spirit is already present in the world. The spirit of antichrist will be embodied in the “beast” described in Revelation 13:1; 11:7. The first prophetic reference to Antichrist is probably found in Genesis 3:15: “And I will put enmity between thee and the woman and between THY SEED and HER SEED….” Christ is the SEED of woman. Antichrist is the SEED of Satan or the “Devil,” whose name means “slanderer,” who speaks against Christ and against His Redeemed.

1 John 2:18, 2018 Dear children, this is the last hour; and as you have heard that the antichrist is coming, even now many antichrists have come. This is how we know it is the last hour. 22 Who is the liar? It is whoever denies that Jesus is the Christ. Such a person is the antichrist—denying the Father and the Son.

1 John 4:3, 3 but every spirit that does not acknowledge Jesus is not from God. This is the spirit of the antichrist, which you have heard is coming and even now is already in the world.

Revelation 13:1, 1The dragon[a] stood on the shore of the sea. And I saw a beast coming out of the sea. It had ten horns and seven heads, with ten crowns on its horns, and on each head a blasphemous name.

B. The Identity of the Antichrist
The spirit of antichrist has possessed many enemies of God through the ages, such as “the kings of Babylon,” a type of Satan (Is. 14:4-17). The name “Mystery Babylon” is borne by the “great harlot” of Revelation 17:5, for she is the embodiment of anti-God religion. Many anti-christian rulers and evil men of power have been identified as the “Antichrist” through history, such as: Nero, Napoleon, Kaisar Wilhelm, Mussolini, Hitler, Stalin, etc. Some of these were no doubt motivated by the spirit of antichrist, but THE Antichrist is yet to come. He may be somewhere in the world already, but he will not be revealed until after the Rapture of the Church; so it is rather futile to try to identify him. The spirit of antichrist will continue to possess any vehicle yielded to Satan.
Isaiah 14:4-17, 4 you will take up this taunt against the king of Babylon: How the oppressor has come to an end! How his fury[a] has ended! 5 The LORD has broken the rod of the wicked, the scepter of the rulers, 6 which in anger struck down peoples with unceasing blows, and in fury subdued nations with relentless aggression. 7 All the lands are at rest and at peace; they break into singing. 8 Even the junipers and the cedars of Lebanon gloat over you and say, “Now that you have been laid low, no one comes to cut us down.” 9 The realm of the dead below is all astir to meet you at your coming; it rouses the spirits of the departed to greet you— all those who were leaders in the world; it makes them rise from their thrones— all those who were kings over the nations. 10 They will all respond, they will say to you, “You also have become weak, as we are; you have become like us.” 11 All your pomp has been brought down to the grave, along with the noise of your harps; maggots are spread out beneath you and worms cover you. 12 How you have fallen from heaven, morning star, son of the dawn! You have been cast down to the earth, you who once laid low the nations! 13 You said in your heart, “I will ascend to the heavens; I will raise my throne above the stars of God; I will sit enthroned on the mount of assembly, on the utmost heights of Mount Zaphon.[b]14 I will ascend above the tops of the clouds; I will make myself like the Most High.” 15 But you are brought down to the realm of the dead, to the depths of the pit. 16 Those who see you stare at you, they ponder your fate: “Is this the man who shook the earth and made kingdoms tremble,7 the man who made the world a wilderness, who overthrew its cities and would not let his captives go home?”
Revelation 17:5, 5 The name written on her forehead was a mystery: BABYLON THE GREAT
THE MOTHER OF PROSTITUTES AND OF THE ABOMINATIONS OF THE EARTH.

C. The Titles of Antichrist.

1. The Beast - Rv. 13:1-4, 12-18; 15:2; 16:2; 17:8; 19:19; 20:4, 10.

Revelation 13:1-4, 12-8, The dragon[a] stood on the shore of the sea. And I saw a beast coming out of the sea. It had ten horns and seven heads, with ten crowns on its horns, and on each head a blasphemous name. 2 The beast I saw resembled a leopard, but had feet like those of a bear and a mouth like that of a lion. The dragon gave the beast his power and his throne and great authority. 3 One of the heads of the beast seemed to have had a fatal wound, but the fatal wound had been healed. The whole world was filled with wonder and followed the beast. 4 People worshiped the dragon because he had given authority to the beast, and they also worshiped the beast and asked, “Who is like the beast? Who can wage war against it?” 12 It exercised all the authority of the first beast on its behalf, and made the earth and its inhabitants worship the first beast, whose fatal wound had been healed. 13 And it performed great signs, even causing fire to come down from heaven to the earth in full view of the people. 14 Because of the signs it was given power to perform on behalf of the first beast, it deceived the inhabitants of the earth. It ordered them to set up an image in honor of the beast who was wounded by the sword and yet lived. 15 The second beast was given power to give breath to the image of the first beast, so that the image could speak and cause all who refused to worship the image to be killed. 16 It also forced all people, great and small, rich and poor, free and slave, to receive a mark on their right hands or on their foreheads, 17 so that they could not buy or sell unless they had the mark, which is the name of the beast or the number of its name. 18 This calls for wisdom. Let the person who has insight calculate the number of the beast, for it is the number of a man.[a] That number is 666.

Revelation 15:2, 2 And I saw what looked like a sea of glass glowing with fire and, standing beside the sea, those who had been victorious over the beast and its image and over the number of its name. They held harps given them by God

16:2, 2 The first angel went and poured out his bowl on the land, and ugly, festering sores broke out on the people who had the mark of the beast and worshiped its image.

17:8, 8 The beast, which you saw, once was, now is not, and yet will come up out of the Abyss and go to its destruction. The inhabitants of the earth whose names have not been written in the book of life from the creation of the world will be astonished when they see the beast, because it once was, now is not, and yet will come.

19:19, 19 Then I saw the beast and the kings of the earth and their armies gathered together to wage war against the rider on the horse and his army.

20:4, 4 I saw thrones on which were seated those who had been given authority to judge. And I saw the souls of those who had been beheaded because of their testimony about Jesus and because of the word of God. They[a] had not worshiped the beast or its image and had not received its mark on their foreheads or their hands. They came to life and reigned with Christ a thousand years.

2. The Little Horn – Dn. 7:8; 8:9.
He shall rise up from among rulers of the revived Roman Empire. The “little horn” of Daniel 8:9 is Antiochus Epiphanes (170 B.C.), the Syrian ruler who persecuted the Jews and defiled the Temple in the time of the Maccabees (Macc. 1:10-47); therefore, he is a type of Antichrist.
Daniel 7:8, 8 “While I was thinking about the horns, there before me was another horn, a little one, which came up among them; and three of the first horns were uprooted before it. This horn had eyes like the eyes of a human being and a mouth that spoke boastfully.

Daniel 8:9, 9 Out of one of them came another horn, which started small but grew in power to the south and to the east and toward the Beautiful Land.

3. The Man of Sin – 2 Thes. 2:3.
2 Thes 2:3, 3 Don’t let anyone deceive you in any way, for that day will not come until the rebellion occurs and the man of lawlessness[a] is revealed, the man doomed to destruction.

He will be history’s vilest embodiment of sin and rebellion.

4. The Son of Perdition – 2 Thes 2:3.
Another title of the Man of Sin. Satan’s tool to seduce men and consign them to the realm of the lost.
2 Thes 2:3, 3 Don’t let anyone deceive you in any way, for that day will not come until the rebellion occurs and the man of lawlessness[a] is revealed, the man doomed to destruction.
5. The Wicked One – 2 Thes 2:8.
“Wicked” is from the Greek, anomos, which means the “lawless one.” He totally opposes every law of God.
2 Thes 2:8, 8 And then the lawless one will be revealed, whom the Lord Jesus will overthrow with the breath of his mouth and destroy by the splendor of his coming.

6. The Willful King – Dn. 11:36-45.
Jesus prayed, “Not my will but thine be done’; the Antichrist will oppose God’s Will and do his own will; he is the inspirer of all those who “do their own thing.”

Daniel 11:36-4536 “The king will do as he pleases. He will exalt and magnify himself above every god and will say unheard-of things against the God of gods. He will be successful until the time of wrath is completed, for what has been determined must take place. 37 He will show no regard for the gods of his ancestors or for the one desired by women, nor will he regard any god, but will exalt himself above them all. 38 Instead of them, he will honor a god of fortresses; a god unknown to his ancestors he will honor with gold and silver, with precious stones and costly gifts. 39 He will attack the mightiest fortresses with the help of a foreign god and will greatly honor those who acknowledge him. He will make them rulers over many people and will distribute the land at a price.[a] 40 “At the time of the end the king of the South will engage him in battle, and the king of the North will storm out against him with chariots and cavalry and a great fleet of ships. He will invade many countries and sweep through them like a flood. 41 He will also invade the Beautiful Land. Many countries will fall, but Edom, Moab and the leaders of Ammon will be delivered from his hand. 42 He will extend his power over many countries; Egypt will not escape.43 He will gain control of the treasures of gold and silver and all the riches of Egypt, with the Libyans and Cushites[b] in submission.44 But reports from the east and the north will alarm him, and he will set out in a great rage to destroy and annihilate many. 45 He will pitch his royal tents between the seas at[c] the beautiful holy mountain. Yet he will come to his end, and no one will help him.

7. The Foolish Shepherd – Zec. 11:15-17.
Jesus is the Good Shepherd who preserves; Antichrist is the worthless shepherd who devours.

Zechariah 11:15-17, 15 Then the LORD said to me, “Take again the equipment of a foolish shepherd. 16 For I am going to raise up a shepherd over the land who will not care for the lost, or seek the young, or heal the injured, or feed the healthy, but will eat the meat of the choice sheep, tearing off their hooves. 17 “Woe to the worthless shepherd, who deserts the flock! May the sword strike his arm and his right eye! May his arm be completely withered, his right eye totally blinded!”

D. The Works of Antichrist.
1. He is the last ruler of the revived Roman Empire – Dn 7:8; Rv. 13:1.
Daniel 7:8, 8 “While I was thinking about the horns, there before me was another horn, a little one, which came up among them; and three of the first horns were uprooted before it. This horn had eyes like the eyes of a human being and a mouth that spoke boastfully.

Revelation 13:1, The dragon[a] stood on the shore of the sea. And I saw a beast coming out of the sea. It had ten horns and seven heads, with ten crowns on its horns, and on each head a blasphemous name.

2. He will appear on the scene as a proponent of peace who is tolerant of religion – Dn. 9:27; Rv. 6:2; Dn. 8:25; 1Thes. 5:3.
Daniel 9:27, 27 He will confirm a covenant with many for one ‘seven.’[a] In the middle of the ‘seven’[b] he will put an end to sacrifice and offering. And at the temple[c] he will set up an abomination that causes desolation, until the end that is decreed is poured out on him.[d]”[e]

Revelation 6:2, 2 I looked, and there before me was a white horse! Its rider held a bow, and he was given a crown, and he rode out as a conqueror bent on conquest.

Daniel 8:25, 25 He will cause deceit to prosper, and he will consider himself superior. When they feel secure, he will destroy many and take his stand against the Prince of princes. Yet he will be destroyed, but not by human power.

1 Thessalonians 5:3, 3 While people are saying, “Peace and safety,” destruction will come on them suddenly, as labor pains on a pregnant woman, and they will not escape.
3. He will arise after the Rapture of the Church and at the beginning of the seventieth week of Daniel, when God sets His hand to deal again with national Israel, and he will make a covenant with the Jews to restore the daily sacrifice – Dn. 9:24-27.

1 Thessalonians 5:3, 24 “Seventy ‘sevens’[a] are decreed for your people and your holy city to finish[b] transgression, to put an end to sin, to atone for wickedness, to bring in everlasting righteousness, to seal up vision and prophecy and to anoint the Most Holy Place.[c]
25 “Know and understand this: From the time the word goes out to restore and rebuild Jerusalem until the Anointed One,[d] the ruler, comes, there will be seven ‘sevens,’ and sixty-two ‘sevens.’ It will be rebuilt with streets and a trench, but in times of trouble. 26 After the sixty-two ‘sevens,’ the Anointed One will be put to death and will have nothing.[e] The people of the ruler who will come will destroy the city and the sanctuary. The end will come like a flood: War will continue until the end, and desolations have been decreed. 27 He will confirm a covenant with many for one ‘seven.’[f]In the middle of the ‘seven’[g] he will put an end to sacrifice and offering. And at the temple[h] he will set up an abomination that causes desolation, until the end that is decreed is poured out on him.[i]”[j]

4. After three and one half years, in the middle of the Tribulation, he will cast off all pretense of toleration, break his covenant with the Jews, cause the daily sacrifice to cease, and begin his persecution of Israel – Rv. 13:7,8.

5. One of his heads will received a deadly wound, then be miraculously healed causing the wonderment and worship of the whole world – Rv. 13:3,4.

6. As the Man of Sin and Lawless One he will blaspheme God, then require the worship of all men with the threat of death – Rv. 13:7,8.

7. The third member of the satanic trinity for the Dragon, the Beast and the False Prophet arises; causes men to worship the Beast, creates an image of the Beast to which he gives life, and causes all men to take a mark or number of the Beast in order to buy or sell – Rv. 13:11-18.

8. During the Tribulation, the Beast sponsors the great Harlot who represents apostate religion, but finally the Beast together with the ten kings who rule with the Beast utterly destroy the scarlet woman – Rv. 17.
The woman is said to be “that great city that reigneth over the kings of the earth” (Rv. 17-18); the city is situated on “seven mountains” (17:9). (Scholars are divided as to whether the city is Rome or Babylon.)

9. The Beast gathers his subject nations together to make war with the Lamb at the Battle of Armageddon, where he is utterly defeated and cast, together with False Prophet, into the Lake of Fire – Rv. 16:16; 17:14; 19:19, 20.

Revelation 13:11-18, Then I saw a second beast, coming out of the earth. It had two horns like a lamb, but it spoke like a dragon. 12 It exercised all the authority of the first beast on its behalf, and made the earth and its inhabitants worship the first beast, whose fatal wound had been healed. 13 And it performed great signs, even causing fire to come down from heaven to the earth in full view of the people.14 Because of the signs it was given power to perform on behalf of the first beast, it deceived the inhabitants of the earth. It ordered them to set up an image in honor of the beast who was wounded by the sword and yet lived. 15 The second beast was given power to give breath to the image of the first beast, so that the image could speak and cause all who refused to worship the image to be killed.16 It also forced all people, great and small, rich and poor, free and slave, to receive a mark on their right hands or on their foreheads,17 so that they could not buy or sell unless they had the Mark, which is the name of the beast or the number of its name. 18 This calls for wisdom. Let the person who has insight calculate the number of the beast, for it is the number of a man.[a] That number is 666.

Revelation 17:99 “This calls for a mind with wisdom. The seven heads are seven hills on which the woman sits.

Revelation 17:1414 They will wage war against the Lamb, but the Lamb will triumph over them because he is Lord of lords and King of kings—and with him will be his called, chosen and faithful followers.”

Revelation 16:16,16 Then they gathered the kings together to the place that in Hebrew is called Armageddon.

Revelation 19:19-20,19 Then I saw the beast and the kings of the earth and their armies gathered together to wage war against the rider on the horse and his army. 20 But the beast was captured, and with it the false prophet who had performed the signs on its behalf. With these signs he had deluded those who had received the mark of the beast and worshiped its image. The two of them were thrown alive into the fiery lake of burning sulfur.
