final _nb_Lesson42 = Lessons(
    lessonNumber: 42,
    lessonTitle: 'The Resurrection',
    lessonBody:
        '''Aim: To teach the believers the biblical teaching of the Resurrection.

Almost all religions teach the immortality of the soul; but the Bible teaches the redemption of and the survival of the total person – spirit, soul and body. The ancient Greeks believed in life after death for the soul, but since the body was the source of all evil, release of the soul from the body was desirable. A heretical Christian sect called “Gnostics” shared this concept derived from Greek philosophy. The Bible does not teach that the physical body is the source of evil; the Pauline term “flesh” refers to man’s sinful and selfish nature which, while it manifests itself through actions of the body, derives from a “carnal mind” (Rom. 8:6,7). Christ’s taking our human body (the “likeness of sinful flesh”), “condemned sin in the flesh.” (Rom. 8:3) Christ by His Incarnation, Death and Resurrection redeemed the total person who is in Christ, giving him a hope of a bodily resurrection which will occur at the Rapture of the Church. “For since by man came death, by man came also the resurrection of the dead. For as in Adam all die, even so in Christ the firstfruits; afterward they that are Christ’s at His coming” (1 Cor. 15:21-23).

Rom. 8:6,7, 6 The mind governed by the flesh is death, but the mind governed by the Spirit is life and peace. 7 The mind governed by the flesh is hostile to God; it does not submit to God’s law, nor can it do so.

Rom. 8:3,3 For what the law was powerless to do because it was weakened by the flesh,[a] God did by sending his own Son in the likeness of sinful flesh to be a sin offering.[b] And so he condemned sin in the flesh,

1 Cor. 15:21-23, 21 For since death came through a man, the resurrection of the dead comes also through a man. 22 For as in Adam all die, so in Christ all will be made alive. 23 But each in turn: Christ, the firstfruits; then, when he comes, those who belong to him.


A. The Fact of the Resurrection.
The fact of the Resurrection is taught in both the Old and the New Testament:

1. In the Old Testament.
a. By affirmation: “For I know that my Redeemer lives, and He shall stand at last on the earth; and after my skin is destroyed, this I KNOW that IN MY FLESH I shall see God” (Jb. 19:25, NKJV). “As for me, I will behold thy face in righteousness: I shall be satisfied, when I awake with thy likeness” (Ps 17:15). (See also Ps. 16:9-11; Dn. 12:2)

Jb. 19:25,25 I know that my redeemer[a] lives, and that in the end he will stand on the earth.

Ps 17:15,15 As for me, I will be vindicated and will see your face; when I awake, I will be satisfied with seeing your likeness.

Ps. 16:9-11,9 Therefore my heart is glad and my tongue rejoices; my body also will rest secure, 10 because you will not abandon me to the realm of the dead, nor will you let your faithful[a] one see decay. 11 You make known to me the path of life; you will fill me with joy in your presence, with eternal pleasures at your right hand.

Dn. 12:2, 2 Multitudes who sleep in the dust of the earth will awake: some to everlasting life, others to shame and everlasting contempt.

b. By prophecy: “Thy dead men shall live, together with my dead body shall they arise. Awake and sing, ye that dwell in dust: for thy dew is like the dew herbs, and the earth shall cast out the dead” (Is 26:19). (Also Hos. 13:14)

Is 26:19,19 But your dead will live, LORD; their bodies will rise— let those who dwell in the lust wake up and shout for joy— your dew is like the dew of the morning; the earth will give birth to her dead.

Hos. 13:14, 14 “I will deliver this people from the power of the grave; I will redeem them from death. Where, O death, are your plagues? Where, O grave, is your destruction? “I will have no compassion,

c. By typology: events such as Joseph’s deliverance from the pit are typical of death and resurrection (Gn. 37:20-36), as are Isaac’s return from the altar of sacrifice (Gn 22:5-14), and Jonah’s deliverance from the great fish (commonly called, whale) (Jon 2; Mt. 12:40)

Gn. 37:20-36,20 “Come now, let’s kill him and throw him into one of these cisterns and say that a ferocious animal devoured him. Then we’ll see what comes of his dreams.” 21 When Reuben heard this, he tried to rescue him from their hands. “Let’s not take his life,” he said. 22 “Don’t shed any blood. Throw him into this cistern here in the wilderness, but don’t lay a hand on him.” Reuben said this to rescue him from them and take him back to his father. 23 So when Joseph came to his brothers, they stripped him of his robe—the ornate robe he was wearing— 24 and they took him and threw him into the cistern. The cistern was empty; there was no water in it. 25 As they sat down to eat their meal, they looked up and saw a caravan of Ishmaelites coming from Gilead. Their camels were loaded with spices, balm and myrrh, and they were on their way to take them down to Egypt. 26 Judah said to his brothers, “What will we gain if we kill our brother and cover up his blood? 27 Come, let’s sell him to the Ishmaelites and not lay our hands on him; after all, he is our brother, our own flesh and blood.” His brothers agreed. 28 So when the Midianite merchants came by, his brothers pulled Joseph up out of the cistern and sold him for twenty shekels[a] of silver to the Ishmaelites, who took him to Egypt. 29 When Reuben returned to the cistern and saw that Joseph was not there, he tore his clothes. 30 He went back to his brothers and said, “The boy isn’t there! Where can I turn now?” 31 Then they got Joseph’s robe, slaughtered a goat and dipped the robe in the blood. 32 They took the ornate robe back to their father and said, “We found this. Examine it to see whether it is your son’s robe.” 33 He recognized it and said, “It is my son’s robe! Some ferocious animal has devoured him. Joseph has surely been torn to pieces.” 34 Then Jacob tore his clothes, put on sackcloth and mourned for his son many days. 35 All his sons and daughters came to comfort him, but he refused to be comforted. “No,” he said, “I will continue to mourn until I join my son in the grave.” So his father wept for him. 36 Meanwhile, the Midianites[b] sold Joseph in Egypt to Potiphar, one of Pharaoh’s officials, the captain of the guard.

Gn 22:5-14,5 He said to his servants, “Stay here with the donkey while I and the boy go over there. We will worship and then we will come back to you.” 6 Abraham took the wood for the burnt offering and placed it on his son Isaac, and he himself carried the fire and the knife. As the two of them went on together,7 Isaac spoke up and said to his father Abraham, “Father?” “Yes, my son?” Abraham replied. “The fire and wood are here,” Isaac said, “but where is the lamb for the burnt offering?” 8 Abraham answered, “God himself will provide the lamb for the burnt offering, my son.” And the two of them went on together. 9 When they reached the place God had told him about, Abraham built an altar there and arranged the wood on it. He bound his son Isaac and laid him on the altar, on top of the wood. 10 Then he reached out his hand and took the knife to slay his son. 11 But the angel of the LORD called out to him from heaven, “Abraham! Abraham!” “Here I am,” he replied. 12 “Do not lay a hand on the boy,” he said. “Do not do anything to him. Now I know that you fear God, because you have not withheld from me your son, your only son.” 13 Abraham looked up and there in a thicket he saw a ram[a] caught by its horns. He went over and took the ram and sacrificed it as a burnt offering instead of his son. 14 So Abraham called that place The LORD Will Provide. And to this day it is said, “On the mountain of the LORD it will be provided.”

Mt. 12:40, 40 For as Jonah was three days and three nights in the belly of a huge fish, so the Son of Man will be three days and three nights in the heart of the earth.

d. By example: the Old Testament contains several examples of persons who were raised form the dead: 1 Kgs. 17:17-24; 2Kgs 4:32-35; 13:20, 21. While these are cases of resuscitation rather than resurrection (for those who were raised died natural deaths later), they demonstrate God’s power and disposition to restore dead bodies to life.

1 Kgs. 17:17-24,17 Sometime later the son of the woman who owned the house became ill. He grew worse and worse, and finally stopped breathing. 18 She said to Elijah, “What do you have against me, man of God? Did you come to remind me of my sin and kill my son?” 19 “Give me your son,” Elijah replied. He took him from her arms, carried him to the upper room where he was staying, and laid him on his bed. 20 Then he cried out to the LORD, “LORD my God, have you brought tragedy even on this widow I am staying with, by causing her son to die?” 21 Then he stretched himself out on the boy three times and cried out to the LORD, “LORD my God, let this boy’s life return to him!” 22 The LORD heard Elijah’s cry, and the boy’s life returned to him, and he lived. 23 Elijah picked up the child and carried him down from the room into the house. He gave him to his mother and said, “Look, your son is alive!” 24 Then the woman said to Elijah, “Now I know that you are a man of God and that the word of the LORD from your mouth is the truth.”

2Kgs 4:32-35, 32 When Elisha reached the house, there was the boy lying dead on his couch. 33 He went in, shut the door on the two of them and prayed to the LORD. 34 Then he got on the bed and lay on the boy, mouth to mouth, eyes to eyes, hands to hands. As he stretched himself out on him, the boy’s body grew warm. 35 Elisha turned away and walked back and forth in the room and then got on the bed and stretched out on him once more. The boy sneezed seven times and opened his eyes.

2Kgs 13:20, 21, 20 Elisha died and was buried. Now Moabite raiders used to enter the country every spring. 21 Once while some Israelites were burying a man, suddenly they saw a band of raiders; so they threw the man’s body into Elisha’s tomb. When the body touched Elisha’s bones, the man came to life and stood up on his feet.

2. In the New Testament.

a. By affirmation: “So also is the resurrection of the dead. It is sown in corruption; it is raised in incorruption; it is raised in incorruption: it is sown dishonor; it is raise in glory: it is sown in weakness: it is raised in power…” (1 Cor 15:42, 43) (See also Mt. 22:30-32; Jn. 5:21; Acts 23:6-8; 26:8, 23; 2Tm 1:10; 1Pt 1:3.)

1 Cor 15:42, 43, 42 So will it be with the resurrection of the dead. The body that is sown is perishable, it is raised imperishable; 43 it is sown in dishonor, it is raised in glory; it is sown in weakness, it is raised in power;

Mt. 22:30-32,30 At the resurrection people will neither marry nor be given in marriage; they will be like the angels in heaven.31 But about the resurrection of the dead—have you not read what God said to you, 32 ‘I am the God of Abraham, the God of Isaac, and the God of Jacob’[a]? He is not the God of the dead but of the living.”

Jn. 5:21,21 For just as the Father raises the dead and gives them life, even so the Son gives life to whom he is pleased to give it.

Acts 23:6-8, 23,6 Then Paul, knowing that some of them were Sadducees and the others Pharisees, called out in the Sanhedrin, “My brothers, I am a Pharisee, descended from Pharisees. I stand on trial because of the hope of the resurrection of the dead.” 7 When he said this, a dispute broke out between the Pharisees and the Sadducees, and the assembly was divided. 8 (The Sadducees say that there is no resurrection, and that there are neither angels nor spirits, but the Pharisees believe all these things.) 23 Then he called two of his centurions and ordered them, “Get ready a detachment of two hundred soldiers, seventy horsemen and two hundred spearmen[a] to go to Caesarea at nine tonight.
2Tm 1:10,10 but it has now been revealed through the appearing of our Savior, Christ Jesus, who has destroyed death and has brought life and immortality to light through the gospel.
1Pt 1:3,3 Praise be to the God and Father of our Lord Jesus Christ! In his great mercy he has given us new birth into a living hope through the resurrection of Jesus Christ from the dead,

b. By prophecy: “Marvel not at this: for the hour is coming, in which all that are in the graves shall hear His voice, and shall come forth; they that have done good, unto the resurrection of life; and they that have done evil, unto the resurrection of damnation” (Jn 5:28, 29). (See also Jn. 6:39, 40, 44,54; Lk. 14:13, 14; 20:35, 36; 1 Cor 15; Phil 3:11, 21; 1 Thes 4:14-16, Rv. 20:4-6, 13-15.)

Jn 5:28, 29, 28 “Do not be amazed at this, for a time is coming when all who are in their graves will hear his voice 29 and come out—those who have done what is good will rise to live, and those who have done what is evil will rise to be condemned.

Jn. 6:39, 40, 44,54, 39 And this is the will of him who sent me, that I shall lose none of all those he has given me, but raise them up at the last day. 40 For my Father’s will is that everyone who looks to the Son and believes in him shall have eternal life, and I will raise them up at the last day.” 44 “No one can come to me unless the Father who sent me draws them, and I will raise them up at the last day. 54 Whoever eats my flesh and drinks my blood has eternal life, and I will raise them up at the last day.

Lk. 14:13, 14,13 But when you give a banquet, invite the poor, the crippled, the lame, the blind, 14 and you will be blessed. Although they cannot repay you, you will be repaid at the resurrection of the righteous.”

Lk. 20:35, 3635 But those who are considered worthy of taking part in the age to come and in the resurrection from the dead will neither marry nor be given in marriage, 36 and they can no longer die; for they are like the angels. They are God’s children, since they are children of the resurrection.

Phil 3:11,21, 11 and so, somehow, attaining to the resurrection from the dead. 21 who, by the power that enables him to bring everything under his control, will transform our lowly bodies so that they will be like his glorious body.

1 Thes 4:14-16, 14 For we believe that Jesus died and rose again, and so we believe that God will bring with Jesus those who have fallen asleep in him. 15 According to the Lord’s word, we tell you that we who are still alive, who are left until the coming of the Lord, will certainly not precede those who have fallen asleep. 16 For the Lord himself will come down from heaven, with a loud command, with the voice of the archangel and with the trumpet call of God, and the dead in Christ will rise first.

Rv. 20:4-6,4 I saw thrones on which were seated those who had been given authority to judge. And I saw the souls of those who had been beheaded because of their testimony about Jesus and because of the word of God. They[a] had not worshiped the beast or its image and had not received its mark on their foreheads or their hands. They came to life and reigned with Christ a thousand years. 5 (The rest of the dead did not come to life until the thousand years were ended.) This is the first resurrection. 6 Blessed and holy are those who share in the first resurrection. The second death has no power over them, but they will be priests of God and of Christ and will reign with him for a thousand years.

c. The New Testament also contains examples of persons raised form the dead. They were not resurrections such as will occur at the Second Coming and at the Last Judgment, for they later died and will experience the final Resurrection just as others; however, they were prefigures of the final Resurrection.On the other hand, the Resurrection of Jesus was the true and ideal resurrection. When Jesus arose He became “the firstfruits of them that slept” (1 Cor 15:20). His Resurrection was the guarantee of all resurrections of believers: “But God… raised us up together, and made us sit together in heavenly places in Christ Jesus” (Eph 2:6). (See Jn 11:41-44, Lazarus; Lk. 8:41-56, Jairus’ daughter; Lk. 7:12-15, the window’s son; Mt. 27:52, 53 Old Testament saints.)

1 Cor 15:20,20 But Christ has indeed been raised from the dead, the firstfruits of those who have fallen asleep.

Eph 2:6,6 And God raised us up with Christ and seated us with him in the heavenly realms in Christ Jesus,

Jn 11:41-44,41 So they took away the stone. Then Jesus looked up and said, “Father, I thank you that you have heard me. 42 I knew that you always hear me, but I said this for the benefit of the people standing here, that they may believe that you sent me.” 43 When he had said this, Jesus called in a loud voice, “Lazarus, come out!” 44 The dead man came out, his hands and feet wrapped with strips of linen, and a cloth around his face. Jesus said to them, “Take off the grave clothes and let him go.”

Lk. 8:41-56,41 Then a man named Jairus, a synagogue leader, came and fell at Jesus’ feet, pleading with him to come to his house 42 because his only daughter, a girl of about twelve, was dying. As Jesus was on his way, the crowds almost crushed him.43 And a woman was there who had been subject to bleeding for twelve years,[a] but no one could heal her.44 She came up behind him and touched the edge of his cloak, and immediately her bleeding stopped.
45 “Who touched me?” Jesus asked. When they all denied it, Peter said, “Master, the people are crowding and pressing against you.” 46 But Jesus said, “Someone touched me; I know that power has gone out from me.” 47 Then the woman, seeing that she could not go unnoticed, came trembling and fell at his feet. In the presence of all the people, she told why she had touched him and how she had been instantly healed. 48 Then he said to her, “Daughter, your faith has healed you. Go in peace.” 49 While Jesus was still speaking, someone came from the house of Jairus, the synagogue leader. “Your daughter is dead,” he said. “Don’t bother the teacher anymore.” 50 Hearing this, Jesus said to Jairus, “Don’t be afraid; just believe, and she will be healed.” 51 When he arrived at the house of Jairus, he did not let anyone go in with him except Peter, John and James, and the child’s father and mother. 52 Meanwhile, all the people were wailing and mourning for her. “Stop wailing,” Jesus said. “She is not dead but asleep.” 53 They laughed at him, knowing that she was dead. 54 But he took her by the hand and said, “My child, get up!”55 Her spirit returned, and at once she stood up. Then Jesus told them to give her something to eat. 56 Her parents were astonished, but he ordered them not to tell anyone what had happened.

Lk. 7:12-15,12 As he approached the town gate, a dead person was being carried out—the only son of his mother, and she was a widow. And a large crowd from the town was with her. 13 When the Lord saw her, his heart went out to her and he said, “Don’t cry.” 14 Then he went up and touched the bier they were carrying him on, and the bearers stood still. He said, “Young man, I say to you, get up!” 15 The dead man sat up and began to talk, and Jesus gave him back to his mother.

Mt. 27:52-53, 52 and the tombs broke open. The bodies of many holy people who had died were raised to life. 53 They came out of the tombs after Jesus’ resurrection and[a] went into the holy city and appeared to many people.

B. The Nature of the Resurrection.
The Resurrection will be universal. All do not have eternal life, but all have eternal existence. All persons will be resurrected, the just to eternal life, the unjust to eternal condemnation. All will be raised, but not all at the same time (Jn 5:28, 29).

Jn 5:28, 29,28 “Do not be amazed at this, for a time is coming when all who are in their graves will hear his voice 29 and come out—those who have done what is good will rise to live, and those who have done what is evil will rise to be condemned.

1. The Resurrection of Believers (1 Thes 4:13-18; 1 Cor 15:50-57; Rv. 20: 4-6).
The Resurrection of the Church occurs at the Coming of Jesus, immediately prior to the Rapture (1 Thes 4:16). The Believers’ Resurrection is called the “first resurrection”: “Blessed and holy is he that hath part in the first resurrection: on such the second death hath no power…” (Rv. 20:6). It has been taught by some that there will be one general resurrection of the dead and one judgment at which just and unjust are judged. Jesus sometimes mentioned the two resurrections and judgments in the same passage, but a careful reading will reveal that Jesus was not speaking of one general resurrection: “And shall come forth; they that have done good unto the resurrection of life; and they that have done evil unto the resurrection of damnation; (Jn 5:29). Notice that one is a resurrection of life while other is a resurrection of condemnation; they are not the same, nor do they occur at the same time, as Paul and John both elucidate.
It is normal for prophetic perspective to view several related future events as if they were one event. With similar prophetic language, the first and second comings of Jesus are merged in the same passage in Old Testament prophecy (Is 9:6,7; 61:1-3; Dn 12:2). New Testament writers sometimes allude to both the Rapture and Final Coming in the same reference (1Thes 3:13). Both Paul and John make I clear that the Saint’s Resurrection (including the saved remnant of Israel and the Tribulation saints) takes place at Christ’s Coming and before the Millennial Reign (1 Cor 15:51, 52; Rv. 20:4-6; Dan 12:1-2).
That the Saint’s Resurrection is selective is seen in a remarkable statement of the Apostle Paul: “that I may know Him, and the power of His resurrection, and the fellowship of His sufferings, being made conformable unto His death; if by any means I might attain unto the resurrection of dead” (Phil 3:10,11). If there is only one general resurrection for the just and the unjust, would Paul aspire to attain to it? A more literal translation reveals Paul’s full meaning: “… If by any means I might advance to the EARLIER resurrection, which is FROM AMONG the dead” (Phil 3:11, Rotherham). The Greek preposition ek means “out from,” Paul desired to be in the group that would be resurrected at the time of the Rapture; those who would be taken selectively “out from among “ the general mass of the dead; those who would be raised in the EARLIER resurrection (the first resurrection, Rv 20:6). The Greek word for “resurrection”; the double use of the word ek gives added emphasis to the idea that the Resurrection of the Christian believers is one in which they selected for a special awakening. That there will be several orders of resurrection is expressed in another place by Paul: “But every man in his own order: Christ the firstfruits; afterward they that are Christ’s at His coming” (1Cor 15:23).

1 Thes 4:13-18, 13 Brothers and sisters, we do not want you to be uninformed about those who sleep in death, so that you do not grieve like the rest of mankind, who have no hope.14 For we believe that Jesus died and rose again, and so we believe that God will bring with Jesus those who have fallen asleep in him. 15 According to the Lord’s word, we tell you that we who are still alive, who are left until the coming of the Lord, will certainly not precede those who have fallen asleep. 16 For the Lord himself will come down from heaven, with a loud command, with the voice of the archangel and with the trumpet call of God, and the dead in Christ will rise first. 17 After that, we who are still alive and are left will be caught up together with them in the clouds to meet the Lord in the air. And so we will be with the Lord forever. 18 Therefore encourage one another with these words.
1 Cor 15:50-57,50 I declare to you, brothers and sisters, that flesh and blood cannot inherit the kingdom of God, nor does the perishable inherit the imperishable. 51 Listen, I tell you a mystery: We will not all sleep, but we will all be changed— 52 in a flash, in the twinkling of an eye, at the last trumpet. For the trumpet will sound, the dead will be raised imperishable, and we will be changed. 53 For the perishable must clothe itself with the imperishable, and the mortal with immortality. 54 When the perishable has been clothed with the imperishable, and the mortal with immortality, then the saying that is written will come true: “Death has been swallowed up in victory.”[a] 55 “Where, O death, is your victory? Where, O death, is your sting?”[b] 56 The sting of death is sin, and the power of sin is the law. 57 But thanks be to God! He gives us the victory through our Lord Jesus Christ.
Jn 5:29,4 I saw thrones on which were seated those who had been given authority to judge. And I saw the souls of those who had been beheaded because of their testimony about Jesus and because of the word of God. They[a] had not worshiped the beast or its image and had not received its mark on their foreheads or their hands. They came to life and reigned with Christ a thousand years. 5 (The rest of the dead did not come to life until the thousand years were ended.) This is the first resurrection. 6 Blessed and holy are those who share in the first resurrection. The second death has no power over them, but they will be priests of God and of Christ and will reign with him for a thousand years.
1 Thes 4:16, 16 For the Lord himself will come down from heaven, with a loud command, with the voice of the archangel and with the trumpet call of God, and the dead in Christ will rise first.
Rv. 20:6, 29 and come out—those who have done what is good will rise to live, and those who have done what is evil will rise to be condemned.
Isaiah 9:6-7, For to us a child is born, to us a son is given, and the government will be on his shoulders. And he will be called Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace. 7 Of the greatness of his government and peace there will be no end. He will reign on David’s throne and over his kingdom, establishing and upholding it with justice and righteousness from that time on and forever. The zeal of the LORD Almighty will accomplish this.

a. It will be a literal bodily resurrection. This is shown by the Resurrection of Jesus. His resurrected body still bore the prints of the nails and the wound of the sword (Jn 20:26-28); after His Resurrection, Jesus had a body of “flesh and bones” and even took food (Lk. 24:36-43). On the other hand, the body of Jesus was sufficiently glorified that His disciples did not always recognize Him at once. His appearances show that His body was not subject to normal physical limitations (Jn 20:19, 26). That our resurrection reaction will be literal does not mean that all the same molecules of our dead bodies will be recovered; in fact, our body cells are replaced a number of times during our life span without our losing personal identity. Of this one may be certain, that God will recover from the dust a body with a definite relationship to one’s earthly body, but transformed and fashioned to one’s new environment (Phil 3:21).
Paul speaks of death as a sowing of the body as a farmer sows seed. The seed dies, but it contains a life principle by which nature brings forth a new plant of the same genus, species and variety as the original seek. At the Resurrection, cemeteries will be turned into harvest fields (1Cor 15:42-44); and out of the planted earthly bodies, the Lord will raise up resurrection bodies that are identified with the earthly body, but which are transformed with a likeness to Christ’s resurrection body. Believer’s bodies will be changed (1 Cor 15:52), but each will have a relationship to the earthly body. The resurrection body will not be the earthly body merely resuscitated; but the likeness of the earthly body glorified. It appears from the identification of Moses and Elijah on the Mount of Transfiguration and of Jesus after His Resurrection that our resurrection bodies will retain their personal identity.

b. The resurrection body will be God-given. “But God giveth it a body as it hath pleased him…” (1 Cor 15:38). This is in answer to a hypothetical question “… How are the dead raised up? And with what body do they be conceived by human intellect. Christ’s Resurrection is the great miracle of our Gospel. We do not explain it. We accept it as Divine revelation. In the same manner we accept bodily resurrection as a miracle of Divine power and wisdom. If we accept Christ’s Resurrection (which is one of the best attested events of history), we should have no problem with the acceptance of our final resurrection; for we shall be raised up by the same Omnipotent God who raised up Jesus form the dead.

1 Cor 15:38,38 But God gives it a body as he has determined, and to each kind of seed he gives its own body.

c. The believer’s resurrection body will be immortal and incorruptible (1 Cor 15:42). The Scriptures never speak of the immortality of the soul. The believer now has eternal life, but he dwells in a mortal body. All men have eternal existence. Only believers who shall experience “The First Resurrection” will receive immortal and incorruptible bodies (1 Cor 15:42).

1 Cor 15:42, 42 So will it be with the resurrection of the dead. The body that is sown is
perishable, it is raised imperishable;

d. The resurrection body will be a celestial body (1Cor.15:40). Our earthly bodies are suited to this present earthly environment. The resurrection body will be suited to both the new heavens and the new earth, as well as to the millennial earth. Like the body of Jesus, it will be able to come and go between Heaven and the earth.

1Cor.15:40, 40 There are also heavenly bodies and there are earthly bodies; but the splendor of
the heavenly bodies is one kind, and the splendor of the earthly bodies is another.

e. The resurrection body will be a powerful body. “… It is sown in weakness, it is raised in power…” (1 Cor 15:43). The contrast here expressed indicates that the new capacities of the resurrection body will be inconceivably and inexpressibly greater than those of any earthly human body. The events recorded of angels are a preview of the capacities of resurrected saints (Mt. 22:29,30).

1 Cor 15:43, 43 it is sown in dishonor, it is raised in glory; it is sown in weakness, it is raised in
power;

Mt. 22:29,30, 29 Jesus replied, “You are in error because you do not know the Scriptures or the
power of God. 30 At the resurrection people will neither marry nor be given in marriage; they will be like the angels in heaven.

f. The resurrection body will be a glorious body. “It is sown in dishonor, it is raised in glory…” (1 Cor 15:43). The resurrected body will be as glorious as the decaying earthly body can be inglorious. Jesus promised, “Then shall the righteous shine forth as the sun in the kingdom of their Father” (Mt 13:43). The above words of Jesus suggest for the saints the glory that He manifested on the Mount of Transfiguration: “And was transfigured before them: and His face did shine as the sun, and his raiment was white as the light” (Mt 17:2). Jesus prayed for us, “And the glory which Thou gavest me I have given them; that they may be one, even as we are one…” (Jn 17:22). After speaking of the Resurrection, Daniel said, “And they that be wise shall shine like the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever” (Dn 12:3)

Mt 13:43,43 Then the righteous will shine like the sun in the kingdom of their Father.
Whoever has ears, let them hear

Mt 17:2, 2 There he was transfigured before them. His face shone like the sun, and his clothes
became as white as the light.

Jn 17:22,22 I have given them the glory that you gave me, that they may be one as we are
one—Dn 12:3, 3 Those who are wise[a] will shine like the brightness of the heavens,
and those who lead many to righteousness,like the stars for ever and ever.

2. The Resurrection of Unbelievers (Rv 20:5, 12, 13, 14; Jn. 5:28, 29; Dn 12:2; Acts 24:15).
The Bible does not reveal specifically the state or nature of the resurrection bodies of the unrighteous; but it may be assumed that they will be bodies subject to corruption or ruin. Jesus said, “And fear not them which kill the body, but are not able to kill the soul: but rather him which is able to destroy [Gr., apollumi, “to ruin utterly”] both BODY and soul in hell [Grk., gehenna]” (Mt 10:28). The bodies of the unrighteous dead will suffer “utter ruin” eternally. (See 2 Thes 1:8,9.) The unrighteous are not resurrected at the time of Christ’s Second Coming, but after the Millennial Reign of Christ (Rev. 20:5).

Mt 10:28,28 Do not be afraid of those who kill the body but cannot kill the soul. Rather, be afraid of the One who can destroy both soul and body in hell.

2 Thes 1:8,9,8 He will punish those who do not know God and do not obey the gospel of our Lord Jesus. 9 They will be punished with everlasting destruction and shut out from the presence of the Lord and from the glory of his might

Rev. 20:5, 5 (The rest of the dead did not come to life until the thousand years were ended.) This is the first resurrection.

C. The Time of the Resurrection.
The order of resurrections is as follows:

1. The Resurrection of Jesus (Mt 28:1-10; Mk 16:1-14; Lk. 24:1-39; Jn 20:1-17).

2. A Resurrection of saints of the Old Testament (Mt. 27:52, 53).

3. The Resurrection of the Church saints at the Rapture (Jn 14:3; 1 Thes 4:16, 1 Cor 15:52).

4. The Resurrection of the two witnesses of Revelation 11:12, during the tribulation period.

5. The Resurrection of the saints of Israel and of the Tribulation saints who are witnesses for Christ and who do not worship the Beast (Rv. 20:4-6; Dn 12:1,2).

6. The Resurrection of the unrighteous.
This will occur after the Millennial Reign of Christ. They will be resurrected to stand before the Great White Throne (Rv 20:5,11-14).
Mt 28:1-10,After the Sabbath, at dawn on the first day of the week, Mary Magdalene and the other Mary went to look at the tomb.2 There was a violent earthquake, for an angel of the Lord came down from heaven and, going to the tomb, rolled back the stone and sat on it. 3 His appearance was like lightning, and his clothes were white as snow. 4 The guards were so afraid of him that they shook and became like dead men.5 The angel said to the women, “Do not be afraid, for I know that you are looking for Jesus, who was crucified.6 He is not here; he has risen, just as he said. Come and see the place where he lay. 7 Then go quickly and tell his disciples: ‘He has risen from the dead and is going ahead of you into Galilee. There you will see him.’ Now I have told you.” 8 So the women hurried away from the tomb, afraid yet filled with joy, and ran to tell his disciples. 9 Suddenly Jesus met them. “Greetings,” he said. They came to him, clasped his feet and worshiped him. 10 Then Jesus said to them, “Do not be afraid. Go and tell my brothers to go to Galilee; there they will see me.”
Mk 16:1-14,When the Sabbath was over, Mary Magdalene, Mary the mother of James, and Salome bought spices so that they might go to anoint Jesus’ body. 2 Very early on the first day of the week, just after sunrise, they were on their way to the tomb 3 and they asked each other, “Who will roll the stone away from the entrance of the tomb?” 4 But when they looked up, they saw that the stone, which was very large, had been rolled away. 5 As they entered the tomb, they saw a young man dressed in a white robe sitting on the right side, and they were alarmed. 6 “Don’t be alarmed,” he said. “You are looking for Jesus the Nazarene, who was crucified. He has risen! He is not here. See the place where they laid him. 7 But go, tell his disciples and Peter, ‘He is going ahead of you into Galilee. There you will see him, just as he told you.’” 8 Trembling and bewildered, the women went out and fled from the tomb. They said nothing to anyone, because they were afraid.[a]
Mt. 27:52, 53, 52 and the tombs broke open. The bodies of many holy people who had died were raised to life. 53 They came out of the tombs after Jesus’ resurrection and[a] went into the holy city and appeared to many people.
Jn 14:3,3 And if I go and prepare a place for you, I will come back and take you to be with me that you also may be where I am.
Revelation 11:12,12 Then they heard a loud voice from heaven saying to them, “Come up here.” And they went up to heaven in a cloud, while their enemies looked on.
''');

final _ls_Lesson1 = Lessons(
    lessonNumber: 1,
    lessonTitle: 'How should a Christian view climate change?',
    lessonBody:
        '''Objectives: To teach and equip the believers about current issues that challenge our faith and how to address them in a biblical and balance understanding.

Introduction:

Welcome back to Onelife! As our lessons are in progress and all of us are blessed and gained many insights from it, this year we decided to go deeper, practical, and more biblical. Considering the current events and issues that we Christians are facing today, we need to be equipped and able enough to answer all these mind bugling questions with the help of the Holy Spirit and our personal discovery from God Word. This is the reason why we are so passionate to venture this new journey of Onelife this year. Welcome to our new series called " Life Issues Series" .

Today, we will start with the issue about Climate change that to many this is still a confusing and vague idea. So what is a climate change?

cli·mate change
noun
1. a change in global or regional climate patterns, in particular a change apparent from the mid to late 20th century onwards and attributed largely to the increased levels of atmospheric carbon dioxide produced by the use of fossil fuels. ( Rent21.org)
What Is Causing Earth's Climate to Change?

Some causes of climate change are natural. These include changes in Earth's orbit and in the amount of energy coming from the sun. Ocean changes and volcanic eruptions are also natural causes of climate change.
Most scientists think that recent warming can't be explained by nature alone. Most scientists say it's very likely that most of the warming since the mid-1900s is due to the burning of coal, oil and gas. Burning these fuels is how we produce most of the energy that we use every day. This burning adds heat-trapping gases, such as carbon dioxide, into the air. These gases are called greenhouse gases. ( NASA.gov )

The bible also gives us a glimpse on this issue of climate change. Here is one of those scripture references that we can consider.

Luke 21:25-26 NIV
[25] “There will be signs in the sun, moon and stars. On the earth, nations will be in anguish and perplexity at the roaring and tossing of the sea. [26] People will faint from terror, apprehensive of what is coming on the world, for the heavenly bodies will be shaken.
"...upon the earth distress of nations in perplexity at the roaring of the sea and waves..."

Question: "How should a Christian view climate change?
What does the Bible say about climate change?"

Here is an article that we see it has a balance and a biblical way of approach on this topic. Our sources are stated at the bottom of this page.

Answer:
It is interesting to note how the phrase "climate change" is replacing "global warming" as the catch phrase of environmentalism. Some scientists/climatologists are certain that human activity, primarily greenhouse gas emissions, is impacting the environment. What they are not certain about is precisely what the impact will be. A couple of decades ago, "global cooling" was the fear, with warnings of a new ice age being the primary scare tactic. While most scientists/climatologists today believe that global warming is the primary risk, uncertainty has led to "climate change" being used as a less specific warning. Essentially, the climate change message is this: greenhouse gas emissions are damaging the environment, and, while we are not certain what the effect will be, we know it will be bad.

Climatologists, ecologists, geologists, etc., are unanimous in recognizing that the earth has gone through significant temperature/climate changes in the past. Despite the fact that these climate changes were obviously not caused by human activity, many of these same scientists are convinced that human activity is the primary cause of climate change today. Why?
There seem to be three primary motivations.

First, some truly and fully believe the greenhouse gas emissions are causing climate change. They honestly examine the data and come to that conclusion.

Second, some hold to the climate change mindset with an almost religious fervor. Many within the environmentalist movement are so obsessed with protecting "Mother Earth" that they will use any argument to accomplish that goal, no matter how biased and unbalanced it is.

Third, some promote the climate change mentality for financial gain. Some of the strongest proponents of climate change legislation are those who stand to have the greatest financial gain from "green" laws and technologies. Before the climate change mindset is accepted, it should be recognized that not everyone who promotes climate change is doing so from an informed foundation and pure motives.

How, then, should a Christian view climate change?

We should view it skeptically and critically, but at the same time honestly and respectfully. Most importantly, though, Christians should look at climate change biblically. What does the Bible say about climate change? Not much. Likely the closest biblical examples of what could be considered climate change would be the end times disasters prophesied in Revelation 6–18. Yet these prophecies have nothing to do with greenhouse gas emissions; rather, they are the result of the wrath of God, pouring out justice on an increasingly wicked world. Also, a Christian must remember that God is in control and that this world is not our home. God will one day erase this current universe (2 Peter 3:7-12)

2 Peter 3:7-12 NIV
[7] By the same word the present heavens and earth are reserved for fire, being kept for the day of judgment and destruction of the ungodly. [8] But do not forget this one thing, dear friends: With the Lord a day is like a thousand years, and a thousand years are like a day. [9] The Lord is not slow in keeping his promise, as some understand slowness. Instead he is patient with you, not wanting anyone to perish, but everyone to come to repentance. [10] But the day of the Lord will come like a thief. The heavens will disappear with a roar; the elements will be destroyed by fire, and the earth and everything done in it will be laid bare. [11] Since everything will be destroyed in this way, what kind of people ought you to be? You ought to live holy and godly lives [12] as you look forward to the day of God and speed its coming. That day will bring about the destruction of the heavens by fire, and the elements will melt in the heat.

and replace it with the New Heavens and New Earth (Revelation 21–22). How much effort should be made "saving" a planet that God is eventually going to obliterate and replace with a planet so amazing and wonderful that the current earth pales in comparison?

Is there anything wrong with going green? No, of course not. Is trying to reduce your carbon footprint a good thing? Probably so. Are solar panels, wind mills, and other renewable energy sources worth pursuing? Of course. Are any of these things to be the primary focus of followers of Jesus Christ? Absolutely not! As Christians, our focus should be proclaiming the truth of the gospel, the message that has the power to save souls. Saving the planet is not within our power or responsibility. Climate change may or may not be real, and may or may not be human-caused. What we can know for certain is that God is good and sovereign, and that Planet Earth will be our habitat for as long as God desires it to be.

So is climate change a thing to fear? No. It is a necessary part of the process that God set in train thousands of years ago and from which he will save his people. He has told us two further things in the scriptures from which we can be encouraged. He says, "When these things begin to take place, look up and raise your heads because your redemption is drawing near." (Luke 21:28), and, "...when you see all these things, you know that he is near, at the very gates." (Matthew 24:33), so take heart and be prepared.

Psalm 46:2-3,
"Therefore we will not fear, though the earth give way and the mountains fall into the heart of the sea, though its waters roar and foam and the mountains quake with their surging."


Lessons to Ponder:

1. After learning this lesson, how do you rate your understanding about the issue of climate change?

2. Share at least three practical steps to help solving this problem.

3. In what way that climate change becomes a great tool of sharing the good-news to the people?
''');

final _ls_Lesson2 = Lessons(
    lessonNumber: 2,
    lessonTitle: 'How to Manage Anxiety and Stress in a Biblical way',
    lessonBody:
        '''Objectives: To teach and Equip the believers about managing the danger of chronic anxiety and stress in a biblical way.

Introduction:
“Anxiety's like a rocking chair. It gives you something to do, but it doesn't get you very far.” ― Jodi Picoult, Sing You Home

According to Glen Ryswyk, an Assemblies of God chaplain and clinical director of the Christian Family Counseling Center in Lawton, Okla., says "stress is a symptom of a modern culture obsessed with performance and perfection."

He added,
"Since 2007, the annual "stress in America" survey by the American Psychological Association has shown a nation struggling under a heavy load of tension and anxiety.

According to the most recent study, published last year, 7 in 10 Americans say stress levels interfere with their physical and mental well-being, causing irritability, anger, fatigue, feelings of being overwhelmed, sleep loss and eating problems.

The biggest sources of stress cited are money (69 percent), work (65 percent), the economy (61 percent), family responsibilities (57 percent), relationships (56 percent), family health problems (52 percent) and personal health concerns (51 percent)."

Christian therapist and trauma specialist H. Norman Wright says
" stress becomes problematic when it is chronic.

According to the National Institutes of Mental Health, prolonged stress is a serious health risk. Stress releases natural hormones, including adrenaline and cortisol. These fight-or-flight chemicals are designed to aid the body in short-term emergencies. They increase the heart rate, elevate blood pressure, boost sugar levels, and redirect energy from other functions, such as digestion and immune responses.
Chronic stress can keep the body's chemical switches on, setting in motion a chain reaction that may throw virtually every system off balance. Long-term stress is linked to depression, anxiety disorder, diabetes, high blood pressure, heart disease, sleep disturbances, weight gain, memory loss and concentration impairment.

Wright says stress can be a spiritual drain as well.
"You can get to a place where you have no reserves—you're running on empty," Wright says. "It can lead to burnout and crisis in every area, including your spiritual life." Yet Wright says stressed-out Christians already have access to the relief they need. "We have the resources for dealing with stress," Wright says. "We have prayer and the promises of Scripture. Many times we're stressed because we're trying to manage it all ourselves. We aren't relying on God or releasing it to Him."

What are the Biblical examples of people who experienced the same way?

Jacob
In Genesis 32, Jacob is returning home after many years away. One of the reasons he had left home was to escape the anger of his brother, Esau, from whom Jacob had stolen the birthright and blessing from their father. Now, as Jacob nears his homeland, he hears that Esau is coming to meet him with 400 men. Jacob is immediately anxious, expecting a horrible battle with his brother. In this case, the anxiety is caused by a broken relationship and a guilty conscience.

Hannah
In 1 Samuel 1, Hannah is distressed because she was unable to conceive children and she was being taunted by Peninnah, her husband's other wife. Her distress is caused by unfulfilled desires and the harassment of a rival.

Queen Esther
In Esther 4, the Jewish people are anxious because of a royal decree allowing them to be massacred. Queen Estheris anxious because she was planning to risk her life on behalf of her people. Fear of death and the unknown is a key element of anxiety.


PRINCIPLES FROM THE BIBLE TO OVERCOME ANXIETY AND STRESS

King David
Psalm 42:5 NIV
[5] Why, my soul, are you downcast? Why so disturbed within me? Put your hope in God, for I will yet praise him, my Savior and my God.

Take time to talk to yourself.
Learn to entrust everything to Him
Worship is the key

Jesus
Matthew 11:28-30 NIV
[28] “Come to me, all you who are weary and burdened, and I will give you rest. [29] Take my yoke upon you and learn from me, for I am gentle and humble in heart, and you will find rest for your souls. [30] For my yoke is easy and my burden is light.”

Great Invitation
Offering is for everyone
God's remedy
Lesson time

Paul
Philippians 4:6-7 NIV
[6] Do not be anxious about anything, but in every situation, by prayer and petition, with thanksgiving, present your requests to God. [7] And the peace of God, which transcends all understanding, will guard your hearts and your minds in Christ Jesus.

Prayer
Petition
Thankful heart
Pour out your case

James
James 1:2-4 NIV
[2] Consider it pure joy, my brothers and sisters, whenever you face trials of many kinds, [3] because you know that the testing of your faith produces perseverance. [4] Let perseverance finish its work so that you may be mature and complete, not lacking anything.

Have a positive spirit
Learn to look at in a bigger picture

Luke
Luke 21:19 NIV
[19] Stand firm, and you will win life.

Don't give up!
You are an overcomer!


PRACTICAL HELPS IN MANAGING ANXIETY AND STRESS

36 Christian Ways to Reduce Stress
( 1st Holistic.com)
1. Pray
2. Go to bed on time.
3. Get up on time so you can start the day unrushed.
4. Say "No," to projects/activities that won't fit into your time schedule, or that will compromise your mental health.
5. Delegate tasks to capable others.
6. Simplify and un-clutter your life.
7. Less is more. (Although one is often not enough, two are often too many.)
8. Allow extra time to do things and to get to places.
9. Pace yourself. Spread out big changes and difficult projects over time; don't lump the hard things all together.
10. Take one day at a time.
11. Separate worries from concerns. If a situation is a concern, find out what God would have you to do and let go of the anxiety. If you can't do anything about a situation, forget it.
12. Live within your budget.
13. Have backups; an extra car key in your wallet, an extra house key buried in the garden, extra stamps, etc.
14. K. M. S. (Keep Mouth Shut.) This single piece of advice can prevent an enormous amount of trouble.
15. Do something for the Kid in You everyday.
16. Carry a Bible with you to read while waiting in line.
17. Get enough exercise.
18. Eat right.
19. Get organized so everything has its place.
20. Listen to a tape while driving that can help improve your quality of life.
21. Write thoughts and inspirations down.
22. Everyday, find time to be alone.
23. Having problems? Talk to God on the spot. Try to nip small problems in the bud. Don't wait until its time to go to bed to try and pray.
24. Make friends with Godly people.
25. Keep a folder of favorite scriptures on hand.
26. Remember that the shortest bridge between despair and hope is often a good "Thank you Jesus!"
27. Laugh.
28. Laugh some more!
29. Take your work seriously, but yourself not at all.
30. Develop a forgiving attitude (most people are doing the best they can).
31. Be kind to unkind people (they probably need it the most).
32. Sit on your ego.
33. Talk less; listen more.
34. Slow down.
35. Remind yourself that you are not the general manager of the universe.
36. Every night before bed, think of one thing you're grateful for that you've never been grateful for before.


Lessons to Ponder:

1. In your own opinion what is anxiety and stress?

2. Share some of your experience to the group and tell about how
did you go about it.

3. To what extent can anxiety and stress works for you and
destroys you.

4. What passage in the bible that uplifts your faith when anxiety
tries to attack you.
''');

final _mt_Lesson1 = Lessons(
    lessonNumber: 1,
    lessonTitle: 'Mentoring The Inner Life',
    lessonBody: '''Nothing to prove is a state of deep security in God.
Nothing to lose is a state of absolute surrender to God.
Nothing to hide is a state of true integrity before God.

The root cause of our inability to reach this blessed state is our lack of inner security. Insecurity causes us to fall into a performance trap. Performance drivenness leads to fragile egos. It causes us to make vain comparisons. Envy and Jealousy rear their ugly heads.

Envy and jealousy are not the same. Envy is desiring what others have. Because we don’t have it. Jealousy happens when others have what we have - but more!

As a result, we often find it difficult to celebrate others' strengths and successes. cain measured his offering against Abel's and couldn't understand why God rejected his offering since both were " first-fruits" offerings. in his insecure jealousy, he murdered Abel. Pride got in the way.

The key to living with nothing to prove is humility.

Philippians 2:3 NIV
[3] Do nothing out of selfish ambition or vain conceit. Rather, in humility value others above yourselves,

If there were something to prove, it should be that God's surpassing strength is made perfect in our weakness.

In life, Humility and Surrender walk hand in hand in a common pilgrimage.

Yet we struggle to give up our rights and desires. Insecurity leads to a fear of full surrender. Instead, we seek in vain to find our security in acquiring, possessing, and hoarding. In maintaining control. Losing for the sake of Christ begins to terrify us. We don't mind making sacrifices but we are afraid of fully surrendering ourselves to God. We forget that surrender is not about giving up, it's about "giving in to God.

In truth, we have become possessed by our possessions. Controlled by our need for control. We miss the point that true security comes when we find satisfaction only on Christ. When we come to this realization, we can surrender all and live nothing to lose.

When Christ is absolutely everything, then Christ's alone is absolutely enough.

Finally insecurity also causes us to camouflage our sins with artificial, guilt soothing human constructs. We hide our heartaches, sins and pains behind smiling masks and ministry activities. We focus on temporarily managing our sins instead of completely repenting of them and thus finding our freedom in the mighty transformation of Jesus.

When we walk in the true repentance then there is nothing to hide.

D.L. Moody once said, "Moses spent forty years thinking he was somebody. He spent the next forty years learning he was nobody, He spent the last forty years discovering what God can do to a nobody"

Indeed God can do wonderful things with a nobody. A nobody with nothing to prove, nothing to lose and nothing to hide.

Questions for Reflections

1. Read 1 Samuel 10-12. What was King Saul trying to " prove" and "hide" in
these chapters?

2. Read Philippians 3:7-10. What was Paul once aspirations?
3. What does " Nothing to Prove, nothing to lose, nothing to hide" mean to you in your present circumstances?
''');

final _mt_Lesson2 = Lessons(
    lessonNumber: 2,
    lessonTitle: 'Mentoring With The End in Mind',
    lessonBody: '''(Perspective, Posture, Pragmatics and Power)

Begin with the end in mind.

In Christian mentoring, we mentor with a purpose. The best mentors do not focus on the programme but on the purpose. That's mentoring with the end in mind. There are four mentoring objectives towards that end.

We mentor for wisdom in thinking ( perspective ), brokenness in attitude ( posture),
Competence in both life - skills and ministry - skills (pragmatics) and the experience of God's daily presence in our lives (power).

A Certain Kind of Perspective
Our worldview must undergo a radical re-orientation. We need to encounter the truth, experience the truth and embrace the truth. This happens when we immerse our minds in Scripture and tutor our hearts to obey it.

We are thus being mentored by the Scripture.

There is no short cut to this renewing of the mind. It is a daily investment. Our perspectives are increasingly informed by the Scriptures. We seek to have a perspective shaped exclusively by Scripture and by a faithful obedience to it.

A Certain Kind of Posture
It is curious to note that our Lord was never impressed with the knowledge of the Scribes and Pharisees. He was looking out for something else beyond the knowing. He was looking for the heart. ( Matthew 13:1-23)

There is a certain receptivity and meekness that marks true disciples ( Isaiah 66:2). But meekness is not weakness. This is the paradox. There is a profound humble-boldness in a life with the right focus on God.

A certain kind of posture is this about
brokenness of heart before God,
a meekness of heart in God and
an openness of heart to God.

A Certain Kind of Pragmatics
Pragmatics is intentional skill development - a disciplined and growing competence in both life-skills and ministry-skills. Disciples have a growing competency.

Life is to short to be lived without thoughtful, skilled competence.

When tutored individuals encounter difficult situations, they have the emotional reservoir and capacity to deal wisely with them - not react to them. And coaching these skills, not just in ministry but also in life, is what holistic is about.

A Certain Kind of Power
Power belongs to the Lord. It is a divine attribute. But in man, it is not. Power in man is by product in God. It is a given. Unfortunately, it is in the disposition of fallen humanity to either grab power through pride or to shun God's power through unbelief or both!

Because spiritual power is intoxicating, God's hedge for this is Love.

When we are more enamoured of power than love, we have lost our focus. True spiritual power is released from on high to build His kingdom. In fact, God's very presence is His very power! We thus seek to abide in His daily presence. And be mentored to receive and release power judiciously in love.

Questions for Reflections

1. Do you have something to help you grow regularly in the Scriptures?
2. Do you have the posture of humble-boldness in your life? In what way?
3. What life - skills and ministry skills would you need most in the next lap of your life?
''');

final _mt_Lesson3 = Lessons(
    lessonNumber: 3,
    lessonTitle: 'Three Arenas of Mentoring',
    lessonBody: '''(The Devotional, Domestic, and Developmental Life)

True mentoring is holistic and deep.

In mentoring, careful attention must be given to three hidden substructures in a person's life. These inner arenas often go unnoticed because they are private. Often they are hidden from public scrutiny. As such, these private arenas are easily neglected. Or else superficially examined with a cursory glance.

When this happens, serious fault- lines develop.

And if so, and we are not careful,they could be used by the devil to destroy the credibility and effectiveness of God's servants. Thus, while skill development is often given more attention in mentoring, there are deeper arenas that must nonetheless be emphasized. True mentoring is indeed holistic and deep.

We thus give due attention to the three inner arenas of the mentoree's life. The wise mentor helps to cultivate the devotional life, deepen the domestic life and empower the developmental life.

Cultivating the Devotional Life
Quiet time does not automatically become easier as one grows older. In fact, it becomes harder. Why? Because one can browse through God's Word quickly and pic up a thought or two without much meditation and intimacy with God.

One can have the routine and the mere discipline without the encounter and the wonder. One can read the Word of God but miss the God of the Word. One can go on serving the Lord without devotion. Christian life and ministry can be faked all to easily. But God calls us to be authentic!.

At the of authentic discipleship is a deep devotional life!

Deepening the Domestic Life
Appearances can be deceiving. Behind the scene of a leader's life is the family. One can deceptively a double life - an angel in church but a monster at home! A person cannot grow holistically because of such inconsistencies. Once this happens, hypocrisy sets in. And the double life takes over.

Another possible problem scenario is having an unsupportive spouse who prevents one from serving and fulfilling God's destiny in one's life. Often deep roots of woundedness Must be surfaced and dealt with. It's sad that such a couple would find great difficulty serving as one. Mentoring the domestic life of the family is vital.

Empowering the Development Life.
People tend to settle in their comfort zones. Often people fail to overcome areas of weakness due to fear of vulnerability or failure. This applies to many arenas of life. It could apply to the need for physical exercise. Or personal growth through reading. Or growth in different ministry competences and skills.

As long as the leader settles for the status quo, stagnation and lack of personal effectiveness sets in. We not neglect to chart the necessary developmental growth areas to work on. We must aim to help our mentoree's come out of their comfort zones!

Let's get out of our comfort zones. Let's grow in depth in all arenas of our lives. And mentor likewise. With a mentoring that is deep and holistic.

Questions for Reflection.

1. What causes one to live a double life? Why is consistency so difficult?

2. What is one common area of neglect in your life now?

3. What can do you do today to get out of your comfort zone and grow?
''');
final _mt_Lesson4 = Lessons(
    lessonNumber: 4,
    lessonTitle: 'Four Steps in Mentoring',
    lessonBody:
        '''Discover the Truth, Apply it, Reap the Benefits and Pass It On!
(a material from the Mentoring Paradigm book of Dr. Edmund Chan)

Mentoring is not just an impartation of knowledge. It's about living a life!

Mentoring is an impartation of life and convictions. It is about living a life and sharing the journey. It also involves imparting values and vision, creating a new empowering belief system. All this takes time. It involves a complex process of growth. And growth takes time. And skill.

As such, many feel unqualified to mentor others. Nonetheless, there are four simple steps to help us start the journey. Don't just take one (Discover the truth ) and immediately jump to step four ( Pass it on ). That's merely an impartation of knowledge.

Don't truncate the process.

The secret of life and value impartation lies in step two (Apply the Truth ) and step three ( Reap the benefits ). Only then can we share from the depth and authenticity of our lives. So here are the four fundamental steps to effective mentoring.

Discover the Truth
Discovery is the inspiration of living. Learning to discover is the perspiration. The first step in mentoring is to learn something good. Something worthwhile to pass on. Something that has been life - changing for you. To pass on the truth, we must first know the truth.

Truth serves as an anchor in our lives.

Without truth, we are adrift in a world of confusions and compromise. Ravi Zacharias insightfully commented that "we live in an unseen world where truth is the most precious commodity. This ultimate truth is found in the Word of God."( John 17:17 )

Apply the Truth
Get this; Truth doesn't change lives. Rather, it is truth applied that changes lives!
Jesus said that whoever hears His Words and does them is like the wise man who builds his house upon the rock ( Matthew 7:24 )

Truth can be insightful and inspiring. But without action and obedience, it has no power. We must not truncate the application and jump straight to passing it on. Other wise we reproduce after our kind : a superficial generation of those who eloquently pass on what they have not effectively applied.

Reap the Benefits
The benefits of truth applied must first be experienced so as to impart truth with authenticity. When that happens, we can teach what we practice and not run the danger of teaching others what we are not practicing ourselves.

Howard Hendricks, Professor of Dallas Theological Seminary said; " what I hear, I Forget. What I see, I remember. What I do, I understand. When I understand, I Changed." Truly what I apply brings about " understanding and transformation.
Pass it On
Ultimately, our legacy in mentoring is to see multiplication of lives. In the Old Testament, God's wondrous working was orally transmitted from one generation to the next. There was multiplication from one generation to another.

If we keep discovering the truth, applying the truth, and reaping the benefit, then we can pass on a legacy of truth from one generation to the next.

FOUR steps , Not TWO

Questions for Reflections

1. Why is " FOUR" streps, not "TWO" important?
2. Of the four steps, which speaks to your life the most? Why?
3. What are some life-changing truths that you have discovered?
Lesson 5: Philosophy of A Mentoring Leadership:
Think Big, Start Small, Build Deep
(a material from the Mentoring Paradigm book of Dr. Edmund Chan)

It is a daring philosophy of leadership.

“Think Big, Start Small, Build Deep” is a compelling watchword that comes up often in our QC Time. For us, it is a reminder to stop comparing. And to stay true and courageous to our specific calling from God. It cultivates a mentoring leadership committed to developing leaders who build to last.

“Think Big, Start Small, Build Deep” first challenges us to pursue with visionary courage our dreams from God. Yet it calls for the inner security to not despise small things. This is an important tension to balance. We are creatures of extremes. We tend to gravitate to one and ignore the other. It is both-and and not either-or!

Finally, it highlights the need for godly wisdom, in the exercise of wise leadership, to build deep. Thus, “think big, start small, build deep” is decidedly provocative in its grand sweep.


The Courage To Think Big
It first calls us to boldly dream BIG dreams IN God. There is a difference between dreaming big dreams FOR God and dreaming big dreams IN God. The former can be mere presumptuousness; the latter is rooted in the holy calling and divine promises.

Our View of God determines our work for Him.

Our God is a God of the impossible. Is anything too difficult for Him? By His word, the heavens and earth were created. Our God is an awesome God. Yet we tiptoe around God’s throne and ask for the mundane.

If God is too small in our eyes, our work will be minute. But if He is bigger than the universe, then is anything too difficult for Him? Let’s dare to do something so big that if God is not in it, we are doomed to fail.


The Security To Start Small
On the other hand, this guiding philosophy of leadership calls us to have an inner security to start small. Some great movements of God have an inconspicuous genesis. It takes a quiet disposition rested enough in God to begin on a small scale.

God is never in a hurry.

In His eternal timeline, everything will fall in its rightful place. While we think big, we must be willing to start small.. Jesus said that the Kingdom of God is like a mustard seed (Matt 13:31-32). Start with what God has already blessed us with and given to us.

The Wisdom To Build Deep
Finally, this philosophy of leadership holds the tension by calling us to keep working on the fundamentals. Depth and influence are more efficacious in the long run than mere breadth and impact. We’ve got to get the fundamentals right!

Ultimately, what really counts is true depth.

Whether it’s starting a movement or the discipling of lives, building deep is anchored in fulfilling God’s fundamental calling and mission. It’s fundamentally about developing a biblical worldview and depth of character. It’s the wisdom of building to last.

Questions for Reflection

1. What do you think of this “Think Big, Start Small, Build Deep” philosophy?
2. Why is the philosophy so important?
3. There are three parts to the philosophy. Which part speaks to you the most and what practical steps will you take to put it into practice?
''');

